window.__Q=window.__Q||{};window.__Q["tcm/8/A2"]=[{"q":"尿毒症患者的呼吸系统变化中，最不可能出现的是","o":["Kussmaul呼吸","浅快呼吸","纤维素性肺炎","肺水肿","呼气有氨味"],"a":1,"e":"尿毒症时代谢性酸中毒刺激呼吸中枢，出现深大的Kussmaul呼吸；尿素随唾液排出分解为氨，故呼气带氨味；尿毒症性肺炎本质为纤维蛋白性炎，并常伴肺水肿。浅快呼吸见于胸痛、肺顺应性降低等限制性通气障碍，不是尿毒症典型表现。Kussmaul呼吸属酸中毒代偿，纤维素性肺炎即尿毒症性肺炎"},{"q":"患者，女，80岁。近三年来，记忆力逐渐下降，经常忘记自己刚刚做过的事情。脑CT发现大脑体积缩小，颈内动脉局部狭窄。患者可能患有","o":["颈动脉粥样硬化致脑萎缩","颈动脉粥样硬化致脑水肿","颈动脉玻璃样变致脑萎缩","风湿性颈动脉炎","风湿性脑病"],"a":0,"e":"颈内动脉起始部是粥样斑块好发部位，管腔狭窄使脑组织长期缺血，发生脑萎缩，临床表现为记忆力下降乃至痴呆。脑水肿是急性缺血或中毒的早期反应，不会呈三年缓慢进展。玻璃样变发生于细小动脉，属高血压性改变，颈内动脉为中动脉，病变为粥样硬化；风湿性颈动脉炎罕见"},{"q":"患儿，女，5岁。1天前出现高热、头痛、呕吐、外周血白细胞增高，全身出现黏膜瘀点、瘀斑、周围循环衰竭、同时伴有急性肾上腺衰竭症状。此病人首先怀疑","o":["普通型流脑","暴发型流脑","急性支气管炎","慢性咽炎","脑脓肿"],"a":1,"e":"暴发型流脑表现为败血症性休克，短期内出现广泛瘀点瘀斑、周围循环衰竭，并可因双侧肾上腺出血坏死出现沃-弗综合征，与本例吻合。普通型流脑以发热、头痛、脑膜刺激征为主，血压多正常。脑脓肿为局灶性占位，无全身瘀斑；急性支气管炎不引起循环衰竭"},{"q":"患者，女，45岁，体检发现乳腺癌。病检见癌细胞突破基膜进入间质，呈实性条索、小梁或团巢状，无明显腺样结构，实质与间质大致相当，此癌是","o":["导管内癌","小叶原位癌","浸润性小叶癌","神经内分泌癌","非特异型浸润癌"],"a":4,"e":"癌细胞突破基膜侵入间质、呈实性条索或团巢而缺乏腺样结构，符合非特殊型浸润癌，是乳腺癌最常见类型。导管内癌与小叶原位癌均未突破基膜，属原位病变。神经内分泌癌需见器官样巢状排列及神经内分泌标记。实质与间质比例相当只是浸润性癌的形态描述，不是独立类型"},{"q":"感染性休克患者，其血压进行性下降的机制为","o":["总血容量的减少","毛细血管容量的减少，血浆外渗","体液量的减少","毛细血管容量增加，血浆外渗","容量血管收缩，毛细血管通透性增高"],"a":3,"e":"感染性休克时内毒素使毛细血管前括约肌松弛而微静脉仍收缩，毛细血管床容量显著增加，同时通透性升高致血浆外渗，有效循环血量减少，血压进行性下降。总血容量减少是失血性休克的特点。容量血管收缩属代偿反应，有助维持回心血量，不会使血压下降"},{"q":"某患者诊断为CRF，以下哪一项不是其出现贫血的原因","o":["EPO减少","体内毒性物质蓄积","胃肠吸收功能减退","红细胞脆性增加","血小板功能亢进"],"a":4,"e":"肾性贫血主要因EPO生成减少、毒性物质抑制骨髓造血、胃肠吸收减退致铁与叶酸不足，以及红细胞脆性增加、寿命缩短。血小板功能亢进不引起贫血，且慢性肾衰时血小板功能实际是低下的，故该项既非贫血原因也不符合病情。EPO减少是其中最主要的机制"},{"q":"患者，男，15岁。因外伤致血管破裂，失血约800mL，烦躁不安，面色苍白，四肢湿冷，血压100/84mmHg，现患者可能处于","o":["失血性休克代偿期","失血性休克失代偿期","失血性休克晚期","大失血，但未休克","重度虚脱"],"a":0,"e":"失血约800mL相当于循环血量20%，患者烦躁、面色苍白、四肢湿冷、脉压减小而收缩压尚可维持，属微循环收缩期的代偿表现。失代偿期血压明显下降、意识淡漠。休克晚期出现DIC和多器官功能衰竭。未发生休克者不应有交感兴奋所致的肢冷与烦躁"},{"q":"患者，男，30岁。因乙型肝炎行穿刺活检，见肝细胞体积增大，胞质疏松、淡染，肝细胞最有可能的病理变化是","o":["脂肪变","细胞水肿","玻璃样变","黏液样变","淀粉样变"],"a":1,"e":"肝细胞损伤后ATP减少、钠泵失灵，细胞内水钠潴留，表现为细胞体积增大、胞质疏松淡染，即细胞水肿，病毒性肝炎时最常见，重者呈气球样变。脂肪变为胞质内脂滴空泡并将核挤向一侧。玻璃样变呈胞质内均质红染小体，黏液样变发生于间质"},{"q":"患者，男，84岁。因肺炎并发中毒性休克和DIC，经抢救无效死亡，解剖后在肺、肾、脑等组织切片中可能见到","o":["白色血栓","红色血栓","混合血栓","透明血栓","延续性血栓"],"a":3,"e":"DIC时凝血在微循环内广泛激活，纤维蛋白在毛细血管内形成嗜酸性均质的透明血栓，镜下见于肺、肾、脑等器官的微血管。白色血栓由血小板构成，见于心瓣膜和动脉血栓头部。红色血栓为静脉内凝血块；混合血栓构成静脉延续性血栓的体部"},{"q":"患者，男，20岁。几天前有淋雨史。两天前突发高烧，全身不适，胸闷，今日突然烦躁不安，面色苍白，四肢厥冷，咳铁锈色痰，急诊入院。查体：体温39.5℃，面色苍白，精神恍惚，颈无抵抗，心率110次/分，血压120/90mmHg。听诊右肺上叶呼吸音减弱，叩诊浊音。胸片右肺上叶纹理增强，淡薄阴影。血常规：白细胞计数明显升高。该患者最可能患的疾病是","o":["急性支气管炎","小叶性肺炎","病毒性肺炎","肺脓肿","大叶性肺炎"],"a":4,"e":"青壮年淋雨后急起寒战高热、胸痛、咳铁锈色痰，伴肺叶实变体征，是大叶性肺炎的典型经过，病原多为肺炎链球菌。小叶性肺炎多见于老幼体弱，病灶散在以细支气管为中心，无铁锈色痰。病毒性肺炎为间质性炎，白细胞多不升高。肺脓肿以大量脓臭痰和空洞为特征"},{"q":"某患者，因大出血发生失血性休克，出现面色苍白，四肢湿冷，少尿等临床表现。这些临床表现的病理生理机制是","o":["毛细血管床大量关闭","毛细血管内流体静压降低","毛细血管壁通透性增高","动静脉吻合支开放","容量血管收缩"],"a":0,"e":"失血性休克早期交感神经强烈兴奋，皮肤、内脏的毛细血管前括约肌收缩，毛细血管床大量关闭，血流减少，故见面色苍白、四肢湿冷、尿量减少。毛细血管壁通透性增高见于淤血期，是血浆外渗的原因。动静脉吻合支开放见于感染性休克。容量血管收缩有助回心血量"},{"q":"某患儿，3岁，严重腹泻呈水样便，患儿呈深大呼吸，其最可能出现的酸碱平衡紊乱类型是","o":["代谢性酸中毒","代谢性碱中毒","呼吸性酸中毒","呼吸性碱中毒","混合型酸碱平衡紊乱"],"a":0,"e":"严重腹泻丢失大量碱性肠液，HCO3-减少，患儿出现深大呼吸以排出CO2进行代偿，符合代谢性酸中毒。呼吸性酸中毒由通气不足致CO2潴留，见于气道阻塞。代谢性碱中毒见于剧烈呕吐、幽门梗阻致胃酸丢失。呼吸性碱中毒由过度通气引起"},{"q":"一呼吸衰竭患者，其肺泡气PO2为102mmHg（13.6kPa），动脉血PO2为56mmHg（7.5kPa），该呼吸衰竭的可能病因是","o":["急性喉头水肿","呼吸肌麻痹","严重胸廓畸形","肺水肿","慢性阻塞性肺疾患"],"a":3,"e":"肺泡气PO2正常而动脉血PO2明显降低，说明通气功能尚可而肺泡与血液间气体弥散受阻，肺水肿时肺泡壁增厚、弥散距离加大，正合此改变。急性喉头水肿、呼吸肌麻痹、严重胸廓畸形均致肺泡通气不足，肺泡气PO2随之下降。慢阻肺为阻塞性通气障碍，肺泡气PO2亦低"},{"q":"患者，男，26岁。患有肛周脓肿，在肛周左侧破溃形成伤口，局部流脓不断，入院后检查，肛周伤口为外口，实与直肠相通，此病理管道为","o":["空洞","瘘管","窦道","溃疡","糜烂"],"a":1,"e":"肛周脓肿向皮肤破溃形成外口，又与直肠相通，形成连接肠腔与体表的通道，即为瘘管。窦道只有一端开口、另一端为盲端，如骨髓炎窦道。空洞是坏死物经自然管道排出后残留的空腔。溃疡为皮肤黏膜的较深缺损，糜烂则仅限于表皮浅层"},{"q":"患者，男。因呕吐、腹泻伴发热4天住院。患者自述虽口渴厉害但饮水即吐。查体：体温 38.6 ℃，呼吸、脉搏正常，血压110/80mmHg，有烦躁不安，口唇干裂。尿量约700ml/d。实验室检查：血清钠 155mmol/L ，尿钠 25mmol/L 。该患者出现的水、钠代谢紊乱类型是","o":["高渗性脱水","等渗性脱水","低渗性脱水","水中毒","水肿"],"a":0,"e":"血清钠155mmol/L高于正常，血浆渗透压升高，口渴明显、饮水即吐致摄水不足而失水多于失钠，属高渗性脱水。低渗性脱水血钠低于135mmol/L，多见于大量补液或利尿后。等渗性脱水血钠正常，见于呕吐腹泻早期。水中毒为水潴留致血钠稀释性降低"},{"q":"患者，女， 21 岁。右颈单一无痛性淋巴结肿大，约2.2cm × 2.5cm ，活动欠佳。活检：淋巴结被膜完整，无明显的出血及坏死。镜下见淋巴结结构已破坏，大量束状纤维组织增生及一些散在的大细胞，其胞浆丰富、透明、核大、有多个嗜碱性核仁；细胞与周围组织之间形成透明的空隙。同时还可见嗜酸性粒细胞、浆细胞及少量的中性粒细胞。该病的最佳诊断为","o":["慢性非特异性淋巴结炎","结核性淋巴结炎","非霍奇金淋巴瘤","霍奇金淋巴瘤，混合细胞型","霍奇金淋巴瘤，结节硬化型"],"a":4,"e":"淋巴结结构破坏，胶原纤维束将病变分割成结节，陷窝细胞胞体大、胞质透明、核仁明显且与周围细胞间形成透明空隙，伴嗜酸性粒细胞浸润，为结节硬化型霍奇金淋巴瘤的典型图像。混合细胞型以典型R-S细胞为主，无宽带状纤维化。非霍奇金淋巴瘤不出现陷窝细胞"},{"q":"某病人持续高热、心动过速、腹泻3周，后因中毒性休克死亡。尸体解剖发现死者弥漫性腹膜炎，回肠末端淋巴小结肿大、坏死和溃疡形成，并有穿孔，脾肿大，考虑最大可能性为","o":["细菌性痢疾","肠癌","急性肠炎","伤寒","结核"],"a":3,"e":"稽留高热、腹泻、中毒性休克，回肠末端淋巴小结坏死溃疡并穿孔，脾大，是伤寒肠道病变坏死溃疡期的表现。细菌性痢疾的假膜性炎主要累及乙状结肠和直肠。肠结核溃疡呈环形、底部有干酪样坏死。肠癌无稽留热及全身中毒症状"},{"q":"患者，男，80岁。尸检中发现双侧肾脏对称性缩小，重量减轻，颜色苍白，质地变硬。肾包膜与肾实质粘连而难于剥离，肾表面呈弥漫性的细颗粒状。切面可见肾皮质萎缩变薄，皮髓质分界不清。光镜下，肾小球发生玻璃样变和硬化，其所属肾小管由于缺血而萎缩、消失。肾间质纤维组织增生，伴有淋巴细胞及浆细胞浸润。出现“肾小球集中”现象。肾内细、小动脉发生玻璃样变和内膜增厚。该患者生前最可能患有","o":["肾病综合征","急性肾炎综合征","慢性肾炎综合征","无症状血尿、蛋白尿","快速进行性肾炎综合征"],"a":2,"e":"双肾对称缩小、质硬、表面细颗粒状、皮质变薄、肾小球玻璃样变硬化并集中，是慢性硬化性肾小球肾炎的终末改变，临床表现为慢性肾炎综合征。急性肾炎综合征双肾增大充血。肾病综合征以大量蛋白尿、低白蛋白血症为特征。快速进行性肾炎见新月体、肾体积增大"},{"q":"患者，男，21岁。1周前开始发热，午后高达40～41℃，伴腹痛、腹胀、便秘，无恶心、呕吐，不思饮食，全身乏力。右胸前皮肤有数个淡红色皮疹，压之褪色，肝肋下1、5cm，剑突下2cm，质软有轻度触痛，脾肋下2cm。该患者考虑诊断为","o":["急性肠炎","伤寒","急性肝炎","过敏性皮炎","败血症"],"a":1,"e":"持续高热、腹痛腹胀便秘，胸腹皮肤出现压之褪色的玫瑰疹，肝脾轻度肿大，为伤寒极期的典型表现，病原为伤寒沙门菌。败血症有原发感染灶及多发性出血点。急性肠炎以腹泻为主。急性肝炎以黄疸和转氨酶升高为主要表现，无玫瑰疹"},{"q":"48岁女性患者，病史2年，无自身免疫反应的表现，体型较胖，腹部B超未见异常回声，餐后2小时血糖8.5mmol/L，血胰岛素正常。该患者首先考虑可能患有","o":["非胰岛素依赖型糖尿病","胰岛素瘤","胃泌素瘤","胰多肽瘤","胰岛素依赖型糖尿病"],"a":0,"e":"成年发病、体型肥胖、起病缓慢、血胰岛素水平正常，符合非胰岛素依赖型糖尿病即2型，其胰岛数目正常或轻度减少，不易发生酮症。胰岛素瘤表现为空腹低血糖发作伴胰岛素升高。胰岛素依赖型多见于青少年，胰岛素降低、易酮症。胃泌素瘤以难治性溃疡为特征"},{"q":"一尸检的脑标本，肉眼见脑回变窄，脑沟加深变宽，脑室扩张。光镜下见神经细胞体积缩小，可见神经原纤维缠结。该标本的病理诊断为","o":["脑萎缩","脑坏死","脑梗死","脑软化","脑纤维化"],"a":0,"e":"脑回变窄、脑沟增宽、脑室代偿性扩张，镜下神经细胞体积缩小并见神经原纤维缠结，属脑萎缩的形态学诊断，常见于阿尔茨海默病。脑梗死为液化性坏死灶，早期即形成软化囊腔。脑坏死多指局灶凝固性或液化性坏死，不呈弥漫萎缩。脑纤维化为瘢痕改变"},{"q":"一肝功能不全患者，两臂平举、手指分开、放松闭眼时，出现腕、掌指关节不规则、急速而微小的鸟翼样颤抖，最可能是发生了","o":["扑翼样震颤","帕金森综合征","特发性震颤","低血糖性震颤","甲亢性震颤"],"a":0,"e":"肝功能不全时血氨等毒性物质蓄积，患者双臂平举、手指分开闭眼时出现腕掌关节不规则、急速的鸟翼样抖动，即扑翼样震颤，是肝性脑病的特征性体征。帕金森综合征为静止性搓丸样震颤伴肌强直。特发性震颤为动作性震颤，无肝病基础。甲亢性震颤细速且伴代谢亢进"},{"q":"一肝硬化患者，在饮食不当后出现上消化出血，遂往医院进行止血处理，三天后出现昏迷。该患者出现昏迷的原因最大可能是","o":["失血引起失血性休克","失血导致缺氧","血液蛋白在肠道内分解产生氨","出现严重感染","饮食不当导致体内毒素增多"],"a":2,"e":"上消化道出血后血液蛋白在肠道被细菌分解产生大量氨，经门体分流直接入脑，诱发肝性脑病，故止血后数日出现昏迷。失血性休克以血压下降、循环衰竭为表现，输血补液后即改善。缺氧需持续低灌注方能致脑病。感染应有发热等中毒表现"},{"q":"患者，男，20岁。近1个月来头痛、头晕伴恶性、呕吐，测血压为240/140mmHg，1年后，患者死亡。患者最可能的死亡原因是","o":["肾功能衰竭","眼底出血","脑水肿","左心衰竭","下肢坏疽"],"a":0,"e":"血压240/140mmHg属恶性高血压，舒张压显著升高使肾入球小动脉纤维素样坏死、肾小球缺血硬化，患者多在短期内死于肾功能衰竭。高血压脑病表现为头痛、呕吐、意识障碍，降压后可逆。眼底出血只影响视力。左心衰竭可发生，但本例以肾损害进展最快"},{"q":"患者，男，40岁。体检时发现直肠一息肉状肿物，肠镜活检示腺癌，肿瘤细胞未突破黏膜肌层。该患者应诊断为","o":["低级别上皮内瘤变","高级别上皮内瘤变","直肠黏膜内瘤变","直肠腺瘤","直肠腺癌"],"a":2,"e":"官方答案为【直肠黏膜内瘤变】，但依据教材，正确答案为【高级别上皮内瘤变】。教材明确结直肠肿瘤组织只有侵犯黏膜肌层到达黏膜下层才称为癌，未突破黏膜肌层的黏膜内癌归入高级别上皮内瘤变或异型增生。故本例不能诊断为腺癌，黏膜内瘤变也非规范术语；低级别上皮内瘤变异型性较轻"},{"q":"患儿因异物误入气管导致窒息而急诊入院，血气测定结果如下：pH：7.14，PaCO2：81mmHg，HCO3ˉ：26.5mmol/L，其酸碱平衡的代偿调节主要依靠","o":["血浆蛋白缓冲系统","碳酸氢盐缓冲系统","非碳酸氢盐缓冲系统","肺的调节","肾脏的调节"],"a":2,"e":"急性呼吸性酸中毒时肾代偿尚未启动，主要靠细胞内外H+与K+交换及血红蛋白、磷酸盐等非碳酸氢盐缓冲系统缓冲CO2。碳酸氢盐缓冲系统是血浆最主要的缓冲对，但对挥发性酸缓冲能力有限。肺的调节针对代谢性酸碱失衡，肾脏调节需3～5天才充分发挥"},{"q":"患者，男，80岁。头痛数十年，以高热不退、畏寒、头痛10余天入院。实验室检查：外周血白细胞为：10.6×109/L，其中中性粒细胞占82%，CT检查发现左侧大脑有一个2cm×3cm大小坏死灶，经过抗炎治疗无效死亡。尸检病灶组织送病理检查，镜下发现：该病变组织液化坏死，有大量中性粒细胞浸润，伴有脓细胞，周围有成纤维细胞增生和新生的毛细血管形成。该病变属于","o":["蜂窝织炎","积脓","肉芽肿性炎","脓肿","炎性包裹"],"a":3,"e":"脑内局限性化脓性炎，组织液化坏死形成脓腔，大量中性粒细胞坏死成为脓细胞，周围肉芽组织增生形成脓肿壁，符合脓肿。蜂窝织炎发生于疏松结缔组织，呈弥漫性化脓，界限不清且坏死不明显。积脓指体腔内脓液积聚。肉芽肿性炎以巨噬细胞结节为特征"},{"q":"某烧伤面积达20%的女性患者，尿量240ml/24h，其最可能出现的电解质紊乱是","o":["高钠 血症","高钾血症","高钙血症","低钙血症","低磷血症"],"a":1,"e":"大面积烧伤使大量组织细胞破坏，钾离子自细胞内释出，加之有效循环血量减少、尿量仅240ml/日致排钾受阻，故出现高钾血症。高钠血症见于高渗性脱水。低钙血症虽可因烧伤后低蛋白发生，但不是本题主要紊乱。低磷血症无此临床背景"},{"q":"患儿，女，13岁。1月前患扁桃体炎，经治疗痊愈。1周前开始发热，38℃，关节肿胀。检查发现，心率100次/分，心尖区闻及舒张期Ⅱ～Ⅲ级杂音。血白细胞升高，血沉加快。抗O滴度升高。该患者最可能发生的心脏疾病是","o":["病毒性心肌炎","细菌性心肌炎","免疫性心肌炎","风湿性心肌炎","寄生虫性心肌炎"],"a":3,"e":"扁桃体链球菌感染后1～3周出现发热、游走性关节肿痛、心率增快及心尖区杂音，抗O升高、血沉加快，符合风湿热心脏受累，心肌间质形成风湿小体，即风湿性心肌炎。病毒性心肌炎有病毒感染前驱期而无ASO升高。细菌性心肌炎为化脓性炎。免疫性心肌炎见于红斑狼疮等"},{"q":"患者男，80岁。有30年高血压病史。近期心衰加剧，用β受体阻断剂可改善心衰症状。引起患者心衰加剧的信号转导异常机制主要可能是","o":["β1肾上腺素能受体上调","β1肾上腺素能受体下调","β1肾上腺素能受体产生自身抗体","β1肾上腺素能受体基因突变","β1肾上腺素能受体增敏"],"a":1,"e":"慢性心衰时交感神经长期兴奋，β1受体因持续激动发生下调，心肌对儿茶酚胺反应性降低，阻断β受体可减少受体下调并改善预后，故用β受体阻断剂有效。β1受体上调见于长期使用拮抗剂后的撤药反应。自身抗体见于扩张型心肌病。受体基因突变罕见"},{"q":"患者，男，50岁。咯血伴左侧头痛、鼻塞、痰中带血6月。鼻咽部活检：非角化性癌。患者完善相关检查后行放射治疗。该治疗方案所依据的原则是","o":["抑制肿瘤细胞过度增殖","修复肿瘤细胞增殖缺陷","提高肿瘤细胞对药物的敏感性","诱导肿瘤细胞凋亡","减少组织细胞凋亡"],"a":3,"e":"放射线造成肿瘤细胞DNA双链断裂，损伤不能修复时由p53启动程序性死亡，使瘤细胞凋亡，这是放疗杀伤肿瘤的基本机制。抑制过度增殖主要针对化疗药物干扰DNA合成。修复增殖缺陷与提高药物敏感性均不是放疗的作用方式。减少细胞凋亡反而促进肿瘤生长"},{"q":"患者，女，45岁。阴道不规则流血半月，病理活检诊断子宫内膜腺体增生，该变化属于","o":["生理性增生","代偿性增生","内分泌性增生","不典型增生","肿瘤性增生"],"a":2,"e":"雌激素绝对或相对增多刺激子宫内膜腺体增生过长，属内分泌性即激素性增生，是功能性子宫出血的病理基础。生理性增生见于正常月经周期，有周期性脱落。代偿性增生见于肝部分切除后残存肝细胞增生。不典型增生细胞有异型性，属癌前病变；肿瘤性增生为克隆性自主生长"},{"q":"患者，女，47岁。右腿大隐静脉曲张12年，近日加重。遂行大隐静脉切除术。术中见静脉腔内有2个褐色物，与血管壁连接紧密，不易剥离。此褐色物质最可能是","o":["白色血栓形成","透明血栓形成","血栓形成并钙化","血栓形成并软化","血栓形成并机化"],"a":4,"e":"血栓经肉芽组织长入并逐渐被纤维组织取代，与血管壁紧密粘连、不易剥离，历时较久则质地变韧，符合血栓机化。血栓软化是纤维蛋白溶解、质地变软易脱落。钙化后质硬如石、切之有砂砾感。白色血栓见于动脉或瓣膜，与管壁黏着但不成褐色团块"},{"q":"Page-Frame患者，女，18岁。因高热，皮肤红疹4天入院，患者2周前右足大拇趾破损，未作任何治疗，入院前4天开始发热，体温39~40℃，且于发热第3天双下肢皮肤出现散在斑点状红疹，体温升高，持续不退，出现精神恍惚，谵语。查体：体温41℃，脉搏108次/分钟，肝肋下2指，脾于肋缘下可触及，右侧腹股沟淋巴结肿大，多个，质软。双下肢皮肤见散在、淡红色斑点，实验室检查：白细胞计数2.4×109/L，其中中性粒细胞占90%。血培养一周后结果显示金黄色葡萄球菌阳性。经抗菌素治疗、解热等综合治疗后体温渐退，3周缓解，4周出院。患者入院诊断应包括","o":["菌血症","毒血症","败血症","脓毒败血症","病毒血症"],"a":2,"e":"细菌自局部病灶入血并大量繁殖、产生毒素，引起高热、皮疹、脾及淋巴结肿大，血培养金黄色葡萄球菌阳性，符合败血症。菌血症仅血中短暂有菌而无全身中毒症状。毒血症只有毒素入血、血培养阴性。脓毒败血症需有多发性迁徙性脓肿"},{"q":"男性，52岁，长期酗酒，近半年腹胀、食欲不振。体检时B超发现肝脏表面结节状，弥漫分布，腹腔里有积液，经肝穿刺活检镜下发现肝组织中有假小叶形成，病理诊断为：门脉性肝硬化。此时腹腔的积液主要是","o":["渗出液","漏出液","浆液","脓液","淋巴液"],"a":1,"e":"门脉性肝硬化时门静脉压升高、血浆白蛋白降低，腹水为淡黄色透明液体，蛋白低于30g/L、细胞数少、比重低，属漏出液。渗出液由炎症引起，蛋白高、浑浊、易凝固。脓液为化脓性炎产物。淋巴液见于淋巴管破裂形成的乳糜腹水"},{"q":"某患者血气分析结果为：pH 7.36，不可能的诊断为","o":["无酸碱平衡紊乱","代偿性酸中毒","代偿性碱中毒","混合性酸碱平衡紊乱","失代偿性酸碱平衡紊乱"],"a":4,"e":"pH正常范围为7.35～7.45，代偿性酸中毒或碱中毒时经代偿pH可维持在正常范围，酸碱方向相反的混合性紊乱也可相互抵消而使pH正常。失代偿性酸碱平衡紊乱必然伴pH超出正常范围，故pH 7.36时不可能成立。无酸碱紊乱时pH亦正常"},{"q":"某患者高热数日，注射解热镇痛药后又大量出汗，最易发生的水钠代谢紊乱是","o":["低渗性脱水","等渗性脱水","高渗性脱水","水中毒","水肿"],"a":2,"e":"高热数日已经失水，注射解热镇痛药后大量出汗，汗液为低渗液，失水多于失钠，血浆渗透压升高，发生高渗性脱水。低渗性脱水见于大量补液或使用排钠利尿剂后。等渗性脱水见于呕吐、腹泻致消化液丢失。水中毒因ADH分泌过多或补液过量所致"},{"q":"某缺氧患者，其呼吸加深加快的原因可能是","o":["CO中毒","亚硝酸盐中毒","进入通风不良的坑道","急性心力衰竭","KCN中毒"],"a":2,"e":"通风不良的坑道内氧分压降低，属低张性缺氧，动脉血氧分压下降刺激颈动脉体和主动脉体外周化学感受器，反射性引起呼吸加深加快。CO中毒和亚硝酸盐中毒属血液性缺氧，动脉血氧分压正常，不刺激呼吸。KCN中毒为组织性缺氧，呼吸不增强。急性心衰为循环性缺氧"},{"q":"患者，女，28岁，有10年吸烟史。近3年来慢性咳嗽、咳白色泡沫痰，每年发病时间3个月以上。气管镜黏膜活检所见病变应是","o":["变质性炎","肉芽肿性炎","慢性非特异性炎症","化脓性炎","纤维素性炎"],"a":2,"e":"长期吸烟刺激支气管黏膜，出现连续两年、每年三个月的咳嗽咳痰，病理为黏膜及周围组织的慢性非特异性炎，伴腺体增生和杯状细胞增多。肉芽肿性炎见于结核等特异性感染。化脓性炎以大量中性粒细胞和脓性痰为特征。纤维素性炎见于大叶性肺炎和假膜性炎"},{"q":"男性，5岁，左腿烫伤后红肿、疼痛，数小时后起水疱。其病变为","o":["出血性炎","变质性炎","浆液性炎","蜂窝织炎","化脓性炎"],"a":2,"e":"Ⅱ度烧伤时毛细血管通透性增高，血浆成分渗出积聚于表皮与真皮之间形成水疱，渗出液以浆液为主、蛋白含量3%～5%，属浆液性炎。出血性炎渗出物含大量红细胞。蜂窝织炎为疏松结缔组织的弥漫性化脓炎。化脓性炎渗出物以中性粒细胞和脓液为主"},{"q":"患儿，男，7岁。3天前出现低热，咽痛，咳嗽和脓痰。当地医院就诊，查体：咽部充血，血常规提示白细胞为12×109/L，以中性粒细胞增高为主；皮肤可见瘀点，颈强直，克氏征阳性。病人首先考虑","o":["流行性脑脊髓膜炎","流行性乙型脑炎","急性支气管炎","大叶性肺炎","肺脓肿"],"a":0,"e":"发热、咽痛、脓痰提示上呼吸道感染，继之出现皮肤瘀点及颈强直、克氏征阳性等脑膜刺激征，符合脑膜炎双球菌所致化脓性脑脊髓膜炎。乙型脑炎为脑实质受累，无皮肤瘀点及脓痰。大叶性肺炎无脑膜刺激征。肺脓肿以空洞和大量脓痰为特征"},{"q":"患者，女，25岁。患有风湿性二尖瓣狭窄合并主动脉瓣关闭不全。乏力、纳差，伴发热20天。查体：体温37.8℃，血红蛋白80g/L，白细胞计数9.2×109/L，皮肤有瘀点，脾大，心尖部可闻及舒张期杂音，主动脉瓣区可闻及舒张期杂音。该患者最符合的疾病是","o":["风湿性心肌炎","贫血性心脏病","风心病，心力衰竭","先天性主动脉瓣病变","风湿性瓣膜病合并感染性心内膜炎"],"a":4,"e":"原有风湿性二尖瓣狭窄与主动脉瓣关闭不全，近期持续发热、贫血、皮肤瘀点、脾大，提示在瓣膜病变基础上并发感染性心内膜炎，赘生物形成并播散。风湿性心肌炎无瘀点和脾大。心力衰竭不引起发热与瘀点。先天性主动脉瓣病变不能解释二尖瓣狭窄"},{"q":"某田径运动员参加奥运会百米赛跑，当他听到起跑信号时，体内最明显升高的激素是","o":["儿茶酚胺","β-内啡肽","糖皮质激素","胰岛素","醛固酮"],"a":0,"e":"听到起跑信号即刻进入应激状态，交感神经兴奋使肾上腺髓质释放儿茶酚胺，血中浓度迅速升高，心率加快、血压上升、血糖升高，以满足肌肉运动需要。糖皮质激素起效慢，属应激后期反应。β-内啡肽主要参与镇痛。胰岛素在运动时分泌减少"},{"q":"患者，男，66岁。慢性咳嗽、咳痰18年，每年冬季加重。近来咳嗽，咳白色黏痰，呼吸困难加重。体查发现患者呈桶状胸，肋间隙增宽，双肺可闻及小水泡音，最可能的诊断是","o":["慢性支气管炎，肺气肿","大叶性肺炎，肺气肿","肺癌，小叶性肺炎","肺结核，小叶性肺炎","慢性支气管炎，支气管扩张"],"a":0,"e":"长期咳嗽咳痰、冬季加重符合慢性支气管炎，气道阻塞致肺过度充气，出现桶状胸、肋间隙增宽，双肺小水泡音提示合并肺气肿。支气管扩张以大量脓痰和反复咯血为特征。肺结核多有低热盗汗及上叶病灶。肺癌以刺激性干咳或肿块影为主"},{"q":"患者，男，20岁。稽留高热3周，伴腹胀、腹泻入院，当晚突然出现腹痛，体温骤降至35、5℃，脉搏120次/分，血压60/45mmHg，腹部压痛、反跳痛明显，肝浊音界缩小。实验室检查：WBC：18.0×109/L，N：0.88，L：0.12，肥达反应H：1:320, O：1:320，最可能的诊断是","o":["胃溃疡穿孔","阑尾炎穿孔","肠伤寒穿孔","胆囊炎胆囊穿孔","阿米巴痢疾肠穿孔"],"a":2,"e":"稽留高热三周伴腹胀腹泻，肥达反应H、O均1:320，突发腹痛、血压下降、腹膜刺激征及肝浊音界缩小，符合伤寒溃疡期并发肠穿孔。胃溃疡穿孔多有慢性溃疡病史，无稽留热及肥达反应阳性。阿米巴痢疾为果酱样便、右下腹压痛。阑尾炎为转移性右下腹痛"},{"q":"某患者上呼吸道感染伴发热 2 天，出现浑身肌肉酸痛的原因是","o":["糖原分解加强","脂肪分解加强","蛋白质分解加强","维生素消耗增多","皮肤、呼吸道水分蒸发增多"],"a":0,"e":"发热时基础代谢率升高，交感兴奋促使肝糖原分解加强，肌肉内糖原无氧酵解增多，乳酸堆积刺激神经末梢，产生全身肌肉酸痛。脂肪分解加强主要增加产热。蛋白质分解见于长期消耗性疾病。维生素消耗增多与酸痛无直接关系。水分蒸发增多只引起口渴和脱水"},{"q":"患者，女，45岁。同房接触性出血一周。检查子宫颈有一菜花状肿物，触之易出血。镜下见异型细胞呈巢状结构，有角化珠形成，浸润宫颈间质。该患者应诊断为","o":["慢性宫颈炎","宫颈原位癌","宫颈鳞癌","宫颈尖锐湿疣","宫颈炎性息肉"],"a":2,"e":"宫颈菜花状肿物、触之易出血，镜下异型细胞呈巢状浸润间质并见角化珠，是宫颈鳞状细胞癌的典型表现。原位癌未突破基膜，不形成角化珠浸润。尖锐湿疣见表皮挖空细胞和乳头状增生，无角化珠。炎性息肉由纤维血管间质构成，被覆柱状上皮"},{"q":"患者，女，50岁。近三年来，活动后出现胸痛，常放射至左肩，左臂内侧，每次发作含硝酸甘油后缓解。诊断为冠状动脉粥样硬化。下列哪些习惯对病情无益","o":["低脂饮食","控制血压","不吸烟","不饮酒","大量运动"],"a":4,"e":"冠状动脉粥样硬化患者应控制危险因素，低脂饮食、控制血压、戒烟限酒均可延缓斑块进展。大量运动使心肌耗氧量骤增，而狭窄的冠状动脉不能相应增加供血，易诱发心绞痛甚至心肌梗死，故对病情无益。中等量有氧运动才属康复措施"},{"q":"患儿，3月女婴，因呕吐、腹泻伴发热 2 天入院。体检：体重 7.8kg ，体温 38.9 ℃。神志清楚，烦躁不安，面色发红，前囱及眼窝轻度凹陷，口唇黏膜干裂，常作口渴欲饮状。皮肤明显干燥，弹性较差。实验室检查：K+：4.6mmol/L ， Na+：158mmol/L 。该患儿最有可能的诊断是","o":["水中毒","等渗性脱水","低渗性脱水","高渗性脱水","水肿"],"a":3,"e":"呕吐腹泻伴高热使水分丢失，前囟及眼窝凹陷、皮肤干燥弹性差为脱水体征，血清钠158mmol/L提示失水多于失钠，属高渗性脱水。低渗性脱水血钠低于135mmol/L，易早期出现循环衰竭。等渗性脱水血钠正常。水中毒血钠降低且无脱水体征"},{"q":"一患者由于慢性呼吸衰竭，检测动脉血PaCO2为85mmHg，出现头痛，烦躁，言语不清等“CO2麻醉”效应，其发生机制不包括","o":["颅内压降低","脑血流量增加","脑细胞内Na+、水增多","脑毛细血管通透性增高","氢离子浓度升高"],"a":0,"e":"CO2潴留使脑血管扩张、脑血流量增加，毛细血管通透性增高，脑细胞内钠水增多形成脑水肿，颅内压因而升高，出现头痛、烦躁乃至昏迷，即CO2麻醉。颅内压降低与上述机制相反，不是CO2麻醉的表现。氢离子浓度升高加重中枢抑制"},{"q":"一名儿童出现发热，并伴有咳嗽，胸透见两肺下叶散在边缘不清的小点状阴影，最有可能的诊断是","o":["干酪样肺炎","小叶性肺炎","大叶性肺炎","间质性肺炎","转移性肿瘤"],"a":1,"e":"儿童发热咳嗽，两肺下叶散在边缘不清的小点状阴影，为以细支气管为中心的化脓性炎，符合小叶性肺炎。大叶性肺炎呈整叶均匀实变，多见于青壮年。干酪性肺炎为结核性，好发于上叶并有空洞。间质性肺炎呈网状或磨玻璃影，以淋巴细胞浸润为主"},{"q":"患者，男，69岁。患高血压病13年。因劳累后突发呼吸困难，咳粉红色泡沫痰就诊。血压190/100mmHg，对该患者的最佳治疗措施是","o":["扩张动脉血管，降低心脏的后负荷","增强心肌收缩力","使用支气管扩张剂","扩张静脉血管，降低心的前负荷","高流量吸氧"],"a":0,"e":"高血压患者突发呼吸困难、咳粉红色泡沫痰，为急性左心衰竭肺水肿，血压190/100mmHg提示后负荷过重，治疗关键在扩张动脉、降低外周阻力与后负荷，减少心肌耗氧。增强心肌收缩力不能解决后负荷过高。支气管扩张剂不改善肺水肿。扩张静脉降前负荷作用有限，高流量吸氧为辅助措施"},{"q":"患者，女，40岁。查体时发现右肺靠近胸膜处有一直径4cm的肿物，与周围肺组织分界不清，同时右肺门及右锁骨上淋巴结肿大，该女士可能患有","o":["肺癌","肺结核","肺脓肿","肺炎性假瘤","大叶性肺炎"],"a":0,"e":"近胸膜处4cm肿块边界不清，伴肺门及锁骨上淋巴结肿大，符合周围型肺癌伴淋巴道转移。结核球边界清楚、可有钙化，不引起锁骨上淋巴结肿大。炎性假瘤为良性局限病变。肺脓肿有液平及大量脓痰。大叶性肺炎为整叶实变并有急性感染症状"},{"q":"患者，男，80岁。因心肺功能衰竭而长期卧床。死亡后尸检见肺组织散在多发小实变区。制片后镜下观察，见细支气管上皮细胞坏死脱落，管腔内及周围有大量炎性渗出物，以中性粒细胞为主。该患者肺部病变提示死前可能患有","o":["大叶性肺炎","小叶性肺炎","病毒性肺炎","慢性支气管炎","肺结核"],"a":1,"e":"长期卧床、心肺功能衰竭者，双肺散在小实变，镜下以细支气管为中心、管壁坏死并大量中性粒细胞渗出，符合小叶性肺炎，属坠积性肺炎。大叶性肺炎为整叶纤维蛋白性炎，肺泡壁结构保存。病毒性肺炎为间质性、淋巴细胞浸润。慢性支气管炎不形成实变"},{"q":"一个恶性肿瘤患者在X线检查时发现肺内有多个散在的圆形阴影，首先考虑恶性肿瘤发生了","o":["支气管播散","淋巴道转移","种植性转移","不典型增生","血道转移"],"a":4,"e":"肺野内多个散在、大小相近的圆形阴影是瘤细胞经肺循环动脉播散形成的转移瘤，即血道转移，多见于肾癌、绒毛膜癌等。淋巴道转移表现为肺门或纵隔淋巴结肿大。种植性转移发生于胸膜表面。支气管播散见于结核，沿支气管呈腺泡结节分布"},{"q":"患者，女，28岁。劳累后心悸、气促4年，近来加重，夜间不能平卧就诊。查体：心率110次/分，心音强弱不等，心尖部可闻及舒张期隆隆样杂音，肺底可闻及细小水泡音。心脏彩超显示二尖瓣狭窄。该患者夜间不能平卧的主要原因是","o":["入睡后迷走神经兴奋性增高，呼吸道阻力增大","平卧时回心血量增多，加重心的前负荷","神经反射敏感性增高","膈肌位置相对下移","需氧量增加"],"a":1,"e":"二尖瓣狭窄致左心房压升高、肺静脉回流受阻，平卧时回心血量增加，肺淤血加重，故夜间不能平卧。入睡后迷走神经兴奋使心率减慢、冠脉收缩，但不是主要原因。平卧时膈肌上移而非下移，肺通气量减少。需氧量增加不是端坐呼吸的直接机制"},{"q":"患者，男，38岁。外伤大出血而急诊入院。患者面色苍白，四肢湿冷，烦躁不安，心率90次/分，血压95/80mmHg。此时患者体内可维持正常血液供应的器官是","o":["皮肤、肝","心、脑","肝、肾","肺、肝","脾、肾"],"a":1,"e":"休克时交感兴奋使血液重新分布，皮肤、肝、肾、脾的血流显著减少，而心和脑因局部自身调节及优先供血得以维持灌注，故血压95/80mmHg时仍能保证心脑血供。皮肤与肝、肾、脾均为缺血器官。肺虽接受全部心排出量，但微循环灌注亦减少"},{"q":"患者，女，23岁。结核性腹膜炎伴有肠梗阻入院手术。手术后禁食，并连续做胃肠减压7天，共抽吸液体2200ml，平均每天静脉补液(5%葡萄糖液)2500ml。术后2周，患者出现肌肉软弱无力，肢体瘫软，不能翻身，偶尔有麻木感。恶心，呕吐，厌食，腹胀，全身乏力等症状。实验室检查：血清钾2.4 mmol/L,血清钠140 mmol/L。心电图显示：ST段压低，T波低平和增宽，有U波。患者发生的水、电解质代谢紊乱类型为","o":["高钠血症","低钠血症","低钾血症","高钾血症","水中毒"],"a":2,"e":"胃肠减压抽吸大量消化液致钾丢失，加之禁食、仅补葡萄糖使钾摄入不足，血清钾2.4mmol/L，出现肌肉软弱、肢体瘫软、腹胀及心电图ST段压低、T波低平、U波，为典型低钾血症。高钾血症T波高尖、QRS增宽。低钠血症以意识障碍为主。水中毒为低渗性液体过多"},{"q":"患者，男，60岁。近期出现乏力、厌食、肝区疼痛加重。肝活检显示，肝细胞出现脂肪变性、碎片样坏死，肝组织有炎症细胞浸润。患者10年前查出HCV（+）。患者现在最可能的诊断是","o":["慢性乙型病毒性肝炎","慢性丙型病毒性肝炎","乙型病毒性肝炎","丙型病毒性肝炎","酒精性肝炎"],"a":1,"e":"HCV感染十年，肝细胞脂肪变性、碎片状坏死伴门管区淋巴细胞浸润及淋巴滤泡形成，是慢性丙型肝炎的特征，病程超过半年即为慢性。慢性乙型肝炎多见毛玻璃样肝细胞。酒精性肝炎有Mallory小体及中性粒细胞浸润。急性肝炎病程短于半年"},{"q":"患者，男，25岁。因急性黄疸性肝炎入院。在治疗过程中出现呕吐咖啡色物及黑便，体检发现腹部及剑突下皮肤瘀斑，转氨酶明显增高，出、凝血时间延长，3P试验阳性，外周血涂片发现多量裂体细胞。此时该患者最恰当的诊断是","o":["肝功能衰竭","上消化道大出血","溶血性贫血","DIC","肾功能衰竭"],"a":3,"e":"重型肝炎时凝血因子合成障碍、组织因子大量释放，激活凝血系统发生DIC，表现为呕血黑便、皮肤瘀斑、3P试验阳性及外周血裂体细胞。肝功能衰竭只有凝血因子减少，3P试验阴性、无裂体细胞。溶血性贫血以贫血黄疸为主。上消化道出血是DIC的结果而非诊断"},{"q":"患者，女，31岁。主诉：经常感冒，主要症状是：咳嗽、咳痰，并时有鼻塞、流鼻涕甚至头痛等症状。由于晚上鼻塞，常常难以入睡，尤其季节交替时更为严重。痰液送病理检查发现有大量的嗜酸性粒细胞。该病人初步诊断为","o":["感冒","病毒感染","细菌感染","过敏性鼻炎","无法判断"],"a":3,"e":"鼻塞流涕、喷嚏头痛呈季节性发作，痰液中出现大量嗜酸性粒细胞，提示Ⅰ型超敏反应，符合过敏性鼻炎，变应原多为花粉、尘螨及动物毛屑。急性病毒性鼻炎分泌物以中性粒细胞为主，无嗜酸性粒细胞增多。细菌感染为脓性分泌物。感冒即病毒性鼻炎的俗称"},{"q":"患者，女，25岁。近3个月来反复出现发热，大关节出现游走性疼痛，伴有红、肿，乏力，不爱活动，稍活动后即有心跳加快。入院检查，肘、腕、膝关节附近伸侧皮下可触及圆形、质硬、无压痛结节。皮下结节内可见到的成分不含有","o":["纤维素样坏死","淋巴细胞","成纤维细胞","Aschoff细胞","中性粒细胞"],"a":4,"e":"风湿性皮下结节属增生性病变，中央为纤维素样坏死，周围有成纤维细胞、风湿细胞即Aschoff细胞及淋巴细胞，不含中性粒细胞。纤维素样坏死是结节中心的基础病变。Aschoff细胞体积大、胞质丰富，是风湿病的特征性细胞。淋巴细胞位于结节外周"},{"q":"患者，男，40岁。在私人诊所洗牙后出现肝功能异常，AST和ALT显著升高。实验室检查，乙肝表面抗原（+）。病人可能的诊断是","o":["甲型病毒性肝炎","乙型病毒性肝炎","丙型病毒性肝炎","丁型病毒性肝炎","戊型病毒性肝炎"],"a":1,"e":"乙肝表面抗原阳性，且有洗牙等破损黏膜接触血液的操作史，肝细胞损伤由HBV直接作用及免疫损伤所致，诊断为乙型病毒性肝炎。丙型肝炎主要经输血及血制品传播。甲型、戊型经粪-口途径传播，多有水源或食物流行史。丁型需在HBV感染基础上重叠感染"},{"q":"患者，女，45岁，交通意外导致全身软组织挤压伤，面色苍白，四肢湿冷，神志清醒，血压90/70mmHg，此时判断患者肾功能障碍的主要依据是","o":["少尿","多尿","肾性贫血","肾性高血压","氮质血症"],"a":0,"e":"挤压伤后肌肉坏死释放肌红蛋白阻塞肾小管，加之休克致肾灌注不足，发生急性肾损伤；24小时尿量240ml属少尿，是判断肾功能障碍最直接的指标。多尿见于慢性肾衰晚期或肾小管浓缩功能丧失。肾性贫血和肾性高血压需较长病程。氮质血症需生化检查确定"},{"q":"患者，男，50岁。肺气肿病史6年，1小时前劳作后突然呼吸困难加重，右侧胸痛，大汗，发绀，应首先考虑的诊断是","o":["干性胸膜炎","急性心肌梗死","自发性气胸","细菌性肺炎","急性肺栓塞"],"a":2,"e":"肺气肿患者肺大疱形成，劳作时胸腔内压骤升致肺大疱破裂，气体进入胸膜腔形成自发性气胸，突发呼吸困难、患侧胸痛、发绀。急性心肌梗死为胸骨后压榨性疼痛，无肺大疱破裂史。肺栓塞多源于下肢深静脉血栓。干性胸膜炎以胸膜摩擦音为特征"},{"q":"患者，男，52岁，三年前诊断为下肢脉管炎，近二个月来出现左下肢第一足趾逐渐变黑、变硬、干燥、疼痛，此足趾最为可能的病变是","o":["出血性梗死","黑色素瘤","干性坏疽","湿性坏疽","气性坏疽"],"a":2,"e":"血栓闭塞性脉管炎使肢体长期慢性缺血，侧支循环不能代偿时，足趾发生凝固性坏死，因水分蒸发而干枯变黑、与健康组织分界清楚，为干性坏疽。湿性坏疽多发生于与外界相通的内脏，伴腐败菌感染、肿胀恶臭。气性坏疽有捻发感及大量气体。黑色素瘤为色素性肿块"},{"q":"患者，男，17岁。身体瘦弱。近日咳嗽乏力，晚间睡觉常出虚汗，胸部X光片检查发现右肺上叶锁骨上下有絮状阴影，首先应考虑的诊断是","o":["大叶性肺炎","间质性肺炎","周围型肺癌","浸润型肺结核","局灶型肺结核"],"a":3,"e":"青少年、消瘦盗汗乏力，X线见右肺上叶锁骨上下边缘模糊的云絮状阴影，符合浸润型肺结核，为继发性肺结核最常见的活动性类型。局灶型肺结核为肺尖边界清楚的增生性病灶，多无症状。大叶性肺炎为整叶实变并高热铁锈色痰。周围型肺癌为孤立结节"},{"q":"患者，女，50岁。双上肢剧烈颤抖，双手甚，走路出现剪刀步，全身僵硬，易摔倒，同时不停震颤导致肌肉酸痛，不能坐，无法进食。此病人可能患有","o":["胶质瘤","脑膜瘤","海绵状脑病","阿尔茨海默病","帕金森病"],"a":4,"e":"静止性震颤、肌强直、运动减少、姿势步态异常，走路呈剪刀步、易跌倒，为黑质多巴胺能神经元变性所致帕金森病的典型表现，镜下见路易小体。阿尔茨海默病以进行性痴呆为主。海绵状脑病进展迅速伴肌阵挛。脑膜瘤为局灶性占位，引起定位体征"},{"q":"患者，男，46岁。因消化性溃疡突然呕血而致失血性休克，面色苍白，四肢湿冷，神志清醒，血压110/96mmHg，此时患者可能处于","o":["休克早期","休克期","休克晚期","失代偿期","DIC"],"a":0,"e":"消化性溃疡大出血后交感神经兴奋，外周血管收缩使血压尚维持在110/96mmHg而脉压减小，神志清醒、面色苍白、四肢湿冷，属微循环收缩期的休克早期。休克期血压明显下降、意识淡漠。休克晚期出现DIC及多器官功能衰竭。失代偿期即休克期"},{"q":"患者，男，35岁。近期出现乏力、厌食、肝区疼痛。据调查，患者有长期和乙型肝炎患者密切接触史。患者应首先检查","o":["肝穿刺活检","肝炎病毒标记物","腹部B超","胃肠钡餐造影","CT"],"a":1,"e":"有与乙型肝炎患者密切接触史，出现乏力、厌食、肝区疼痛，应首先检测乙肝表面抗原等病毒标记物以明确病原。肝穿刺活检为有创检查，须在明确指征后进行。腹部B超和CT用于观察肝脏形态及有无占位。胃肠钡餐造影对肝病无诊断价值"},{"q":"患者，男，40岁。因肝右叶肝癌而行肝叶切除术，患者的肝脏最有可能发生的病理变化是","o":["经过较长时间，恢复肝脏原结构","保持手术后剩余肝脏的状态","肝脏肝小叶不断增生","肝脏形成若干再生结节","肝脏纤维组织大量增生"],"a":0,"e":"肝脏再生能力很强，肝叶切除后残存肝细胞在生长因子刺激下增殖，经较长时间可恢复原有体积和肝小叶结构。再生结节是肝硬化时肝细胞增生被纤维间隔包绕形成的异常结构。纤维组织大量增生是肝硬化的表现。保持术后剩余状态不符合肝脏的代偿性增生规律"},{"q":"患者，男，55岁。自述肝区疼痛，同时伴有食欲不振，消化不良。B超显示，肝脏体积缩小，脾脏肿大。患者无病毒性肝炎、酗酒等病史，实验室检查发现感染华支睾吸虫。该患者可能的诊断是","o":["门脉性肝硬化","坏死后性肝硬化","寄生虫性肝硬化","淤血性肝硬化","胆汁性肝硬化"],"a":2,"e":"华支睾吸虫寄生于胆管，虫体及代谢产物长期刺激致胆管周围纤维组织增生，形成寄生虫性肝硬化。门脉性肝硬化多由乙型或丙型肝炎、慢性酒精中毒引起。坏死后性肝硬化源于大块状坏死。淤血性肝硬化见于慢性右心衰竭。胆汁性肝硬化由肝内外胆道长期梗阻所致"},{"q":"某患者呼吸骤停，血气分析结果如下：pH：7.19，PaCO2： 70mmHg， HCO3-：26mmol/L，可诊断为","o":["代谢性碱中毒","急性呼吸性酸中毒","慢性呼吸性酸中毒","代谢性酸中毒","呼吸性酸中毒合并代谢性碱中毒"],"a":1,"e":"呼吸骤停致肺泡通气急剧减少，CO2潴留使PaCO2升至70mmHg，HCO3-尚在正常范围，pH降至7.19，为急性呼吸性酸中毒。慢性呼吸性酸中毒因肾代偿HCO3-明显升高。代谢性酸中毒HCO3-降低、PaCO2代偿性下降。代酸合并代碱时pH可正常或接近正常"},{"q":"患者，男，45岁。精神混乱、多尿、烦渴、便秘加重2天，急诊入院。5年前因烧伤右手臂患慢性骨髓炎。体格检查深部肌腱反射减弱。在检查过程中，患者也表现出明显的不适和无方向感，并且不配合。EKG显示QT间期缩短。实验室指标如下：血钙5、94mmol/L，血清白蛋白1.45mmol//L，BUN：1.4mg/dl，PTH：12pg/dl，碱性磷酸酶980U/L，该患者可能出现的电解质紊乱是","o":["高钙血症","低钙血症","低钾血症","高钾血症","高镁血症"],"a":0,"e":"长期骨髓炎、制动致骨钙动员增加，血钙5.94mmol/L明显升高，出现多尿烦渴、精神混乱、肌腱反射减弱及心电图QT间期缩短，符合高钙血症。低钙血症表现为手足搐搦、QT延长。低钾血症有U波和弛缓性瘫痪。高镁血症时血钙不升高"},{"q":"患者，男，45岁。有长期“胃痛”史。曾诊断胃溃疡病。此次病理活检诊断为腺癌。镜下诊断的主要依据应是","o":["腺上皮异常增生","呈浸润性生长，有角化珠形成","癌细胞呈腺管样结构","癌细胞异型性明显，核分裂多见","癌细胞染色深、核仁明显"],"a":2,"e":"腺癌的诊断依据是瘤细胞形成腺管或腺样结构，胃黏膜腺上皮来源的恶性肿瘤据此确诊。角化珠和细胞间桥是鳞状细胞癌的依据。异型性明显、核分裂象多、核深染是恶性肿瘤的共性，不能区分组织学类型。浸润性生长亦为恶性共性"},{"q":"一患者因血压升高、水肿严重1周就诊，10年前曾确诊为慢性肾小球肾炎，实验室检查发现内生肌酐清除率为22ml/min，尿比重固定在1.008~1.012。该患者最可能的诊断是","o":["少尿型ARF","非少尿型ARF","CRF肾功能不全期","CRF肾衰竭期","尿毒症"],"a":3,"e":"内生肌酐清除率22ml/min、尿比重固定于1.008～1.012，提示肾小管浓缩功能丧失、肾功能严重受损，属慢性肾衰竭肾衰竭期。肾功能不全代偿期清除率50～80ml/min。氮质血症期25～50ml/min。尿毒症期低于10ml/min并出现全身中毒症状"},{"q":"患者，男，80岁。近一年来，出现严重记忆力下降，经常喊错家人的名字，出门找不到家，CT显示大脑出现普遍性萎缩。上述表现提示此人患有","o":["胶质瘤","脑膜瘤","海绵状脑病","阿尔茨海默病","帕金森病"],"a":3,"e":"老年起病，进行性记忆力下降、认错家人、找不到回家路，CT示大脑普遍性萎缩，符合阿尔茨海默病，镜下见老年斑、神经原纤维缠结。帕金森病以震颤、强直、运动减少为主。海绵状脑病进展迅速伴肌阵挛。脑膜瘤为局灶占位，不引起弥漫性萎缩"},{"q":"患者，女，25岁。面部蝶形红斑，反复出现发热及关节肿痛，病程迁延反复。肾活检可见，肾小球内大量内皮下免疫复合物沉积，并出现苏木素小体。该患者的肾脏病变符合","o":["系膜增生性肾小球肾炎","局灶性肾小球肾炎","膜性肾小球肾炎","弥漫增生型狼疮性肾炎","快速进行性肾小球肾炎"],"a":3,"e":"面部蝶形红斑、发热关节痛提示系统性红斑狼疮，肾活检见肾小球内皮下大量免疫复合物沉积及苏木素小体，为弥漫增生型狼疮性肾炎，是急性期的特征性病变。膜性狼疮性肾炎以上皮下沉积和钉突为主。系膜增生型病变较轻。快速进行性以新月体为特征"},{"q":"消化道溃疡患者服用过多碳酸氢钠，导致酸碱失衡，血气分析结果表现为pH：7.50，PaCO2：48mmHg，HCO3ˉ：36mmol/L，可判断为","o":["代偿性代谢性碱中毒","代偿性呼吸性碱中毒","失代偿性代谢性碱中毒","失代偿性呼吸性碱中毒","代谢性碱中毒合并呼吸性酸中毒"],"a":2,"e":"大量服用碳酸氢钠使HCO3-升至36mmol/L，pH 7.50高于正常上限，PaCO2代偿性升高但不足以使pH回到正常，为失代偿性代谢性碱中毒。代偿性者pH应在正常范围。呼吸性碱中毒PaCO2降低。代谢性碱中毒合并呼吸性酸中毒时pH可不升高"},{"q":"患者，男，65岁。糖尿病患者，自己使用胰岛素治疗，结果出现四肢肌肉无力、腹胀、心律失常等表现。该患者最可能的诊断为","o":["低钠血症","低钙血症","高钠血症","高钾血症","低钾血症"],"a":4,"e":"胰岛素促使钾离子随葡萄糖进入细胞，加之用量偏大，血钾降低，出现四肢无力、腹胀即肠麻痹及心律失常。低钾时心电图T波低平、出现U波。高钾血症多发生于少尿、肾功能不全，T波高尖。低钠血症以意识障碍和抽搐为主。低钙血症表现为手足搐搦"},{"q":"患者，女，25岁，3 天前开始出现咽痛、咳嗽等症状，体温38.0℃，无其他明显不适症状。请问下列哪项处理原则不恰当","o":["尽快找出原发病并进行治疗","立刻给予药物解热","注意补充营养物质和水","注意休息避免劳累","必要时可给予物理降温"],"a":1,"e":"体温38℃属低热，此时解热药可掩盖病情、干扰热型判断，且出汗可致脱水，故不宜立刻使用，应先查明病因，予休息、补液及物理降温。物理降温用于高热或超高热。补充营养与水分、休息均为合理措施。找原发病并治疗是根本原则"},{"q":"某慢性肾衰竭患者，病久逐渐出现肾性佝偻病，其发病机制主要是","o":["水钠代谢失调","钾代谢失调","钙磷代谢失调","镁代谢失调","氮质血症"],"a":2,"e":"慢性肾衰时肾单位减少，磷排出受阻致血磷升高、血钙降低，刺激甲状旁腺增生，继而骨钙动员、骨盐溶解，儿童期骨骺生长障碍形成肾性佝偻病，核心是钙磷代谢失调。水钠失调引起水肿和高血压。钾代谢紊乱致心律失常。氮质血症为毒素蓄积表现"},{"q":"某幽门梗阻患者发生反复呕吐，血气分析结果为pH：7.5，最可能的酸碱平衡紊乱类型是","o":["代谢性酸中毒","代谢性碱中毒","呼吸性酸中毒","呼吸性碱中毒","混合型酸碱平衡紊乱"],"a":1,"e":"幽门梗阻反复呕吐，大量胃酸即HCl丢失，同时伴氯和细胞外液丢失，HCO3-相对增多，pH 7.5，为代谢性碱中毒。代谢性酸中毒见于腹泻及肾衰。呼吸性碱中毒由过度通气使CO2排出过多所致，PaCO2降低。混合型需两项原发紊乱并存"},{"q":"患者，男，60岁。患高血压数年。近1个月来头痛、头晕伴恶性、呕吐，测血压为180/100mmHg，清晨起床时家属发现患者死亡，患者死前小便失禁。患者最可能的死亡原因是","o":["肾功能衰竭","眼底出血","脑出血","右心衰竭","下肢坏疽"],"a":2,"e":"长期高血压、血压骤升并伴头痛呕吐、意识障碍，夜间死亡且小便失禁，提示基底节区大片脑出血破入脑室或致脑疝。脑出血是高血压最常见的致死并发症。肾功能衰竭为渐进过程，多有少尿和尿毒症表现。眼底出血只影响视力。右心衰竭以体循环淤血为主"},{"q":"一肝功能不全患者，突然出现嗜睡，唤之可醒，伴明显精神错乱，见扑翼样震颤，提示该患者处于肝性脑病的哪一期","o":["前驱期","昏迷前期","昏睡期","昏迷期","震颤期"],"a":2,"e":"患者嗜睡但唤之可醒，伴明显精神错乱及扑翼样震颤，属肝性脑病第三期即昏睡期。前驱期仅有轻度性格改变和睡眠颠倒，扑翼样震颤可不明显。昏迷前期以意识错乱、行为异常为主，尚无明显嗜睡。昏迷期不能被唤醒，腱反射消失"},{"q":"某患者血气检查的结果：血氧容量20ml/dl（正常值为20ml/dl），动脉血氧含量19ml/dl(正常值为19ml/dl)，动脉血氧分压100mmHg(正常值为100mmHg)，动-静脉血氧含量差6ml/dl(正常值为5ml/dl)。请判断该患者的缺氧类型","o":["低张性缺氧","循环性缺氧","血液性缺氧","乏氧性缺氧","组织性缺氧"],"a":1,"e":"动脉血氧分压、血氧容量及动脉血氧含量均正常，说明外呼吸与血红蛋白携氧无异常；动静脉血氧含量差增至6ml/dl，提示血流缓慢使组织从单位血液中摄取氧增多，符合循环性缺氧。低张性缺氧动脉血氧分压降低。血液性缺氧血氧容量降低。组织性缺氧时动静脉氧含量差减小"},{"q":"患者，男，40岁。背部红、肿、热、痛7天，表面有3个溃破口，流黄色凝乳状液体，按之深部有波动感。其病变最可能的病因是","o":["溶血性链球菌感染","大肠杆菌感染","金黄色葡萄球菌感染","绿脓杆菌感染","变形杆菌感染"],"a":2,"e":"背部红肿热痛、有多个溃破口并深部波动感，为痈，脓液呈黄色凝乳状，符合金黄色葡萄球菌感染，该菌产生血浆凝固酶使病变局限并形成脓肿。溶血性链球菌引起蜂窝织炎，脓液稀薄、扩散迅速。大肠杆菌多见于肠道及泌尿道感染。绿脓杆菌脓液呈蓝绿色并有特殊臭味"},{"q":"某患者肺泡-动脉氧分压差为60mmHg,吸纯氧30分钟后无改善，最可能发生的情况是","o":["解剖分流增加","功能分流增加","弥散障碍","肺泡扩张受限","气道阻塞"],"a":0,"e":"肺泡-动脉氧分压差明显增大，吸纯氧30分钟仍无改善，说明存在血液未经肺泡换气即流入动脉的真性分流，即解剖分流。功能性分流由通气/血流比例失调引起，提高吸氧浓度可使PaO2上升。弥散障碍吸氧后明显改善。肺泡扩张受限和气道阻塞属通气障碍，吸氧亦有效"},{"q":"某运动员在训练时发生股骨骨折，因处理不当，大量脂肪滴进入血液。该运动员出现呼吸困难，咳嗽、咳粉红色泡沫状痰。推测该运动员体内脂肪栓子可能栓塞于","o":["左心房","左心室","肺静脉及其分支","肺动脉及其分支","主动脉分支"],"a":3,"e":"骨折后骨髓脂肪滴入血，随体静脉回流进入右心，最终栓塞于肺动脉及其分支，引起肺栓塞，出现呼吸困难、咳嗽及粉红色泡沫痰。左心房、左心室及主动脉分支属体循环途径，栓子须经肺毛细血管或心内分流方能到达。肺静脉位于肺内，接受肺循环回流"},{"q":"女性，65岁，经确诊为慢性支气管炎，肺气肿12年，此次感冒后再次发作，呼吸困难加重且伴有口唇发绀入院，未经吸氧，下列的血气指标结果与之相符的是","o":["PaO2降低，PaCO2升高","PaO2正常，PaCO2升高","PaO2降低，PaCO2正常","PaO2正常，PaCO2降低","PaO2降低，PaCO2降低"],"a":0,"e":"慢性支气管炎合并肺气肿患者肺泡通气不足、通气/血流比例失调，感冒后急性加重，出现低氧血症伴二氧化碳潴留，故PaO2降低而PaCO2升高，属Ⅱ型呼吸衰竭。PaCO2正常见于早期单纯低氧血症。PaCO2降低提示过度通气。PaO2正常不符合发绀和呼吸困难"},{"q":"患者右小腿皮肤破溃不愈合半年就诊，见破溃处为火山口状溃疡，边缘较硬灰白色，伴明显出血、坏死。此病变最可能的诊断是","o":["皮肤鳞癌","皮肤慢性炎症","皮肤扁平苔藓","皮肤老年疣","皮肤良性溃疡"],"a":0,"e":"小腿慢性溃疡呈火山口状、边缘隆起质硬、底部坏死出血，为鳞状细胞癌向深部浸润并坏死脱落的表现，需活检确诊。良性溃疡边缘整齐、底部为肉芽组织，无硬结。皮肤慢性炎症无隆起硬边。老年疣为良性表皮增生，表面呈疣状。扁平苔藓为紫红色多角形丘疹"},{"q":"一患者因充血性心力衰竭和心律失常入院，主诉近期胃口差，伴恶心、呕吐、腹泻，记忆力减退，夜不成寐，家人诉说其“口臭”严重，检查发现其皮肤色素颜色较深，表面附有白色结晶。其最可能的诊断是","o":["CRF肾功能不全期","CRF肾衰竭期","尿毒症","少尿型ARF","非少尿型ARF"],"a":2,"e":"尿毒症时毒素蓄积引起尿毒症性胃肠炎、周围神经病变及心包炎，尿素随汗液排出在皮肤表面形成白色结晶即尿素霜，并刺激皮肤致色素沉着，口中有氨味。肾功能不全期仅有氮质血症而无全身中毒。肾衰竭期症状较轻。急性肾衰少尿型病程短，不以多系统症状为主"},{"q":"患者，男，69岁。恶性肿瘤晚期出现全身严重消耗状态，体重减轻。其全身性萎缩发生的原因最主要是","o":["压迫性萎缩","失用性萎缩","去神经性萎缩","内分泌性萎缩","营养不良性萎缩"],"a":4,"e":"恶性肿瘤晚期蛋白质摄入不足而消耗增多，全身肌肉及脂肪组织分解，形成恶病质，属营养不良性萎缩。压迫性萎缩见于脑积水、肿瘤压迫。失用性萎缩见于长期制动。去神经性萎缩见于下运动神经元损伤。内分泌性萎缩见于靶腺缺乏激素刺激"},{"q":"患者，男，63岁。吸烟，反复咳嗽，咳白色泡沫痰20余年，气促10年，近两天因受寒后出现发热伴咳黄脓痰，气喘不能平卧，查体双肺语颤减弱，可闻及散在干湿性啰音，心界缩小，心率110次/分，该患者最可能的诊断是","o":["慢性支气管炎急性发作","支气管哮喘","支气管扩张","肺结核","肺癌"],"a":0,"e":"老年吸烟者长期咳嗽咳白色泡沫痰，受寒后痰转黄脓、气喘，符合慢性支气管炎急性发作，致病菌多为肺炎链球菌、流感嗜血杆菌。支气管哮喘为发作性呼气性呼吸困难、可逆。支气管扩张以大量脓痰和咯血为特征。肺结核有低热盗汗。肺癌为刺激性干咳或肿块"},{"q":"患者，女，35岁，两下肢严重挤压伤，面色苍白，四肢湿冷，血压90/70mmHg。经初步抗休克处理后，患者出现进行性呼吸困难和缺氧，吸氧不能改善，患者最可能出现了","o":["输液过多","吸入性肺炎","心功能不全","急性呼吸窘迫综合征","呼吸道阻塞"],"a":3,"e":"严重挤压伤后经抗休克治疗，出现进行性呼吸困难且吸氧不能纠正的低氧血症，是创伤后全身炎症反应损伤肺泡毛细血管、形成透明膜所致，即急性呼吸窘迫综合征。输液过多致肺水肿吸氧可改善。心功能不全有颈静脉怒张、肝大。吸入性肺炎有误吸史及局灶实变"},{"q":"某冠心病病人，于剧烈运动后出现心绞痛症状，服用硝酸甘油不能缓解，遂拨打120求救。救护车于80分钟后将病人送到医院。医院为防治再灌注损伤采取的治疗措施中不包括","o":["低压、低流、低温灌注","高pH、高钙、高钠灌注","再灌注前给予SOD和CAT","给予牛磺酸","使用非甾体类抗炎药"],"a":4,"e":"再灌注损伤的防治包括低压、低流、低温灌注，再灌注前给予超氧化物歧化酶和过氧化氢酶清除氧自由基，以及牛磺酸等抗氧化剂。非甾体抗炎药抑制环氧合酶、减少前列腺素合成，用于镇痛解热，不属再灌注损伤的防治措施。控制再灌注条件应采用低钙、低钠液以减轻钙超载"},{"q":"在一肺组织切片中，可见多数细支气管壁充血水肿，并有大量中性粒细胞浸润，管腔内也有大量中性粒细胞。周围肺泡内有大量浆液脓性渗出物，此时最可能的诊断是","o":["大叶性肺炎","小叶性肺炎","支原体肺炎","病毒性肺炎","肺结核"],"a":1,"e":"病变以细支气管为中心，管壁充血水肿并有大量中性粒细胞浸润，周围肺泡充满浆液脓性渗出物，符合小叶性肺炎即支气管肺炎。大叶性肺炎为肺泡内大量纤维蛋白渗出，肺泡壁结构保存，不呈细支气管中心分布。支原体及病毒性肺炎为间质性炎，以淋巴细胞浸润为主"},{"q":"患者，女，58岁。咳嗽、咳痰8年，吸烟史20年，桶状胸，双肺可听到少量湿罗音，肝脾不大，最可能的诊断是","o":["大叶性肺炎","肺气肿","胸腔积液","支气管哮喘","肺癌"],"a":1,"e":"长期吸烟、慢性咳嗽咳痰，双肺湿啰音，桶状胸提示肺过度充气，符合慢性支气管炎并发肺气肿。大叶性肺炎急性起病、整叶实变。胸腔积液叩诊呈浊音、呼吸音减弱。支气管哮喘为发作性哮鸣、间歇期正常。肺癌多有肿块或肺不张"},{"q":"患者，男，55岁。出现严重的血尿和右腰部疼痛。体检发现腹部肿块。全血细胞计数（CBC）显示血红蛋白水平为21g/dL和红细胞增多。超声波显示右侧肾脏上极有一个6、0cm的肿块。患者红细胞增多症最可能的解释是","o":["肝细胞癌","卵巢癌","肾上腺皮质腺瘤","肾癌","肾积水"],"a":3,"e":"无痛性血尿、腰痛及腹部肿块为肾癌三联征，肿瘤分泌红细胞生成素样物质致红细胞增多，血红蛋白达21g/dL。肝细胞癌位于肝内，不引起肾脏肿块。卵巢癌位于盆腔。肾上腺皮质腺瘤引起Cushing综合征或醛固酮增多症。肾积水为尿路梗阻所致，无红细胞增多"},{"q":"某人夜间走山路时，发现有一黑影尾随而至，随即他心跳呼吸加快、拼命奔跑。此时其机体内主要发生","o":["交感－肾上腺皮质兴奋","交感－肾上腺髓质兴奋","肾素－血管紧张素分泌增多","假性神经递质分泌增多","血管加压素分泌增多"],"a":1,"e":"遭遇危险时交感神经兴奋，肾上腺髓质释放肾上腺素和去甲肾上腺素，心率加快、心输出量增加、血压升高、瞳孔扩大，属交感-肾上腺髓质系统兴奋。交感-肾上腺皮质系统通过ACTH促糖皮质激素分泌，起效慢。肾素-血管紧张素主要调节血压和水盐。血管加压素调节水重吸收"},{"q":"某中年男性患者，有胃溃疡病史多年，3小时前突然上腹部疼痛，继而全腹疼痛。本例应首先考虑的是","o":["胃溃疡出血","胃溃疡穿孔","幽门梗阻","胃溃疡癌变","胃酸刺激溃疡面引起疼痛"],"a":1,"e":"胃溃疡患者突发上腹剧痛并迅速波及全腹，提示溃疡穿透浆膜致胃内容物漏入腹腔引起弥漫性腹膜炎。出血表现为呕血和黑便，血压下降。幽门梗阻以呕吐宿食、胃扩张为主。癌变为渐进性消瘦、贫血及肿块。胃酸刺激溃疡面只引起规律性疼痛，不会全腹剧痛"},{"q":"患者，女，12岁。临床诊断为快速进行性肾小球肾炎，该疾病最具特征性的病变是","o":["基膜增厚","肾小球血管袢坏死","肾血管内膜纤维化","新月体形成","系膜细胞增生"],"a":3,"e":"急进性肾小球肾炎的组织学特征是球囊内壁层上皮细胞和单核细胞增生，形成新月体，故又称新月体性肾小球肾炎，临床迅速出现少尿和肾衰竭。基膜弥漫增厚是膜性肾小球病的特征。系膜细胞增生见于系膜增生性肾炎。肾血管内膜纤维化见于恶性高血压"},{"q":"患者，男，27岁。突发高热、寒战、头痛、全身酸痛，尤以肾区疼痛为甚。面色潮红，呈醉酒貌。全身皮肤散在瘀点、瘀斑，肾区叩痛。入院后抢救无效死亡。尸检：全身皮肤及黏膜散在瘀点及瘀斑，睑结膜充血、出血。肺、肾表面可见点状出血，右心房出血。镜检：肾小球毛细血管充血，肾小管上皮细胞变性、坏死，肾小管管腔内可见各种管型，肾间质高度充血、水肿和弥漫性出血。可考虑诊断为","o":["伤寒","大叶性肺炎","流行性出血热","钩端螺旋体病","急性肾盂肾炎"],"a":2,"e":"高热、头痛、全身酸痛、颜面潮红呈醉酒貌，皮肤瘀点瘀斑，肾区叩痛，尸检见肾间质弥漫性出血及肾小管坏死，符合汉坦病毒所致流行性出血热。钩端螺旋体病以腓肠肌压痛和黄疸为特点。伤寒为稽留热和玫瑰疹。急性肾盂肾炎有尿路刺激征和脓尿"},{"q":"一心源性休克患者，血气测定结果如下：pH 7.31，其细胞外哪种离子的浓度易增加","o":["K+","Na+","Cl-","HCO3-","HPO42-"],"a":0,"e":"心源性休克时组织灌注不足、乳酸堆积，pH 7.31提示代谢性酸中毒；酸中毒时细胞外H+进入细胞内，细胞内K+移出以维持电中性，故细胞外钾浓度升高。钠、氯浓度无此规律性升高。HCO3-在酸中毒时被消耗而降低。磷酸盐主要参与细胞内缓冲，变化不明显"},{"q":"患者，女，59岁。下肢静脉血栓4年，治疗取血栓，触之质硬、致密，切割有砂砾感。该血栓可能继发的病理变化是","o":["机化","化生","纤维化","玻璃样变","钙化"],"a":4,"e":"血栓形成日久，钙盐沉积于变性坏死的血栓内，质地变硬、致密，切割时有砂砾感，为营养不良性钙化，最终形成静脉石。机化是肉芽组织取代血栓，质地变韧但无砂砾感。玻璃样变呈均质红染。化生是上皮或间叶组织转变为另一种成熟组织"},{"q":"某急性肾功能衰竭患者血气分析结果为pH：7.18，PaCO2：30mmHg，HCO3-：9mmol/L，该患者的心肌收缩力","o":["先增强后减弱","增强","不变","减弱","先减弱后增强"],"a":3,"e":"pH 7.18、HCO3- 9mmol/L、PaCO2 30mmHg，为失代偿性代谢性酸中毒。酸中毒时H+竞争性抑制Ca2+与心肌肌钙蛋白结合，并使血管对儿茶酚胺反应性降低，心肌收缩力减弱、心输出量下降。碱中毒时心肌收缩力增强。酸中毒不会先增强后减弱"},{"q":"患者，男，43岁。劳累时心悸、气短两年，加重伴夜间不能平卧3天。查体：血压120/75mmHg，心率100次/分，皮肤温度降低，双下肢水肿。胸部X线提示心脏向左侧扩大。上述哪项表现不属于心功能不全的代偿反应","o":["心率加快","血压正常","心脏扩大","皮肤温度降低","双下肢水肿"],"a":4,"e":"心功能不全代偿期通过心率加快维持心输出量、通过心脏紧张源性扩张和心肌肥大代偿，外周血管收缩使皮肤温度降低、血压尚可维持。双下肢水肿是静脉淤血、毛细血管流体静压升高所致，属失代偿表现。血压正常反映代偿有效。心率加快和心脏扩大均为代偿反应"},{"q":"11 岁儿童，锁骨上淋巴结肿大，约1.5cm×2.0cm ，活动度尚好。表面光滑，切面细腻、无出血坏死。镜下淋巴结结构消失，在大量的淋巴细胞当中可见到少量的 R-S 细胞及典型的镜影细胞。该例的正确诊断为","o":["外周T细胞淋巴瘤","非霍奇金淋巴瘤","小淋巴细胞淋巴瘤","霍奇金淋巴瘤","巨大淋巴结病"],"a":3,"e":"淋巴结结构破坏，在大量淋巴细胞背景中见少量R-S细胞及典型镜影细胞，为霍奇金淋巴瘤的诊断性改变。非霍奇金淋巴瘤无R-S细胞，呈单一克隆性淋巴细胞增生。小淋巴细胞淋巴瘤由成熟小淋巴细胞弥漫构成。巨大淋巴结病保留淋巴结结构，无镜影细胞"},{"q":"患者，男，63岁。因心慌胸闷2年，咳嗽气急30天入院。既往有高血压病，近一个月来症状加重，夜间不能平卧，咳嗽、咳粉红色泡沫状痰。X线检查双肺纹理增粗，心界扩大。患者肺部可能有哪些变化","o":["肺淤血","肺结核","肺梗死","间质性肺炎","大叶性肺炎"],"a":0,"e":"高血压、夜间不能平卧、咳粉红色泡沫痰，为左心衰竭致急性肺淤血、肺水肿，X线示肺纹理增粗、心界扩大。肺结核好发于上叶，有低热盗汗。肺梗死为楔形出血性梗死，伴胸痛和咯血。间质性肺炎以病毒或支原体感染为主，肺纹理呈网状"},{"q":"患儿，男，3岁。无任何诱因突发剧烈阵发性腹痛伴恶心、呕吐1天入院手术。术中见肠套叠。套叠肠管扩张，颜色暗红，局部发黑坏死。肠管的病变可诊断为","o":["肠缺血性梗死","肠出血性梗死","慢性肠炎","肠结核","肠动脉性充血"],"a":1,"e":"肠套叠使肠系膜静脉受压、动脉仍搏动，肠管高度淤血，发生出血性即红色梗死，肠管暗红发黑。贫血性梗死见于脾、肾、心等结构致密、侧支循环少的器官，呈灰白色。肠结核为干酪样坏死及环形溃疡。肠动脉性充血为局部动脉扩张，不引起坏死"},{"q":"某科技工作者长期处于超负荷紧张工作状态，近期因家庭问题出现精神烦躁、情绪焦虑，出现心前区不适。其最不可能发生的心血管系统改变是","o":["血压升高","心肌梗死","心绞痛","二尖瓣狭窄","心律失常"],"a":3,"e":"长期精神紧张使交感神经兴奋、儿茶酚胺升高，可致血压升高、冠状动脉痉挛诱发心绞痛甚至心肌梗死，并引起心律失常。二尖瓣狭窄由风湿性心内膜炎反复发作致瓣叶粘连、增厚，与精神应激无因果关系。故其最不可能出现。心律失常和心绞痛均属应激相关改变"},{"q":"患儿，男，8岁。约一周前出现喉咙痛，两天前开始发热，体温38.8°C，恶心和呕吐。尿量减少，尿液呈暗色、烟熏色，血压略高，手足和眼周出现水肿。该患儿最可能患有的疾病是","o":["膜性肾小球病","新月体性肾小球肾炎","系膜增生性肾小球肾炎","IgA肾病","急性弥漫性增生性肾小球肾炎"],"a":4,"e":"儿童链球菌感染后1～2周出现血尿、少尿、水肿和高血压，为急性弥漫性增生性肾小球肾炎，免疫荧光见IgG和C3颗粒状沉积。IgA肾病表现为感染后1～3天内反复发作性血尿，无水肿和高血压。膜性肾病多见于成人，表现为肾病综合征。新月体性肾炎进展迅速"},{"q":"患者，女，28岁。近两天出现尿频、尿急、尿痛，体温升高到38.2°C，尿培养有大肠杆菌菌群生长，使用抗生素后体温下降，症状好转，她最有可能患有的疾病是","o":["急性弥漫性增生性肾小球肾炎","尿路上皮癌","子宫内膜异位","急性肾盂肾炎","慢性肾盂肾炎"],"a":3,"e":"育龄女性出现尿频尿急尿痛、发热，尿培养大肠杆菌阳性，抗生素治疗有效，符合急性肾盂肾炎，为肾盂、肾间质和肾小管的化脓性炎。急性弥漫性增生性肾炎以血尿、水肿、高血压为主，尿培养阴性。尿路上皮癌为无痛性血尿。慢性肾盂肾炎有反复发作史及瘢痕形成"},{"q":"一位32岁女性近两天出现尿频、尿急、尿痛，体温升高到38.5°C，尿培养有大肠杆菌菌群生长，使用抗生素后体温下降，症状好转。之后症状反复发作，迁延数载，她最有可能发展为以下哪种疾病","o":["慢性硬化性肾小球肾炎","膀胱炎","子宫内膜异位","肾细胞癌","慢性肾盂肾炎"],"a":4,"e":"急性肾盂肾炎反复发作、迁延数载，可致肾间质纤维化、瘢痕形成及肾盂肾盏变形，发展为慢性肾盂肾炎，晚期出现肾性高血压和肾功能不全。慢性硬化性肾小球肾炎源于原发性肾小球疾病，双肾对称缩小。膀胱炎无发热及腰痛。肾细胞癌为肿块和血尿"},{"q":"患者，女，43岁。无明显诱因出现头痛、癫痫发作入院。入院后行头颅MRI显示左侧额叶、颞叶占位性病变，PET-CT示颅内多发不规则低密度灶，基因检测显示p53基因突变。上述检查结果提示病人可能患有","o":["胶质瘤","脑膜瘤","神经纤维瘤","神经鞘瘤","室管膜瘤"],"a":0,"e":"成人额叶、颞叶占位，多发不规则低密度灶，伴p53基因突变及癫痫、头痛，符合成人型弥漫性胶质瘤，好发于大脑半球。脑膜瘤位于脑外，增强均匀并有硬膜尾征。神经鞘瘤多位于听神经，边界清楚。室管膜瘤发生于脑室系统。神经纤维瘤为周围神经良性肿瘤"},{"q":"男性，50岁，高血压病史20年。近1月来，血压升高至180/110mmHg，出现头痛、头晕、眼花，有时恶心、呕吐，甚至意识模糊。符合本患者疾病的描述是","o":["脑出血","脑梗死","高血压危象","恶性高血压","心肌梗死"],"a":2,"e":"高血压患者血压骤升至180/110mmHg，出现剧烈头痛、头晕、眼花、恶心呕吐及意识模糊，为血压急剧升高致脑内细动脉痉挛和脑水肿，即高血压危象。恶性高血压舒张压常超过130mmHg，伴视盘水肿和肾衰竭。脑出血有偏瘫等局灶体征。脑梗死为缺血性局灶缺损"},{"q":"患儿，男，4岁。因突发高热、惊厥、昏迷被幼儿园老师紧急送到医院急诊。查体未见皮肤、黏膜出血点或瘀斑。询问老师得知，近期幼儿园有小朋友“拉肚子”。该患儿最可能的诊断是","o":["流行性出血热，失血性休克","受到惊吓，神经源性休克","先天性心脏病，心源性休克","暴发型流脑，感染性休克","中毒性菌痢，感染性休克"],"a":4,"e":"学龄前儿童急起高热、惊厥、昏迷，而无皮肤瘀点瘀斑，且有痢疾接触史，符合中毒性细菌性痢疾，病原为志贺菌，全身中毒症状重而肠道病变轻，可迅速发生感染性休克。暴发型流脑有广泛瘀点瘀斑。流行性出血热有醉酒貌和肾损害。神经源性休克有明确诱因且无高热"},{"q":"一尸检标本，见肾内细动脉壁呈均质、红染，原有结构消失，最有可能的病理变化是","o":["脂肪变","细胞水肿","玻璃样变","黏液样变","淀粉样变"],"a":2,"e":"肾内细动脉壁呈均质红染、原有结构消失，为血浆蛋白渗入血管壁并沉积所致的玻璃样变，是高血压良性期细动脉硬化的基本病变。脂肪变为细胞内脂滴空泡。细胞水肿表现为细胞肿大、胞质疏松淡染。黏液样变为间质内类黏液积聚。淀粉样变需刚果红染色阳性"},{"q":"患儿，男，8岁。暑假随父母到乡下奶奶家居住了2周。奶奶家养了鸡、鹅等家禽和猪、牛等家畜。在奶奶家居住期间曾多次被蚊子叮咬。回家后出现高热、嗜睡、抽搐、昏迷。该患儿最可能的诊断是","o":["流行性脑脊髓膜炎","流行性乙型脑炎","急性支气管炎","结核性脑膜炎","脑脓肿"],"a":1,"e":"夏秋季发病，有蚊虫叮咬史及猪、牛等家畜接触，急起高热、嗜睡、抽搐、昏迷，符合乙型脑炎病毒经三带喙库蚊传播的流行性乙型脑炎，病变为脑实质的变质性炎。流脑为化脓性脑膜炎，有皮肤瘀点。结核性脑膜炎起病缓慢。脑脓肿有化脓性感染灶"},{"q":"某患者行阑尾切除术后，其阑尾送病理检查。镜下可见阑尾各层均有中性粒细胞浸润，血管明显扩张充血，未见组织坏死或增生性改变，该患者可诊断为","o":["急性单纯性阑尾炎","急性蜂窝织炎性阑尾炎","急性坏疽性阑尾炎","慢性阑尾炎","坏疽性阑尾炎"],"a":1,"e":"炎症波及阑尾壁全层，各层均有大量中性粒细胞弥漫浸润伴血管扩张充血和炎性水肿，为急性蜂窝织炎性即化脓性阑尾炎。急性单纯性阑尾炎病变局限于黏膜及黏膜下层。坏疽性阑尾炎因血管受压出现梗死、坏死，阑尾呈暗红或黑色。慢性阑尾炎以纤维增生和淋巴细胞浸润为主"},{"q":"患者，男，43岁。突然出现大咯血，少尿，肉眼血尿，实验室检查：血肌酐、尿素氮水平升高，抗GBM抗体阳性，尿常规发现红细胞、蛋白质均阳性。该患者最可能患有","o":["急性弥漫性增生性肾小球肾炎","新月体性肾小球肾炎","IgA肾病","微小病变性肾病","膜性肾小球病"],"a":1,"e":"抗GBM抗体阳性，伴大咯血、血尿、少尿及肾功能急剧恶化，为肺出血肾炎综合征，肾小球内新月体形成，属新月体性肾小球肾炎。急性弥漫性增生性肾炎有链球菌感染史，不咯血，抗GBM阴性。IgA肾病为发作性血尿。微小病变性肾病表现为肾病综合征"},{"q":"以下哪项不是大面积烧伤患者形成静脉内血栓的原因","o":["浆液渗出引起血浆浓缩","进食减少致白蛋白水平降低","卧床治疗期间血流缓慢","组织因子释放入血引起血液凝固性增高","皮肤烧伤引起血管壁损伤"],"a":1,"e":"大面积烧伤后血浆大量渗出致血液浓缩、长期卧床使血流缓慢、组织破坏释放组织因子使血液凝固性增高、烧伤直接损伤血管内皮，三者共同构成血栓形成的条件。白蛋白降低只引起血浆胶体渗透压下降和水肿，与血栓形成无直接关系"},{"q":"患者，男，46岁。吸烟史20年，每日2～3包。近日咳嗽加重。支气管黏膜活检，可见黏膜被覆鳞状上皮，细胞无异型性。此种病理变化属于","o":["支气管黏膜萎缩","支气管黏膜鳞状上皮化生","支气管黏膜鳞状上皮增生","支气管鳞状细胞癌","支气管黏膜肥大"],"a":1,"e":"长期吸烟刺激使支气管黏膜的假复层纤毛柱状上皮被复层鳞状上皮取代，细胞无异型性，属鳞状上皮化生，是可逆的适应性改变。增生表现为细胞数目增多而仍为原上皮。萎缩为上皮变薄、体积缩小。鳞状细胞癌须有细胞异型性及突破基膜浸润"},{"q":"患者，女，40岁。两年前患胃癌并行胃大部切除术。三个月前体检B超提示右卵巢肿块，行卵巢切除术。卵巢标本活检，镜下示印戒细胞癌，并见低分化腺癌。该患者的卵巢病变可能是","o":["胃癌直接蔓延","胃癌淋巴道转移","胃癌血道转移","胃癌种植性转移","原发性卵巢癌"],"a":3,"e":"胃癌细胞侵及浆膜后脱落，种植于卵巢表面生长，形成富于黏液的印戒细胞癌，即Krukenberg瘤，属种植性转移。直接蔓延只累及邻近器官。淋巴道转移首先至胃周淋巴结及左锁骨上淋巴结。血道转移多至肝、肺。原发性卵巢癌多为浆液性或黏液性囊腺癌"},{"q":"患儿，男，4岁。因咳嗽、咳痰伴喘息3天，以支气管肺炎收入院。入院查体：体温39℃，呼吸30次/分，心率130次/分，口周青紫，双肺底可闻及湿性啰音，肝脏肋下3cm，下肢轻度水肿，该患儿最可能的诊断为支气管肺炎合并了","o":["左心衰竭","右心衰竭","全心衰竭","呼吸衰竭","急性心肌炎"],"a":1,"e":"支气管肺炎患儿出现肝肋下3cm、下肢水肿，提示肺动脉高压致右心负荷过重，发生右心衰竭，此为小儿肺炎的严重并发症。左心衰竭以肺淤血、端坐呼吸和咳粉红色泡沫痰为主。全心衰需左右心表现并存。呼吸衰竭以低氧和高碳酸血症为诊断依据。急性心肌炎以心律失常为主"},{"q":"患者，男，35岁。10年前诊断为急性乙型病毒性肝炎。最近B超显示，肝脏体积缩小，脾脏肿大，食管-胃底静脉曲张。患者可能的诊断是","o":["门脉性肝硬化","坏死后性肝硬化","血吸虫性肝硬化","淤血性肝硬化","胆汁性肝硬化"],"a":0,"e":"十年前患急性乙型肝炎，现肝体积缩小、脾大、食管胃底静脉曲张，为肝炎后肝硬化，在我国以乙型肝炎最常见，属小结节型即门脉性肝硬化。坏死后性肝硬化由大块状坏死引起，结节大而不规则。血吸虫性肝硬化有疫水接触史。胆汁性肝硬化有胆道梗阻和黄疸"},{"q":"肠伤寒患者，发热 2 天后，体温开始下降，伴周身大汗，此时治疗上应特别注意","o":["休息，吸氧","补充营养物质","补充维生素","补充水分和适量的电解质，防止脱水","药物解热"],"a":3,"e":"伤寒极期后体温骤降并大量出汗，易致血容量不足和电解质丢失，应补充水分及适量电解质以防脱水、维持循环稳定。此时用药物解热可致大汗虚脱并掩盖热型。休息、吸氧非关键措施。补充维生素不能纠正水盐失衡。补液以口服或静脉等渗液为主"},{"q":"患者，女，56岁。患高血压病数年。近半月来，患者下肢水肿明显，尿中出现大量泡沫并不易消退。患者尿液检查可能发现","o":["尿蛋白+～++","白细胞+++","红细胞+++","脓细胞+++","尿比重升高"],"a":0,"e":"高血压肾损害使肾小球滤过膜通透性增高，尿中出现以白蛋白为主的蛋白尿，表现为尿蛋白+～++，尿液表面泡沫增多且不易消退。白细胞和脓细胞大量出现提示尿路感染。红细胞+++提示肾小球性血尿。尿比重升高见于脱水。大量蛋白尿达3.5g/d以上才属肾病综合征范围"},{"q":"患者，男，50岁。右腹股沟疝，经疝修补术后，伤口抗拉力强度达到顶点的时间是","o":["一周","三周","五周","二个月","三个月"],"a":4,"e":"伤口愈合过程中胶原纤维不断沉积并重组，抗拉力强度逐渐增加，约3个月达到顶点，此后略有下降，故疝修补术后3个月强度最高。1周时以炎症和肉芽组织为主，抗拉力弱。3周胶原开始沉积。2个月仍在增强阶段。临床据此建议术后3个月内避免重体力劳动"},{"q":"患者，男，22岁。半月前感冒，咽部肿痛，经治疗后好转。但尿液镜检显示：血尿(++++)，蛋白(±)，肾组织活检免疫荧光镜下显示：系膜区IgA 和 C3大量块状沉积，可诊断为","o":["IgA肾病","系膜增生性肾小球肾炎","急性弥漫性增生性肾小球肾炎","新月体性肾小球肾炎","膜性肾小球病"],"a":0,"e":"上呼吸道感染后出现肉眼血尿，免疫荧光示系膜区IgA和C3呈团块状沉积，为IgA肾病的诊断依据，其血尿多在感染后1～3天内发作。系膜增生性肾小球肾炎以IgG和C3沉积为主，无IgA优势。急性弥漫性增生性肾炎有内皮及系膜细胞增生。膜性肾病为上皮下沉积"},{"q":"患者，男，48岁。临床反复出现发热、乏力、体重下降、全身淋巴结肿大。肢体、面部反复出现皮损斑块，近期腭部、牙龈也出现斑块，活检为血管肉瘤（Kaposi肉瘤）。该患者最可能患有的疾病是","o":["系统性硬化","梅毒","黏膜皮肤念珠菌病","AIDS","霍奇金淋巴瘤"],"a":3,"e":"发热、乏力、消瘦、全身淋巴结肿大，伴皮肤及口腔黏膜多发性紫红色斑块，活检为Kaposi肉瘤，提示严重免疫缺陷，符合艾滋病。Kaposi肉瘤由HHV-8引起，约30%的AIDS患者发生。梅毒有硬下疳和梅毒疹。系统性硬化以皮肤硬化和雷诺现象为特征。霍奇金淋巴瘤无Kaposi肉瘤"},{"q":"患者，男，65岁。患糖尿病10余年，昏迷入院。化验尿常规：尿蛋白（+),葡萄糖（+++），酮体（+）。入院后注射胰岛素72单位，并输入0、9%NaCL及乳酸钠，患者神志逐渐清楚，呼吸平稳，但出现烦躁不安，心律不齐等表现。实验室检查除出现血钾偏低外，还可能出现","o":["低钠血症","低钙血症","高钠血症","高镁血症","低镁血症"],"a":4,"e":"糖尿病酮症酸中毒经大量胰岛素和补液治疗后，钾、镁、磷随葡萄糖转运进入细胞，血镁降低，出现烦躁、心律不齐，与低钾血症并存。低钠血症多因补水过多或利尿，以意识障碍为主。低钙血症表现为手足搐搦。高镁血症引起反射减弱和血压下降。补镁可纠正"},{"q":"某球迷在世界杯比赛期间，高度关注自已支持的球队，熬夜看球，情绪随着球队的成绩而激烈变化。赛程进行1周后，该球迷出现腹痛、腹泻与便秘交替、食欲差。至世界杯赛结束后约1周，上述症状消失。该球迷最可能发生的是","o":["肠易激综合征","消化不良","急性肠炎","肠道肿瘤","慢性胃炎"],"a":0,"e":"长期精神紧张、情绪波动及作息紊乱通过脑-肠轴使肠道运动和感觉功能异常，出现腹痛伴腹泻与便秘交替，症状随应激解除而消失，符合肠易激综合征，肠道无器质性病变。急性肠炎有不洁饮食和发热。消化不良以上腹饱胀为主。肠道肿瘤呈进行性加重伴消瘦便血"},{"q":"患儿，男，5岁。因发热，呕吐，皮肤有出血点3天入院。治疗中出血点逐渐增多呈片状，出血点涂片检查见脑膜炎双球菌。血压由入院时的92/64mmHg降至60/40mmHg。进一步检查确诊为DIC，下述检查中哪项不支持DIC诊断","o":["血小板计数明显降低","凝血酶原时间延长","纤维蛋白原含量降低","3P试验阳性","凝血酶原时间缩短"],"a":4,"e":"DIC时凝血因子大量消耗并继发纤溶，血小板减少、凝血酶原时间延长、纤维蛋白原降低、3P试验阳性，均为诊断依据。凝血酶原时间缩短不符合DIC的消耗性低凝状态，故不支持诊断，见于高凝状态早期。该患儿有脑膜炎双球菌败血症，DIC诊断成立"},{"q":"患者，女，30岁。出现心悸2年，1个月前因牙痛拔牙后，开始发热，全身乏力，体检：皮肤有出血点，脾大，心尖区可闻及杂音。该患者最可能患有","o":["风湿病活动期","感冒、肺部轻微感染","亚急性感染性心内膜炎","风湿性心瓣膜病","急性感染性心内膜炎"],"a":2,"e":"原有心脏杂音，拔牙后出现发热、乏力、皮肤出血点及脾大，为草绿色链球菌等毒力较弱的细菌在受损瓣膜形成赘生物所致，符合亚急性感染性心内膜炎。急性感染性心内膜炎由金黄色葡萄球菌等强毒力菌引起，起病急、数日死亡。风湿病活动期无瘀点和脾大。风湿性瓣膜病本身不发热"},{"q":"某患者血氧指标检查为：动脉血氧分压100mmHg（正常为100mmHg），静脉血氧分压为55mmHg（正常为40mmHg），血氧容量20ml/dl（正常为20ml/dl），动脉血氧饱和度95%，动静脉氧含量差2、8ml/dl(正常为5ml/dl)。，此患者可有哪些类型缺氧","o":["低张性缺氧","循环性缺氧","血液性缺氧","组织性缺氧","淤血性缺氧"],"a":3,"e":"动脉血氧分压、血氧容量正常，说明外呼吸及携氧无障碍；静脉血氧分压升高至55mmHg，动静脉氧含量差减至2.8ml/dl，提示组织细胞利用氧障碍，静脉血氧未被充分摄取，符合组织性缺氧。循环性缺氧动静脉氧差增大。低张性缺氧动脉血氧分压降低。血液性缺氧氧容量降低"},{"q":"患儿，男，6岁。 脓血便8天，高热3天，多饮多尿，近两天乏力，呼吸困难2小时入院。体检，神志不清，口唇发绀，腹胀，肠鸣音消失，四肢呈迟缓性瘫痪，血钠140mmol/L，血钾2、6mmol/L，该患者最可能的诊断是","o":["低钠血症","低钙血症","低钾血症","高钾血症","高钠血症"],"a":2,"e":"脓血便后出现腹胀、肠鸣音消失及四肢弛缓性瘫痪，血清钾2.6mmol/L，为腹泻丢失钾及摄入不足所致低钾血症，低钾使骨骼肌和肠平滑肌兴奋性降低。高钾血症虽也致弛缓性瘫痪，但多伴少尿、肾功能不全及T波高尖。低钠血症以意识障碍为主。低钙血症表现为手足搐搦"},{"q":"患者，男，60岁。因胃癌广泛转移而死亡。尸体解剖检查，心脏重200g。切片检查心肌细胞核两侧可见黄褐色细颗粒状色素，此色素最可能是","o":["黑色素","胆色素","含铁血黄素","脂褐素","前角蛋白聚集"],"a":3,"e":"老年、恶性肿瘤消耗状态下，萎缩心肌细胞核两端出现黄褐色细颗粒色素，为自噬溶酶体未消化的细胞器残体，即脂褐素，又称消耗性色素。含铁血黄素见于陈旧性出血和肺淤血，普鲁士蓝染色阳性。黑色素为黑褐色颗粒。胆色素见于黄疸。前角蛋白聚集见于Mallory小体"},{"q":"患者，男，68岁。既往患冠心病10余年，近日出现慢性充血性心力衰竭合并慢性肺淤血。患者咳嗽、咳痰，呼吸困难，其特征性痰中应出现","o":["肺泡上皮细胞","心力衰竭细胞","异物巨细胞","中性粒细胞","朗汉斯巨细胞"],"a":1,"e":"慢性肺淤血时肺泡腔内红细胞被巨噬细胞吞噬，血红蛋白分解为含铁血黄素，形成胞质含棕黄色颗粒的心力衰竭细胞，可随痰排出，是慢性肺淤血的标志。肺泡上皮细胞脱落见于肺水肿但不含色素。异物巨细胞见于异物肉芽肿。朗汉斯巨细胞见于结核结节"},{"q":"患者，男，60岁。长期以来感觉上腹胀，出现空腹痛以及夜间痛，大便潜血阳性，幽门螺杆菌阳性。可诊断为","o":["早期胃癌","胃溃疡","慢性浅表性胃炎","十二指肠溃疡","慢性萎缩性胃炎"],"a":3,"e":"空腹痛和夜间痛、进食后缓解是十二指肠溃疡的典型节律，大便潜血阳性提示溃疡活动性出血，幽门螺杆菌阳性为重要病因。胃溃疡多为餐后痛。早期胃癌多无明显症状，可有潜血阳性但无周期性疼痛。慢性浅表性胃炎为上腹隐痛不适。慢性萎缩性胃炎伴胃酸降低和贫血"},{"q":"患者，女，30岁。腰椎结核并在腰椎旁形成冷脓肿，破溃后流脓不止。此处已形成","o":["空洞","瘘管","溃疡","窦道","糜烂"],"a":3,"e":"冷脓肿穿破皮肤后形成只有一个开口、经久不愈的盲管，为窦道。瘘管两端均有开口，连接两个器官或器官与体表。空洞为坏死物液化排出后残留的空腔。溃疡为皮肤黏膜的缺损。糜烂仅限于表皮浅层。脊椎结核的窦道需抗结核治疗并清创方能愈合"},{"q":"患者，男。1天前因煤气爆炸造成面部、前胸及上肢Ⅱ～Ⅲ度烧伤，面积达 40%，当地医院给予大量5%的葡萄糖溶液。次日转入某院，入院实验室检查血清钠 110mmol/L ，渗透压250mOsm/L 。该患者出现的水、钠代谢紊乱类型是","o":["水中毒","等渗性脱水","低渗性脱水","高渗性脱水","水肿"],"a":2,"e":"烧伤后大量体液渗出致失钠失水，又输入大量5%葡萄糖液而不补电解质，使细胞外液渗透压降至250mOsm/L、血钠110mmol/L，属低渗性脱水。水中毒为水潴留但无脱水体征、尿钠不低。高渗性脱水血钠高于150mmol/L。等渗性脱水血钠正常。治疗应补等渗盐水"},{"q":"中年女性，化验指标提示甲状腺功能低下，手术切除标本甲状腺弥漫性对称性肿大，稍呈结节状，质较韧，镜下见甲状腺正常结构破坏，有大量的淋巴细胞浸润、甲状腺滤泡萎缩。滤泡上皮常有嗜酸性变、纤维组织增生和淋巴滤泡形成，该患者最有可能的诊断是","o":["桥本甲状腺炎","慢性纤维性甲状腺炎","结节性甲状腺肿","乳头状癌","甲状腺腺瘤"],"a":0,"e":"中年女性甲状腺功能低下，甲状腺弥漫对称肿大、质韧，镜下大量淋巴细胞浸润并形成淋巴滤泡，滤泡萎缩、上皮嗜酸性变，为桥本甲状腺炎的典型改变，属自身免疫病。慢性纤维性甲状腺炎质硬如木、与周围组织粘连。结节性甲状腺肿无淋巴滤泡。乳头状癌有毛玻璃核"},{"q":"男性，62岁，因肺心病伴发呼吸衰竭入院，入院检查：血气结果如下：PaO2：30mmHg，PaCO2：60mmHg，经氧疗后患者病情恶化，血气数值变为：PaO2：70mmHg，PaCO2：80mmHg，分析原因最可能的是","o":["感染加重","气道阻力增加","心力衰竭加重","周围循环衰竭","氧疗方法不当"],"a":4,"e":"肺心病呼衰患者PaO2 30mmHg时，高浓度吸氧解除了低氧对外周化学感受器的驱动，呼吸抑制加重，CO2潴留使PaCO2由60升至80mmHg，病情恶化，属氧疗方法不当，应低浓度持续给氧。感染加重、气道阻力增加及心衰加重均为渐进过程，不会在吸氧后立即出现CO2骤升"},{"q":"患儿，女，5岁。因倦怠、食欲减退、潮热、盗汗就诊。该患儿呈营养不良体征，经检查发现结核菌素试验为阳性，X线胸片显示肺部呈哑铃状阴影，未见咳嗽、咯血及其他异常。考虑诊断为","o":["干酪样肺炎","小叶性肺炎","原发性肺结核","支原体肺炎","病毒性肺炎"],"a":2,"e":"儿童初次感染结核分枝杆菌，结核菌素试验阳性，X线见原发病灶、结核性淋巴管炎与肺门淋巴结肿大构成的哑铃状阴影，即原发复合征，诊断为原发性肺结核。干酪性肺炎为大片干酪样坏死实变。小叶性肺炎为沿支气管分布的化脓灶。支原体肺炎为间质性炎"},{"q":"HE染色切片，镜下见癌细胞弥漫浸润于胃壁全层，癌细胞胞质内有蓝染物质，核偏于一侧呈印戒样。该切片应诊断为","o":["印戒细胞癌","鳞癌","腺鳞癌","腺瘤","未分化癌"],"a":0,"e":"癌细胞弥漫浸润胃壁全层，胞质内充满黏液将核挤向一侧，呈印戒样，为印戒细胞癌，属低黏附性癌。鳞癌见角化珠和细胞间桥。腺鳞癌兼有腺癌与鳞癌两种成分。腺瘤为良性、有完整基膜。未分化癌缺乏腺管结构和黏液分泌"},{"q":"患者，男，55岁。慢性支气管炎、肺气肿10年。最近出现下肢水肿，呼吸气促、乏力，颈静脉怒张。同时B超显示，肝脏体积变小、脾脏肿大。患者肝脏可能出现的病变是","o":["门脉性肝硬化","坏死后性肝硬化","血吸虫性肝硬化","淤血性肝硬化","胆汁性肝硬化"],"a":3,"e":"慢性支气管炎、肺气肿致肺动脉高压和右心衰竭，长期肝淤血使肝细胞萎缩、坏死，纤维组织增生，形成淤血性肝硬化，肝体积缩小、脾大、颈静脉怒张。门脉性肝硬化多由肝炎或酒精引起。血吸虫性肝硬化有疫水接触史。胆汁性肝硬化由胆道梗阻所致"},{"q":"一慢性阻塞性肺部疾患的病人继发心力衰竭，血气分析结果表现为pH：7.31，PaCO2：62mmHg， HCO3-：30mmol/L，可诊断为","o":["代谢性酸中毒","呼吸性酸中毒","代谢性碱中毒","呼吸性碱中毒","呼吸性酸中毒合并代谢性碱中毒"],"a":1,"e":"慢性阻塞性肺疾病患者肺泡通气不足致CO2潴留，PaCO2 62mmHg，肾代偿使HCO3-升至30mmol/L，但pH仍降至7.31，为失代偿性呼吸性酸中毒。代谢性碱中毒HCO3-升高伴pH升高。呼吸性碱中毒PaCO2降低。呼吸性酸中毒合并代谢性碱中毒时pH可正常或升高"},{"q":"患者会出现典型的恐水、怕风、咽喉肌痉挛、进行性瘫痪等症状，应考虑诊断为","o":["狂犬病","流行性脑脊髓膜炎","钩端螺旋体病","伤寒","流行性乙型脑炎"],"a":0,"e":"狂犬病病毒沿周围神经逆行入脑，累及脑干和边缘系统，出现恐水、怕风、咽喉肌痉挛、吞咽困难及进行性瘫痪，病死率几乎100%。乙型脑炎以高热、抽搐、昏迷为主，无恐水。流脑为化脓性脑膜炎，有皮肤瘀点。钩端螺旋体病以腓肠肌压痛和黄疸为特征"},{"q":"患者，男，58岁。因进行性体弱、疲劳，劳力性呼吸困难1周入院。体检示心律不齐，双侧肺底部可闻及水泡音。胸片示肺水肿。给予地高辛和呋塞米治疗，3天后出现头晕，四肢肌肉无力、腹胀等表现。EKG显示T波低平，ST段降低，该患者可能出现的电解质紊乱类型是","o":["低钠血症","低钙血症","低钾血症","高钾血症","高钠血症"],"a":2,"e":"地高辛与呋塞米合用，呋塞米抑制肾小管对钠钾的重吸收致钾排出增多，出现头晕、四肢无力、腹胀及心电图T波低平、ST段压低，符合低钾血症，也是洋地黄中毒的诱因。低钠血症以意识障碍为主。低钙血症QT间期延长、手足搐搦。高钾血症T波高尖"},{"q":"患者，男，25岁。下肢骨折后，石膏固定2个月，使患侧肢体变细，肌肉萎缩，病理诊断属于","o":["压迫性萎缩","内分泌性萎缩","营养不良性萎缩","去神经性萎缩","失用性萎缩"],"a":4,"e":"骨折后石膏固定、肢体长期不活动，肌肉工作负荷减少、代谢降低，属失用性萎缩，患肢变细与骨质疏松并存。压迫性萎缩由肿物或积液长期挤压所致，如肾盂积水压迫肾实质；去神经性萎缩见于周围神经损伤后肌肉失去神经营养；营养不良性萎缩见于慢性消耗和饥饿"},{"q":"一患儿由于误吞了小玩具，出现呼吸困难症状。经检查玩具阻塞在中央气道的胸内段，患儿的呼吸困难表现为","o":["呼吸性呼吸困难","吸气性呼吸困难","呼吸和吸气均困难","呼吸和吸气困难交替出现","阵发性吸气困难"],"a":0,"e":"胸内段气管属胸内气道，呼气时胸内压高于气道内压，管腔受压变窄，故表现为呼气性呼吸困难，即选项所称呼吸性呼吸困难。吸气性呼吸困难见于喉及胸外段气管阻塞，如喉头水肿、声门异物；吸气和呼气均困难见于广泛肺病变所致的混合性呼吸困难"},{"q":"患者，女，55岁。数月前发现左肩部皮下有一肿物，活动度好。病理检查发现：送检组织似正常脂肪组织，呈不规则分叶状，由纤维间隔。该患者的病理诊断是","o":["脂肪瘤","平滑肌瘤","淋巴管瘤","囊腺瘤","纤维肉瘤"],"a":0,"e":"肿物位于肩背部皮下，镜下呈正常脂肪组织、不规则分叶并有纤维间隔，符合脂肪瘤。平滑肌瘤由梭形平滑肌束构成，多见于子宫和胃肠道；纤维肉瘤为异型梭形细胞呈鱼骨样排列的恶性肿瘤；脂肪肉瘤位于腹膜后深部，以查见脂肪母细胞为诊断依据"},{"q":"患者，女，34岁。孕10周时检查发现无胎心搏动，随行引产手术。术后第二天患者出现寒战、高热、呕吐等症。实验室检查：血红蛋白50g/L，白细胞总数26、6×109/L，中性粒细胞0.9。给予输血、抗感染等治疗，在交叉配血时发现患者外周血中有大量星型、盔型等形态各异的红细胞。该患者的贫血最有可能是","o":["感染性贫血","微血管病性溶血性贫血","失血性贫血","中毒性贫血","缺铁性贫血"],"a":1,"e":"引产后感染诱发弥散性血管内凝血，纤维蛋白在微血管内形成网架，红细胞通过时被切割成星形、盔形碎片，故为微血管病性溶血性贫血。失血性贫血为正细胞正色素性，红细胞形态完整；缺铁性贫血呈小细胞低色素性，均不出现红细胞碎片"},{"q":"患者，男，56岁，农民。双下肢活动无力、头晕头痛2天，加重2小时入院。患者行走不稳伴言语不利，时有恶心，查头部CT示：左侧腔隙性脑梗死。下列哪项病理学描述是错误的","o":["为出血性梗死","属液化性坏死","梗死灶颜色灰白","可见脑软化灶","可形成胶质瘢痕"],"a":0,"e":"脑组织富含脂质而蛋白质少，缺血后水解酶作用强，坏死呈液化性，形成灰白色软化灶，后期由星形胶质细胞增生形成胶质瘢痕。腔隙性脑梗死属贫血性梗死；出血性梗死见于肺、肠等双重血供或严重淤血的器官，故该项描述错误"},{"q":"患者，女，20岁。长期腹泻。电子肠镜检查：结肠密布大小不等的息肉，多达100余个，有蒂或无蒂。单个肿物切除活检，病理报告为：管状腺瘤。请问，该患者的疾病描述最可能是","o":["结肠多发管状腺瘤，可能与遗传因素有关","结肠多发性腺瘤性息肉，可能与免疫因素有关","结肠腺瘤性息肉病，可能与遗传因素有关","结肠腺瘤性息肉病，可能与免疫因素有关","结肠多发性腺瘤性息肉，可能与环境因素有关"],"a":2,"e":"结肠息肉多达百余枚、活检为管状腺瘤，符合家族性腺瘤性息肉病，系APC基因胚系突变所致的常染色体显性遗传病。散发性多发腺瘤性息肉数目少、无家族聚集，不以遗传因素为主；免疫因素与息肉病发生无关，环境因素仅参与散发性结直肠癌"},{"q":"患者，女，4岁。于外阴部发现一葡萄样肿物。病理检查发现：送检组织由不同分化阶段的横纹肌母细胞组成。该患者的病理诊断是","o":["脂肪瘤","平滑肌肉瘤","横纹肌肉瘤","尿路上皮癌","纤维肉瘤"],"a":2,"e":"肿瘤由不同分化阶段的横纹肌母细胞构成，主要见于10岁以下儿童，好发头颈及泌尿生殖道，呈葡萄状外观者属胚胎性横纹肌肉瘤。平滑肌肉瘤多见于中老年子宫和胃肠道，瘤细胞呈束状交织；纤维肉瘤由异型成纤维细胞构成，无横纹肌母细胞"},{"q":"患者，男，35岁。食用海鲜后出现黄疸，肝功能异常。据调查，购买同一批海鲜的多人出现相同症状。实验室检查，HAV（+）。病人可能的诊断是","o":["甲型病毒性肝炎","乙型病毒性肝炎","丙型病毒性肝炎","丁型病毒性肝炎","戊型病毒性肝炎"],"a":0,"e":"食用污染海产品后同批多人发病、HAV阳性，符合甲型病毒性肝炎，经粪-口传播，多表现为急性黄疸型。戊型肝炎亦经粪-口传播并可暴发，但血清学为HEV阳性；乙型、丙型和丁型主要经血液、母婴及性接触传播，与共食海鲜无关"},{"q":"患者，男，42岁。长期以来感觉上腹胀，食欲不振，体检未见明显异常，胃镜检查显示：黏膜充血、水肿，表面有灰白色或灰黄色分泌物。诊断为","o":["早期胃癌","胃溃疡","慢性浅表性胃炎","慢性萎缩性胃炎","慢性肥厚性胃炎"],"a":2,"e":"胃镜下黏膜充血、水肿，覆灰黄或灰白色黏液性渗出物，而腺体完整无萎缩，是慢性浅表性胃炎的表现，炎症限于黏膜浅层。慢性萎缩性胃炎以黏膜变薄、血管透见及肠上皮化生为特点；早期胃癌呈局灶凹陷或隆起；胃溃疡为圆形黏膜缺损"},{"q":"男性，65岁，查体发现动脉粥样硬化。请问下列检查指标中升高的可能性最小的是","o":["TG","HDL","LDL","ox-LDL","VLDL"],"a":1,"e":"HDL参与胆固醇逆向转运并抗氧化、抑制LDL氧化，对动脉粥样硬化有保护作用，故升高可能性最小，其水平降低才是危险因素。LDL与VLDL为致AS脂蛋白，ox-LDL损伤内皮并促泡沫细胞形成，TG升高也属常见脂代谢异常"},{"q":"患儿，男，9岁，主诉头痛、头晕乏力，半月前曾患有急性咽喉炎，体检发现其面部水肿，血压160/100 mmHg。少尿，尿液分析显示血尿和轻度蛋白尿。他最可能患有的疾病是","o":["微小病变性肾小球病","新月体性肾小球肾炎","膜性肾小球病","急性弥漫性增生性肾小球肾炎","IgA肾病"],"a":3,"e":"咽部感染后约10天出现水肿、血尿、少尿和高血压，为急性弥漫性增生性肾小球肾炎的典型经过，系循环免疫复合物沉积致内皮及系膜细胞增生。微小病变性肾小球病仅表现为肾病综合征，无血尿和高血压；新月体性肾炎肾功能急剧恶化，多见于成人"},{"q":"患者，女，50岁。胃痛半年。胃镜检查胃窦部有一3cm×4cm的不规则溃疡；B超示双侧卵巢肿大。病理检查发现，卵巢活检病理图像与胃活检图像一致。下列推测中哪一项是错误的","o":["胃内病灶是原发灶","卵巢病灶为转移灶","卵巢转移灶为种植性转移所致","患者患有胃癌和卵巢癌","胃癌伴卵巢转移"],"a":3,"e":"胃癌种植转移至双侧卵巢形成Krukenberg瘤，卵巢病变为转移性黏液腺癌而非原发卵巢癌，故“患者患有胃癌和卵巢癌”错误。该转移经腹腔种植，胃为原发灶；卵巢转移癌多双侧、实性，镜下见印戒细胞，与原发卵巢癌不同"},{"q":"患者，男，54岁。体检时发现血压升高，160/98mmHg。服药或休息后血压可降至正常。此患者血压升高可能是由于","o":["细动脉硬化","全身细小动脉痉挛","大动脉粥样硬化","动脉中层钙化","广泛性细小动脉坏死"],"a":1,"e":"血压波动、休息或服药后可降至正常，属高血压功能紊乱期，全身细小动脉间歇性痉挛而尚无器质性改变。细动脉硬化属动脉病变期，管壁玻璃样变使血压持续升高、失去波动性；大动脉粥样硬化因管壁弹性下降致收缩压升高、脉压增大"},{"q":"某患者血气分析结果为：pH 7.20，PaCO2 71mmHg，HCO3ˉ 27mmol/L，最可能的酸碱平衡紊乱类型是","o":["无酸碱平衡紊乱","代偿性酸中毒","代偿性碱中毒","失代偿性酸中毒","失代偿性碱中毒"],"a":3,"e":"PaCO2明显升高而HCO3尚在正常范围、pH降低，提示CO2潴留超过肾脏代偿，为失代偿性呼吸性酸中毒。代偿性酸中毒时经肾代偿HCO3相应升高、pH可维持正常；代谢性酸中毒以HCO3原发降低、PaCO2代偿性下降为特征"},{"q":"某糖尿病患者血气分析结果：pH：7.30，PaCO2：33mmHg，HCO3-：16mmol/L，血Na+：140mmol/L，Cl-：104mmol/L，K+：3.5mmol/L，可诊断为","o":["急性呼吸性酸中毒","慢性呼吸性酸中毒","AG正常型代谢性酸中毒","AG增高型代谢性酸中毒","呼吸性酸中毒合并代谢性酸中毒"],"a":3,"e":"AG为140减104减16，等于20mmol/L，明显增高，提示酮酸、乳酸等未测阴离子蓄积，为AG增高型代谢性酸中毒，见于糖尿病酮症。AG正常型见于腹泻致HCO3丢失、血氯相应升高；呼吸性酸中毒以PaCO2升高为原发改变，本例PaCO2降低属代偿"},{"q":"肺结核患者发热 1 周，伴精神差，食欲下降，尿液检查时出现尿酮，其原因是","o":["糖原分解增强","脂肪分解增强","蛋白质分解增强","维生素消耗增多","皮肤、呼吸道水分蒸发增多"],"a":1,"e":"发热使分解代谢增强、食欲下降致糖供给不足，脂肪动员加速，脂肪酸在肝内氧化不全生成酮体，出现酮尿。糖原分解增强仅补充血糖，不产生酮体；蛋白质分解增强主要引起负氮平衡和消瘦，与酮体生成无直接关系"},{"q":"一慢性肝炎、肝硬化并有严重肝功能不全的病人，急诊入院时出现意识障碍、手足抽搐等表现，提示出现了哪种酸碱平衡紊乱","o":["代谢性酸中毒","呼吸性酸中毒","呼吸性碱中毒","代谢性碱中毒","呼吸性酸中毒合并代谢性酸中毒"],"a":2,"e":"肝功能严重障碍时血氨升高刺激呼吸中枢，通气过度使CO2排出增多，形成呼吸性碱中毒；碱中毒使血浆游离钙减少、神经肌肉兴奋性增高，出现手足抽搐。代谢性碱中毒多由剧烈呕吐、低钾或利尿剂引起；代谢性酸中毒表现为深大呼吸，不出现抽搐"},{"q":"某男，60岁。因胃部不适、消瘦、贫血3个月入院。经胃镜活检诊断为胃腺癌。从抑制细胞增殖信号转导过弱的角度分析，其发生的分子基础最有可能是","o":["表皮生长因子受体过度表达","信号转导分子类蛋白异常表达","TGF-βII型受体突变","sis基因激活","int-2基因激活"],"a":2,"e":"TGF-β经其Ⅱ型受体抑制上皮细胞增殖，受体突变使抑制信号减弱、细胞增殖失控，与胃癌发生相关。表皮生长因子受体过度表达、sis及int-2基因激活均属促进增殖的信号增强，不属抑制信号减弱"},{"q":"患者，男，12岁。以慢性骨髓炎收入院。入院后病理检查发现：送检组织异型性明显，梭形或多边形，直接形成肿瘤性骨样组织。X线检查可见Codman三角。本病例最可能的诊断是","o":["脂肪瘤","骨肉瘤","横纹肌肉瘤","血管肉瘤","纤维肉瘤"],"a":1,"e":"肿瘤细胞异型明显并直接形成肿瘤性骨样组织，伴Codman三角，为骨肉瘤的诊断依据，多见于青少年长骨干骺端。软骨肉瘤见于中老年，以软骨小叶和软骨基质为特点，无肿瘤性骨样组织；纤维肉瘤无成骨现象"},{"q":"女性患者，23岁，近期多食，但人渐消瘦，出现心悸、多汗、怕热、易激动等症状，颈部肿大，眼球突出，其可能的临床诊断是","o":["Graves病","单纯性甲状腺肿","桥本甲状腺炎","Riedel甲状腺肿","甲状腺腺瘤"],"a":0,"e":"多食而消瘦、心悸多汗怕热、易激动，伴甲状腺弥漫性肿大和突眼，是Graves病的典型表现，由促甲状腺激素受体抗体持续刺激所致。单纯性甲状腺肿无甲亢症状；桥本甲状腺炎多表现为质韧结节性肿大及甲减；Riedel甲状腺肿质硬如木，常压迫致声嘶"},{"q":"黄嘌呤脱氢酶转变为黄嘌呤氧化酶需要","o":["镁依赖性蛋白水解酶","锌依赖性蛋白水解酶","钙依赖性蛋白水解酶","铜依赖性蛋白水解酶","铁依赖性蛋白水解酶"],"a":2,"e":"缺血缺氧使细胞内钙超载，激活钙依赖性蛋白水解酶，将黄嘌呤脱氢酶转化为黄嘌呤氧化酶，后者催化次黄嘌呤生成尿酸并产生大量氧自由基。锌依赖性蛋白酶指基质金属蛋白酶，参与细胞外基质降解，与此转化无关"},{"q":"不符合蕈样肉芽肿特点的描述是","o":["原发于皮肤","T细胞来源","形成Pautrier微脓肿","细胞核高度扭曲","好发于儿童"],"a":4,"e":"蕈样肉芽肿为原发于皮肤的成熟T细胞淋巴瘤，瘤细胞核高度扭曲呈脑回状并侵入表皮形成Pautrier微脓肿，多见于中老年男性。好发于儿童的是淋巴母细胞性淋巴瘤和Burkitt淋巴瘤，故该项不符合其特点"},{"q":"患者，女，36岁。因车祸致股骨粉碎性骨折，整复时突然死亡，其原因最可能是","o":["脑动脉粥样硬化","伤口感染后引起脑膜脑炎","股静脉血栓形成","骨折源性脂肪栓塞","左心房球形血栓脱落"],"a":3,"e":"长骨粉碎性骨折时骨髓脂肪滴进入破裂的静脉窦，经右心入肺，直径大于20μm者阻塞肺动脉分支，可引起急性呼吸循环衰竭而猝死，整复时更易发生。股静脉血栓形成需较长时间；脑动脉粥样硬化不会在整复时突然致死"},{"q":"患者，男，58岁。有慢性肝炎史20余年。近半年来恶心、乏力伴肝区疼痛。B超示肝右叶有一直径2cm大小的肿物，血液AFP阳性。肝穿刺活检显示：肿瘤细胞类似肝细胞，细胞间有丰富的血窦样腔隙。该患者最有可能的诊断是","o":["肝硬化","肝腺瘤","早期肝癌（小肝癌）","肝转移癌","肝胆管细胞癌"],"a":2,"e":"慢性肝炎背景、AFP阳性、肝右叶直径2cm的单发结节，癌细胞似肝细胞且血窦丰富，符合早期肝癌中的小肝癌。肝腺瘤无肝炎背景、AFP不升高；肝内胆管细胞癌由腺管状排列的癌细胞构成，AFP阴性；转移癌多为多发结节"},{"q":"患者，男，20岁。剧烈运动时不慎扭伤左踝关节以致骨折，到骨伤科医院进行了及时良好的复位、固定后，其骨折部位最可能的结果是","o":["骨折处由软骨代替","骨折处由纤维组织代替","骨折处由骨组织代替，但不能恢复原状","骨折处完全愈合，恢复正常的结构和功能","骨折处由纤维组织、软骨组织、骨组织混合增生代替"],"a":3,"e":"单纯外伤性骨折经良好复位固定后，骨再生能力强，数月内可完全愈合，恢复原有结构和功能。骨折处由纤维组织或软骨代替属愈合过程的中间阶段，停留于此即为延迟愈合或不愈合；不能恢复原状多见于复位不良或合并感染"},{"q":"某溺水窒息患儿，血气分析结果为：pH 7.16，PaCO2 75mmHg，HCO3ˉ 26mmol/L，其主要依靠下列哪种方式代偿","o":["碳酸氢盐缓冲系统","血红蛋白的缓冲作用","肺的调节作用","肾脏的调节作用","骨骼的代偿作用"],"a":1,"e":"急性呼吸性酸中毒时肾脏代偿需3至5天才启动，急性期主要靠血红蛋白缓冲，HHb与H2CO3作用生成HCO3并释放O2。碳酸氢盐缓冲系统主要缓冲固定酸；肺本身因窒息通气障碍不能起代偿作用，故不选肺的调节"},{"q":"患者，男，65岁。确诊肝癌1年余。患者烟龄10多年，每天吸烟1包。有饮酒史20多年，每天约2两。喜食腌制食品。经常上夜班。与该患者肝癌发生关系最密切的致瘤因素是","o":["吸烟","饮酒","亚硝胺类物质","作息不规律","遗传因素"],"a":1,"e":"患者有20余年每日饮酒史，乙醇在肝内代谢为乙醛，引起酒精性肝炎、肝硬化并进展为肝细胞癌，与肝癌关系最密切。吸烟主要与肺癌相关；亚硝胺类物质与胃癌、食管癌关系密切；作息不规律不是独立致瘤因素"},{"q":"患者，男，65岁。因骨折卧床数月，近一月来常咳嗽，并咳黄色黏脓痰。查体：双肺下叶可闻及湿啰音；X线片示双肺下叶不规则散在小片状模糊阴影。最有可能的诊断是","o":["大叶性肺炎","小叶性肺炎","慢性支气管炎","支气管扩张","支气管哮喘"],"a":1,"e":"长期卧床、咳黄脓痰、双下肺湿啰音及散在小片状模糊阴影，符合坠积性小叶性肺炎，病变以细支气管为中心呈化脓性炎。大叶性肺炎累及整个肺叶、咳铁锈色痰，X线呈大片均匀致密影；支气管扩张以反复咯血和卷发样阴影为特点"},{"q":"患者，女，74岁。由于长期卧床导致下肢深静脉血栓形成，若栓子脱落，最可能发生的是","o":["肺动脉栓塞","脾动脉栓塞","肾动脉栓塞","肝门静脉栓塞","肾静脉栓塞"],"a":0,"e":"下肢深静脉血栓脱落后经静脉、右心进入肺动脉，引起肺动脉栓塞，是体循环静脉血栓最常见的后果。脾动脉、肾动脉栓塞的栓子来自左心或主动脉；肝门静脉栓塞多由门静脉系统血栓引起，与下肢血栓无关"},{"q":"患者，男，65岁。吸烟史40年，近一个月来咳嗽、痰中带血。X线示右肺近肺门处不规则阴影，边界不清，痰菌阴性，可能的诊断为","o":["慢性支气管炎","大叶性肺炎","小叶性肺炎","肺癌","炎性假瘤"],"a":3,"e":"长期吸烟、痰中带血伴肺门区不规则肿块，是中央型肺癌的表现，癌肿起源于主支气管或叶支气管。慢性支气管炎仅有纹理增粗而无肿块；大叶性肺炎呈大片实变影并有急性感染症状；炎性假瘤边界清楚、生长缓慢"},{"q":"患者，男，67岁。尿毒症并发肺部、泌尿系统的严重感染，下列哪项是患者并发感染的原因","o":["体液免疫受到明显抑制","细胞免疫受到明显抑制","B淋巴细胞数量相对减少","心衰致供血不足","负氮平衡致恶病质"],"a":1,"e":"尿毒症毒素抑制T淋巴细胞转化及中性粒细胞趋化和吞噬功能，细胞免疫明显受损，故易并发肺部及泌尿系统感染。体液免疫相对保留，B淋巴细胞数量减少不明显；心力衰竭和负氮平衡可加重病情，但不是感染的主要原因"},{"q":"患者，女，50岁。发作性胸痛1个月，常放射至左肩，左臂内侧，每次发作含硝酸甘油后缓解。患者可能的诊断是","o":["心绞痛","心肌梗死","左心衰竭","心内膜炎","心外膜炎"],"a":0,"e":"发作性胸痛向左肩及左臂内侧放射，含硝酸甘油后迅速缓解，为心绞痛的典型特点，系心肌暂时缺血引起的反射性疼痛。心肌梗死疼痛持续30分钟以上、含药不缓解，常伴大汗和心律失常；左心衰竭以呼吸困难为主"},{"q":"患者，女，53岁。因咳嗽及右侧胸痛不适入院，X线示右肺下叶近胸膜处见一直径3cm的球形阴影，边界不清，抗生素及抗结核治疗不见好转，痰脱落细胞学检查见可疑腺癌细胞。该患者最有可能的诊断是","o":["肺鳞状细胞癌","肺小细胞癌","肺结核","小叶性肺炎","肺腺癌"],"a":4,"e":"肿块位于胸膜下、边界不清，抗感染抗结核治疗无效，痰中查见可疑腺癌细胞，符合周围型肺腺癌，女性及非吸烟者多见。鳞癌多位于肺门、与吸烟密切相关；小细胞癌为中央型、早期即广泛转移；结核病灶多有钙化及卫星灶"},{"q":"患者，男，24岁。临床反复出现发热、乏力、肺部感染、体重下降、全身淋巴结肿大。血清示HIV-1阳性。该患者体内HIV-1攻击的细胞是","o":["CD4+T淋巴细胞","CD8+T淋巴细胞","B淋巴细胞","嗜酸性粒细胞","中性粒细胞"],"a":0,"e":"HIV-1的gp120与CD4分子结合，并借助CCR5或CXCR4辅助受体进入细胞，故主要攻击CD4+T淋巴细胞，使其进行性减少。CD8+T细胞、B细胞和粒细胞不表达CD4，不被直接感染，其数量和功能下降属继发改变"},{"q":"患者，男，23岁，持续高热伴腹泻8天，大便每天5~6次，偶有黏液，右下腹隐痛。体检：肝脏右肋下2cm，脾脏左肋下1cm，躯干背侧隐约可见米粒大小淡红色皮疹，压之退色。血液检查未见白细胞升高。大便检查见少许白细胞及脓细胞，培养无致病菌。应诊断为","o":["细菌性痢疾","阿米巴病","食物中毒","伤寒","急性肠炎"],"a":3,"e":"持续高热、相对缓脉、脾大、躯干玫瑰疹及白细胞不升高，是伤寒的典型表现，病原为伤寒沙门菌，经粪-口传播。细菌性痢疾以脓血便、里急后重、白细胞升高为特点；阿米巴痢疾大便呈果酱样、中毒症状轻；食物中毒潜伏期短、集体发病"},{"q":"患者，男，45岁。患风湿性心内膜炎10年，近日发热，白细胞增多，皮肤黏膜见出血点。住院治疗期间，医嘱绝对卧床休息。今晨病人自行起床，数分钟后突感头痛，呕吐，左下肢麻木，倒地死亡。该患者最可能的死因是","o":["心肌梗死","脑出血","肺动脉栓塞","肺炎","脑动脉栓塞"],"a":4,"e":"风湿性心内膜炎患者发热、皮肤黏膜出血点，提示并发亚急性感染性心内膜炎，左心瓣膜赘生物脱落随体循环入脑，阻塞脑动脉致猝死。肺动脉栓塞的栓子来自右心或静脉系统；脑出血多有高血压及颅内血管病变，本例无相应基础"},{"q":"某男孩，出生后即出现多尿、烦渴、多饮等症状，注射加压素后尿量不减少，尿比重不增加，血浆ADH浓度正常。患儿出现该病最可能的原因是","o":["精神因素","下丘脑神经垂体部位的肿瘤","神经细胞退行性病变","ADHV2受体合成减少或结构异常","ADH-神经垂体素运载蛋白基因突变"],"a":3,"e":"注射加压素后尿量不减、尿比重不升，而ADH浓度正常，提示肾小管对ADH不反应，属肾性尿崩症，因V2受体合成减少或结构异常所致。垂体性尿崩症由下丘脑-神经垂体病变致ADH缺乏，注射加压素后尿量明显减少"},{"q":"6岁女童，不慎从滑梯跌落摔伤，右下肢皮肤大面积破损。治疗修复期间，除注意补充蛋白质等营养物质外，还需注意补充","o":["维生素C和锌","维生素C和维生素B","铁和锌","维生素D和钙","维生素A和维生素C"],"a":0,"e":"维生素C是脯氨酸、赖氨酸羟化酶的辅助因子，缺乏时前胶原分子难以形成，胶原合成障碍；锌是多种氧化酶的成分，缺乏同样延缓愈合，故创面修复需补充二者。维生素D和钙主要影响骨矿化，铁缺乏主要引起贫血"},{"q":"一患者严重低钾血症，血钾浓度为2、5mol/L，导致呼吸肌麻痹，出现呼吸困难。治疗上除了常规补钾外，还需要进行给氧治疗。给氧原则是","o":["间歇性低浓度吸氧","慢速高浓度给氧","正压低浓度给氧","持续性低浓度低流量给氧","持续高浓度高流量给氧"],"a":3,"e":"低钾致呼吸肌麻痹时通气不足，兼具缺氧和CO2潴留，属Ⅱ型呼吸衰竭，应持续低浓度低流量给氧，借低氧刺激维持呼吸中枢驱动。高浓度吸氧可解除低氧对颈动脉体的刺激，加重CO2潴留甚至引起肺性脑病"},{"q":"患者，女，23岁。急诊收入院。寒战，高热，铁锈色痰。查体：体温39、8℃，左肺闻及湿啰音，X线胸片显示：左肺下叶大片状致密阴影。给予抗生素治疗，2天后症状减轻。该患者最可能患的疾病是","o":["大叶性肺炎","小叶性肺炎","病毒性肺炎","慢性支气管炎","肺脓肿"],"a":0,"e":"寒战高热、铁锈色痰、左下肺湿啰音及大片致密阴影，抗菌治疗有效，符合肺炎链球菌所致大叶性肺炎，病变为肺泡内纤维蛋白性炎。小叶性肺炎以细支气管为中心呈小片状阴影；病毒性肺炎间质受累、白细胞多不升高；肺脓肿可见空洞和液平"},{"q":"某患者的血气检查结果：动脉血氧分压100mmHg（正常为100mmHg），血氧容量12ml/dl（正常值为20ml/dl），动脉血氧含量11.4ml/dl（正常值为19ml/dl），动-静脉血氧含量差3.5ml/dl(正常值为5ml/dl)，患者为哪种疾病的可能性比较大","o":["慢性支气管炎","急性呼吸窘迫综合征","慢性阻塞性肺疾病","慢性充血性心力衰竭","慢性贫血"],"a":4,"e":"PaO2正常而血氧容量和血氧含量成比例下降，提示血红蛋白数量减少，即慢性贫血；心输出量代偿性增加又使动-静脉血氧含量差缩小。慢性心力衰竭时动脉血氧分压降低、动-静脉差增大；慢性阻塞性肺疾病和ARDS均以低氧血症为特征"},{"q":"患儿，4个月，因抽搐入院，患儿近两天发热抽搐，一天4～5次，抽搐后吃奶好。体检，体温38℃，发育营养好，精神好，咽充血，有颅骨软化，枕秃明显，前囟平。实验室检查：血清总钙1.7mmol/L，离子钙1.0mmol/L。该患儿可能出现的电解质紊乱是","o":["低磷血症","高钙血症","高钠血症","高镁血症","低钙血症"],"a":4,"e":"血清总钙1.7mmol/L、离子钙1.0mmol/L，伴颅骨软化、枕秃及反复抽搐，为维生素D缺乏性低钙血症，神经肌肉兴奋性增高所致。高钙血症多由甲状旁腺功能亢进或骨转移引起，表现为乏力多尿；低磷血症见于再喂养综合征，不引起手足抽搐"},{"q":"手术中见肝有一肿物，无明显境界，颜色暗红，切开可见肿物呈囊状，其间有许多红褐色液体流出，镜检见多量管腔，管壁厚薄不均并扩张迂曲，管腔内有多量红细胞。此瘤可诊断为","o":["肝癌","肝血管瘤","肝腺瘤","肝淋巴管瘤","肝囊状水瘤"],"a":1,"e":"肿物暗红、囊状，内含血性液体，镜下见壁厚薄不均、扩张迂曲的血管腔并充满红细胞，符合肝海绵状血管瘤。肝癌为异型肝细胞构成的实性肿块，伴出血坏死；肝淋巴管瘤腔内含淋巴液而非血液；肝腺瘤由分化良好的肝细胞索构成"},{"q":"患者，女，30岁。右卵巢肿物6cm×5cm，切面囊实性，可见油脂样物及毛发。镜下见成熟表皮、毛囊和皮脂腺结构，还见到支气管柱状上皮、纤维脂肪组织等，此肿瘤诊断为","o":["成熟型畸胎瘤","未成熟型畸胎瘤","卵巢癌","毛发上皮瘤","混合瘤"],"a":0,"e":"囊内见油脂、毛发，镜下同时有成熟表皮及附件、支气管柱状上皮和脂肪组织，为三个胚层成熟组织构成的成熟型畸胎瘤。未成熟型畸胎瘤含未成熟神经组织，多见于年轻患者、恶性度高；卵巢癌无毛发油脂；毛发上皮瘤为皮肤附属器良性肿瘤"},{"q":"患者，男，20岁。高热4天，咳铁锈色痰，查体左肺上部叩诊浊音，呼吸音弱，其胸片表现最大可能是","o":["左上肺纹理增粗","双肺散在片絮状阴影","左上肺淡薄片状模糊阴影","左上肺大片状均匀致密阴影","左上肺淡薄不均阴影，可见少许透亮区"],"a":3,"e":"大叶性肺炎红色及灰色肝样变期肺泡腔内充满纤维蛋白性渗出物，实变区呈大片状均匀致密阴影，与叩诊浊音、呼吸音减弱一致。纹理增粗见于支气管炎；淡薄片状模糊影为充血水肿期表现；透亮区提示空洞形成，见于肺脓肿或结核"},{"q":"患者，女，23岁。因心悸气短、夜间无法平卧2月，发热1周入院。10年前被诊断为“风湿热”，未系统治疗。查体：睑结膜有瘀点，在大拇趾尖端掌面有一紫红色结节，有压痛。体温38、0℃，脉搏120次/分，主动脉听诊区可闻及舒张期叹气样杂音。尿常规：少量蛋白。血常规：WBC 9.9×109/L，中性粒细胞0.84，淋巴细胞0.16、最可能的诊断是","o":["上呼吸道感染","急性肾小球肾炎","风湿热","亚急性感染性心内膜炎","主动脉瓣关闭不全"],"a":3,"e":"原有风湿性瓣膜病者出现发热、睑结膜瘀点、趾端痛性结节及主动脉瓣舒张期杂音，符合亚急性感染性心内膜炎，多由甲型溶血性链球菌引起，赘生物脱落可致栓塞。风湿热无瘀点和Osler结节；上呼吸道感染不能解释瓣膜杂音和栓塞表现"},{"q":"患儿，女，12岁。近5个月来反复发热，大关节出现游走性红、肿、痛，同时患儿有乏力，不爱活动，稍活动后即有心跳加快。入院检查，诊断为风湿性心肌炎，风湿性关节炎。此种关节炎关节腔可见到的病变是","o":["化脓性炎","坏死性炎","浆液纤维素性炎","假膜性炎","肉芽肿性炎"],"a":2,"e":"风湿性关节炎为变态反应性炎症，关节腔渗出以浆液和纤维蛋白为主，故称浆液纤维素性炎，积液可完全吸收而不留关节畸形。化脓性炎由化脓菌引起、脓液含大量中性粒细胞；肉芽肿性炎见于结核；假膜性炎发生于黏膜表面，如菌痢和白喉"},{"q":"患者，男，45岁。体格检查时发现结肠肠腔内有一带蒂赘生物，活检组织送病理科检查，镜下显示主要为增生的肠黏膜上皮腺体细胞和少量肉芽组织，最可能的诊断是","o":["炎性假瘤","炎性息肉","炎性肉芽肿","息肉状腺瘤","黏膜淋巴瘤"],"a":1,"e":"镜下以增生的肠黏膜腺体和肉芽组织为主，符合炎性息肉，系慢性炎症刺激下黏膜上皮与肉芽组织增生所形成。息肉状腺瘤以异型增生的腺上皮为主体、无显著肉芽组织，属真性肿瘤；炎性假瘤为纤维组织及炎细胞构成的瘤样病变"},{"q":"患者，女，18岁，食欲不好，厌油腻，肝大，肝区疼痛，临床诊断为急性普通性肝炎，此时患者肝出现的病变为","o":["以实质变质为主","以间质变质为主","以浆液渗出为主","以中性粒细胞渗出为主","以纤维素渗出为主"],"a":0,"e":"急性普通型肝炎属变质性炎，以肝细胞水肿、嗜酸性变及点状坏死为主，渗出和增生均轻微。间质变质为主者见于结缔组织的黏液样变性；浆液渗出为主见于浆液性炎；中性粒细胞渗出为主提示化脓性炎；纤维素渗出为主见于大叶性肺炎"},{"q":"患者，男，36岁。反复咳嗽，咳痰，体温38、5度，WBC：12×109/L（正常值4～10×109/L），X线胸片显示在右肺下叶有大片致密阴影。抗病毒治疗无效。该患者最有可能的诊断是","o":["大叶性肺炎","小叶性肺炎","病毒性肺炎","慢性支气管炎","肺结核"],"a":0,"e":"高热、白细胞升高、右下肺大片致密阴影且抗病毒治疗无效，提示细菌感染所致大叶性肺炎，病变为肺泡内纤维蛋白性渗出。小叶性肺炎呈散在小片状阴影；病毒性肺炎白细胞不升高、病变位于肺间质；肺结核多位于上叶尖后段并有钙化"},{"q":"患者，女，50岁。患慢性萎缩性胃炎20余年，现因胃癌行胃大部切除术。手术切除标本显示整个胃腔缩小，胃壁增厚变硬，呈“革囊胃”。该患者胃癌的大体形态类型属于","o":["浸润型","息肉型","溃疡型","胶样癌","隆起型"],"a":0,"e":"癌组织在胃壁内弥漫浸润，使胃壁增厚变硬、胃腔缩小呈革囊胃，属浸润型胃癌，预后差。隆起型向腔内呈息肉状或盘状突起；溃疡型形成火山口状溃疡；胶样癌切面呈半透明胶冻状，由大量黏液分泌所致"},{"q":"某患儿因窒息急诊入院，血气分析为：pH 7.19，标准条件下测得HCO3-的浓度为24mmol/L，隔绝空气的条件下测得HCO3-的浓度为30mmol/L，该患儿最可能出现的酸碱平衡紊乱是","o":["代谢性酸中毒","急性呼吸性酸中毒","急性呼吸性碱中毒","慢性呼吸性酸中毒","混合性酸碱平衡紊乱"],"a":1,"e":"窒息使CO2排出受阻、PaCO2骤升，HCO3尚在正常范围而pH下降，符合急性呼吸性酸中毒；隔绝空气所测HCO3偏高，反映血中CO2蓄积后部分转化为HCO3。慢性呼吸性酸中毒经肾代偿HCO3明显升高、pH接近正常；代谢性酸中毒以HCO3原发降低为特征"},{"q":"患者，女，35岁。近段时间病人食欲不振，腹胀，右腹部疼痛不适 。查体：肋缘下2cm触及肝脏，按压有疼痛。未明确诊断，应首先做下列哪项检查","o":["肝炎病毒标记物","腹水检查","胃肠钡餐造影","超声心动图","腹部B超"],"a":0,"e":"患者有肝大、肝区压痛及消化道症状，病毒性肝炎是最常见病因，检测肝炎病毒标志物可明确病原分型并指导治疗，应作为首选。腹部B超用于排除肝占位和胆道梗阻，属形态学检查；腹水检查适用于已有腹水者；钡餐造影和超声心动图与本例无关"},{"q":"患者，男，68岁。反复咳嗽、咳痰20年，伴心悸2年。体检：双肺叩诊呈过清音，呼吸音减弱，肺底部有湿啰音，剑突下心尖搏动明显，该处可闻及3/6级收缩期杂音，肺动脉瓣区第二音亢进。该例最可能的诊断为","o":["慢性支气管炎","慢支+肺气肿","慢支+肺气肿+肺心病","慢支+风湿性心瓣膜病","慢支+右心功能不全"],"a":2,"e":"长期咳痰伴桶状胸、过清音提示肺气肿，剑突下心脏搏动和肺动脉瓣区第二音亢进提示肺动脉高压及右心室肥厚，故为慢支、肺气肿合并肺心病。单纯慢支无过清音；风湿性瓣膜病有相应杂音；右心功能不全应出现肝大和下肢水肿"},{"q":"患者，女，50岁。近3年来，活动后出现胸痛，常放射至左肩，左臂内侧，每次发作含硝酸甘油后缓解。近半年来，疼痛加剧、发作频繁。今日清晨患者上楼后胸痛发作，持续30分钟未见缓解，大汗、面色苍白，可能诊断为","o":["心绞痛","心肌梗死","左心衰竭","心内膜炎","心外膜炎"],"a":1,"e":"胸痛持续30分钟不缓解、含硝酸甘油无效，伴大汗和面色苍白，提示冠状动脉持续阻塞致心肌坏死，即心肌梗死。心绞痛发作短暂、休息或含药后数分钟缓解；左心衰竭以呼吸困难和粉红色泡沫痰为主；心内膜炎疼痛与体位、呼吸相关"},{"q":"患者，女，25岁。患风湿病5年。听诊可闻及心包摩擦音。心包腔内渗出物的特征性成分应该是","o":["淋巴细胞","纤维素","中性粒细胞","巨噬细胞","红细胞"],"a":1,"e":"风湿病累及心包时多为纤维蛋白性心包炎，渗出物以纤维蛋白为主，附着于心包脏壁两层之间，随心脏搏动摩擦产生心包摩擦音。中性粒细胞为主者为化脓性心包炎；浆液性心包炎渗出以浆液为主，积液增多时摩擦音反而不明显"},{"q":"患者，男，10岁，腹痛2天，伴有发热，呕吐。初始疼痛部位不确定，后疼痛逐渐集中于右下腹，体温38.5℃。医生诊断为急性蜂窝织炎性阑尾炎，决定立即手术。切除的阑尾送病理科检验，镜下检查以哪种细胞为主","o":["淋巴细胞","巨噬细胞","嗜酸性粒细胞","中性粒细胞","浆细胞"],"a":3,"e":"急性蜂窝织炎性阑尾炎属化脓性炎，阑尾壁各层弥漫中性粒细胞浸润，伴充血水肿和纤维蛋白渗出，故镜下以中性粒细胞为主。淋巴细胞和浆细胞为主提示慢性阑尾炎；嗜酸性粒细胞增多见于寄生虫感染或过敏性疾病"},{"q":"患者，男，60岁。长期以来感觉上腹胀，食欲不振，近3个月体重明显减轻。胃镜检查显示：胃窦部位黏膜变薄，颜色灰暗，病变黏膜下血管清晰可见。周围正常黏膜隆起。最可能的诊断为","o":["慢性浅表性胃炎","慢性萎缩性胃炎","急性刺激性胃炎","胃溃疡","早期胃癌"],"a":1,"e":"胃窦黏膜变薄、颜色灰暗、黏膜下血管透见，是慢性萎缩性胃炎的胃镜特征，伴腺体减少和肠上皮化生。慢性浅表性胃炎黏膜充血水肿、呈淡红色，血管不能透见；胃溃疡为圆形溃疡；早期胃癌呈局灶性凹陷或隆起"},{"q":"男性患者，肝炎肝硬化病史20余年，查体：轻度脱水，上腹部膨隆，有移动性浊音。该症状的发生与下列哪项无关","o":["门脉高压","血浆胶体渗透压下降","醛固酮增多","ADH增多","肾小球滤过率增加"],"a":4,"e":"腹水形成与门静脉高压致毛细血管静水压升高、白蛋白降低致胶体渗透压下降、醛固酮和ADH增多致水钠潴留有关；有效循环血量减少使肾血流量下降，肾小球滤过率降低而非增加，故该项与腹水发生无关"},{"q":"自由基中能使染色体发生畸变主要是","o":["O2-","1O2","OH•","LO•","LOO•"],"a":2,"e":"羟自由基反应性最强，可直接攻击DNA的脱氧核糖和碱基，引起链断裂、碱基修饰和染色体畸变。超氧阴离子经SOD转化为H2O2，损伤作用较弱；脂质自由基和脂过氧自由基主要引发脂质过氧化链式反应，破坏生物膜"},{"q":"一患者发生呼吸困难，检测肺泡通气血流比例大于0.8，提示患者可能出现","o":["肺不张","肺动脉栓塞","肺水肿","支气管肺炎","慢性阻塞性肺疾病"],"a":1,"e":"肺动脉栓塞使部分肺血流中断而肺泡通气仍存，形成死腔样通气，通气血流比例升高。肺不张、肺水肿和支气管肺炎均使肺泡通气减少而血流不减，比值降低，形成功能性分流；慢性阻塞性肺疾病以通气不足为主"},{"q":"一患者因慢性心瓣膜病而入院，如其血气分析结果为PaCO2 升高，同时HCO3－降低，最可能的诊断是","o":["呼吸性酸中毒","代谢性酸中毒","呼吸性碱中毒","代谢性碱中毒","混合型酸碱平衡紊乱"],"a":4,"e":"PaCO2升高提示CO2潴留即呼吸性酸中毒，HCO3降低提示代谢性酸中毒，二者并存为混合型酸碱平衡紊乱。单纯呼吸性酸中毒时HCO3应代偿性升高或正常；单纯代谢性酸中毒时PaCO2应代偿性下降"},{"q":"患者，男，60岁。严重水肿、大量蛋白尿、低蛋白血症、高脂血症，其最可能患有的原发性肾小球肾炎类型是","o":["急性弥漫性增生性肾小球肾炎","新月体性肾小球肾炎","IgA肾病","微小病变性肾小球病","膜性肾小球病"],"a":4,"e":"大量蛋白尿、严重水肿、低蛋白血症和高脂血症构成肾病综合征，60岁成人以膜性肾小球病最常见，上皮下免疫复合物沉积致基底膜弥漫增厚。微小病变性肾小球病多见于儿童；急性弥漫性增生性肾炎以血尿、高血压为主"},{"q":"患者，男，38岁。因发热2个月而入院。该患者2个月来不规则发热，伴体重减轻，右上腹部疼痛，呼吸时加重，有时伴咳嗽、胸痛，体检时肝区有明显压痛和叩击痛。X线检查：右侧膈肌抬高，活动受限，伴有少量胸腔积液。肝穿刺获得典型的黄色脓液。既往有慢性腹泻病史。该患者应首先考虑","o":["阿米巴肝脓肿","肠阿米巴穿孔","阿米巴肺脓肿","阿米巴肾脓肿","结核性胸膜炎"],"a":0,"e":"长期不规则发热、右上腹痛、肝大压痛，右膈抬高伴少量胸腔积液，有慢性腹泻史，肝穿刺得脓液，符合阿米巴肝脓肿，多位于右叶，由肠阿米巴滋养体经门静脉入肝。细菌性肝脓肿起病急、寒战高热且常多发；阿米巴肺脓肿由肝脓肿穿膈而来"},{"q":"患者，男，64岁。患高血压病10年。近日有夜间憋醒、气促伴咳嗽、气喘，在考虑心源性哮喘与支气管哮喘的鉴别时，下列哪项有助于心源性哮喘的诊断","o":["肝肿大伴下肢水肿","心率超过120次/分","双肺底湿啰音","心脏向左扩大","咳嗽咳痰"],"a":3,"e":"心源性哮喘有器质性心脏病基础，心脏向左扩大提示左心室扩大，是鉴别的重要依据。双肺底湿啰音也可见于肺部感染；心率增快和咳嗽咳痰在支气管哮喘同样存在；肝大伴下肢水肿提示已合并右心衰竭，属晚期表现"},{"q":"患者，男性，60岁，急性心力衰竭并发支气管肺炎入院，血气测定结果如下：pH：7.17，PaCO2：48mmHg，HCO3ˉ：17mmol/L，Na+：140mmol/L，Cl－：104mmol/L，K+：4.5mmol/L，最可能的酸碱平衡紊乱类型是","o":["AG正常型代谢性酸中毒","AG增高型代谢性酸中毒","代谢性酸中毒合并代谢性碱中毒","AG增高型代谢性酸中毒合并呼吸性酸中毒","呼吸性酸中毒合并呼吸性碱中毒"],"a":3,"e":"PaCO2为48mmHg提示CO2潴留，AG等于140减104减17即19mmol/L，增高提示代谢性酸中毒，两者并存。AG正常型代谢性酸中毒血氯升高、AG正常；代谢性酸中毒合并代谢性碱中毒时PaCO2不应升高；呼吸性酸中毒合并呼吸性碱中毒无AG增高"},{"q":"患者，女，43岁。诊断为二尖瓣狭窄，患者可能出现的临床表现中不包括","o":["呼吸困难","咳粉红色泡沫状痰","颈静脉怒张","水冲脉","心尖区舒张期隆隆样杂音"],"a":3,"e":"水冲脉由收缩压升高、舒张压降低所致，见于主动脉瓣关闭不全和动脉导管未闭。二尖瓣狭窄使左心房压升高、肺淤血，出现呼吸困难和粉红色泡沫痰；肺动脉高压及右心衰竭时出现颈静脉怒张；心尖区舒张期隆隆样杂音为其特征性体征"},{"q":"患儿，女，足月顺产，牛奶喂养。13天后出现烦躁不安，易激怒，四肢肌张力增高，腱反射增强，血钙1、6mmol/L，血糖5、8mmol/L，最有可能的诊断是","o":["新生儿低血糖","新生儿低血钙","新生儿缺氧缺血性脑病","新生儿颅内出血","新生儿破伤风"],"a":1,"e":"牛奶含磷高、钙磷比例不当，致血钙降低，出现烦躁、肌张力增高、腱反射增强及抽搐，血糖正常可排除低血糖。新生儿低血糖表现为反应差、震颤、呼吸暂停；缺氧缺血性脑病有围生期窒息史；破伤风有牙关紧闭和苦笑面容"},{"q":"男性，35岁。右下腹痛、腹泻5天伴低热。大便呈酱色、腥臭。粪便检查：红细胞（++），白细胞（+），查见阿米巴滋养体及包囊。请问该患者何种疾病","o":["阿米巴痢疾","细菌性痢疾","血吸虫病","阿米巴肿","阿米巴肝脓肿"],"a":0,"e":"大便呈酱色、腥臭，镜检见阿米巴滋养体及包囊，为溶组织内阿米巴侵袭结肠形成烧瓶状溃疡所致，即阿米巴痢疾。细菌性痢疾为脓血便伴里急后重、白细胞升高；阿米巴肿为肉芽组织增生形成的包块，无腹泻及病原体"},{"q":"患儿，男，7岁。因发热、头痛，呕吐呈喷射状1天入院。T：39.5℃，P：155次/分，R：30/分，BP：90/50mmHg，烦躁不安，意识朦胧，呼吸困难，肝肋下7cm，手臂、胸、腹及下肢等处出现红色、紫红色瘀点和瘀斑。白细胞总数15、0×109/L ，中性粒细胞0.78；红细胞3.59×1012/L，血红蛋白85g/L。凝血酶原时间18秒 (正常11～14秒) 。积极抢救无效死亡。入院时该患儿最可能的诊断是：","o":["暴发性脑脊髓膜炎并发沃-弗综合征","过敏性紫癜","流行性乙型脑炎","病毒性肝炎","心力衰竭"],"a":0,"e":"高热、意识障碍、皮肤瘀点瘀斑及休克，提示脑膜炎双球菌败血症，内毒素致微循环障碍和肾上腺出血，即沃-弗综合征。过敏性紫癜血小板正常、无高热和休克；流行性乙型脑炎以高热惊厥为主，无瘀斑；病毒性肝炎无此暴发过程"},{"q":"患者，女，27岁。阑尾炎手术后、刀口对合严密整齐、无感染，一般术后多久拆线","o":["术后3天","术后1周","术后2周","术后3周","术后4周"],"a":1,"e":"切口对合严密、无感染的清洁伤口属一期愈合，术后约1周即可拆线，此时胶原已连接创缘、抗张力强度足够。头面部血供丰富可4至5天拆线，四肢及关节处需10至12天；延迟至2周以上易致缝线窦道和瘢痕增生"},{"q":"患者，男，50岁。因肾结石、尿路阻塞就诊。超声检查发现肾体积增大，肾实质变薄。这种病理改变称为","o":["肥大","变性","萎缩","发育不良","化生"],"a":2,"e":"尿路梗阻致肾盂积水，积液压迫肾实质使其变薄、肾体积增大，属压迫性萎缩。肥大是细胞体积增大伴实质增厚，见于代偿性增生；变性为细胞内物质蓄积，器官体积多增大而实质不减薄；化生是组织转化为另一类型组织"},{"q":"患者，男，68岁。反复咳嗽、咳痰10余年，近两年来咳嗽、咳痰加重，并出现呼吸气促，呈渐进加重。査体：桶状胸，语颤减弱，叩诊呈过清音，心浊音界缩小，肺下界下移，两肺呼吸音减弱，本病例最可能的诊断是","o":["慢性支气管炎急性发作","慢性阻塞性肺气肿","慢性支气管炎并发阻塞性肺气肿","慢性支气管哮喘","自发性气胸"],"a":2,"e":"咳嗽咳痰每年持续3个月以上、连续2年，加之桶状胸、过清音、语颤减弱和肺下界下移，符合慢性支气管炎并发阻塞性肺气肿。单称慢性阻塞性肺气肿未反映原发病；支气管哮喘以发作性喘息为特征；气胸起病突然、患侧呼吸音消失"},{"q":"一女性患者，甲状腺肿大前来就医。手术切除标本镜下检查，见甲状腺滤泡灶性坏死、坏死滤泡的胶质外溢，较多异物巨细胞增生形成肉芽肿。自述曾有病毒感染史。该患者可能患有","o":["亚急性甲状腺炎","慢性淋巴细胞性甲状腺炎","桥本甲状腺炎","结节性甲状腺炎","甲状腺腺瘤"],"a":0,"e":"甲状腺滤泡灶性坏死、胶质外溢并见异物巨细胞肉芽肿，伴病毒感染史，为亚急性甲状腺炎，又称肉芽肿性甲状腺炎。桥本甲状腺炎以淋巴滤泡形成和生发中心、Hürthle细胞为特点；结节性甲状腺炎为结节性增生；腺瘤有完整包膜"},{"q":"某患者有畏寒、发热、腹痛、腹泻、脓血便和里急后重，应考虑为","o":["细菌性痢疾","肠阿米巴病","食物中毒","肠伤寒","急性肠炎"],"a":0,"e":"畏寒发热、腹痛腹泻、脓血便伴里急后重，为细菌性痢疾的典型表现，病变位于乙状结肠和直肠，初为卡他性炎继而形成假膜和浅溃疡。肠阿米巴病大便呈果酱样、里急后重轻；肠伤寒以便秘或腹泻、玫瑰疹、白细胞减少为特点"},{"q":"某38岁男性游客到玉龙雪山旅游，登山至海拔4000米左右时，呼吸困难加重，咳粉红色泡沫痰，皮肤发绀，该游客可能出现的病理变化是","o":["高原性肺水肿","急性心力衰竭","过敏性休克","下肢深静脉血栓","高原性代偿反应"],"a":0,"e":"快速登高至4000米，缺氧性肺血管收缩不均使毛细血管压升高、通透性增加，血浆渗入肺泡，出现呼吸困难、粉红色泡沫痰和发绀，为高原性肺水肿。急性心力衰竭多有心脏病史；过敏性休克有过敏原接触及皮疹；代偿反应不出现泡沫痰"},{"q":"患者，男，48岁。肝硬化腹水严重入院治疗，由于短时间内抽取腹水过多，患者突发晕厥。其晕厥的原因是","o":["腹腔内动脉炎症性充血","腹腔内静脉炎症性充血","腹腔内动脉减压后充血","脑动脉减压后充血","脑动脉炎症性充血"],"a":2,"e":"大量抽放腹水使腹腔内压骤降，长期受压的内脏细动脉失去外力支撑而反射性扩张，血液淤积于腹腔，回心血量和血压骤降致晕厥，称减压后充血。炎症性充血伴红热痛；脑动脉充血不引起全身血压下降"},{"q":"患者，女，31岁，孕40周。分娩时出现寒战及呼吸困难，阴道大量流血，注射催产素后仍流血不止。测血压60/40mmHg，血红蛋白70g/L，血小板计数90×109/L，凝血酶原时间22秒（正常11～14秒），3P试验阳性，D-二聚体阳性。此时该患者处于DIC哪一期","o":["高凝期","低凝期","消耗性低凝期","原发性纤溶亢进期","继发性纤溶亢进期"],"a":4,"e":"DIC进入继发性纤溶亢进期时，纤维蛋白降解产物大量生成，3P试验和D-二聚体阳性，同时血小板减少、凝血酶原时间延长并有出血不止。高凝期以血栓形成为主、出血不明显；消耗性低凝期纤溶指标升高不如本期显著"},{"q":"患者，男68岁，20年前被诊断为慢性支气管炎，未系统治疗。今冬12月，咳、痰、喘加重，门诊以“肺气肿”收住入院。患者用力呼气时，呼吸困难明显加重。肺功能检查发现呼气时出现小气道闭合，其发生机制主要是","o":["小气道管壁增厚","小气道阻塞","小气道痉挛","气道等压点移至膜性气道","小气道顺应性降低"],"a":3,"e":"肺气肿使肺泡弹性回缩力下降，呼气时气道内压迅速降至胸内压以下，等压点向周围移至无软骨支撑的膜性气道，管腔受压闭合、气体陷闭。小气道管壁增厚和痉挛见于慢性支气管炎和哮喘，是气道阻力增加的原因而非闭合机制"},{"q":"患者，男，60岁。身体消瘦。最近感觉腹部胀满，食欲不振就诊。平时平均每天抽一包烟。胃镜检查显示：胃窦部位黏膜变薄，颜色灰暗。病理检查发现肠上皮化生。诊断为","o":["早期胃癌","胃溃疡","慢性浅表性胃炎","慢性萎缩性胃炎","神经官能症"],"a":3,"e":"胃窦黏膜变薄、色泽灰暗并见肠上皮化生，为慢性萎缩性胃炎，腺体减少、固有层淋巴细胞和浆细胞浸润。慢性浅表性胃炎腺体完整、无化生；胃溃疡有黏膜缺损；早期胃癌为局灶性癌灶；神经官能症无胃黏膜器质性改变"},{"q":"患者，女，45岁。急腹症入院。B超示腹部有一个5cm×7cm×8cm的肿物。术后病理检查发现：送检组织为卵巢肿物，切开内有大量浆液流出，囊壁上有一乳头状肿物向腔内生长，镜下未见异型性明显的细胞。该患者的病理诊断是","o":["脂肪瘤","平滑肌瘤","淋巴管瘤","囊腺瘤","管状腺瘤"],"a":3,"e":"卵巢囊性肿物，囊内清亮浆液，囊壁乳头向腔内生长而细胞无明显异型，符合浆液性乳头状囊腺瘤。交界性肿瘤乳头密集、上皮复层并有轻度异型；囊腺癌异型明显、伴间质浸润和坏死；脂肪瘤由成熟脂肪组织构成"},{"q":"患者，女，26岁。因急腹症致感染性休克入院。现患者情况进一步恶化，血压进行性下降，神志淡漠，少尿，皮肤发绀。此时患者可能处于","o":["休克难治期","休克早期","休克期","代偿期","临终期"],"a":2,"e":"感染性休克进展至休克期，微循环淤血、回心血量减少，血压进行性下降，出现神志淡漠、少尿和皮肤发绀。休克早期（代偿期）血压尚正常、皮肤苍白湿冷；休克难治期出现DIC、无尿及多器官功能衰竭，皮肤瘀斑明显"},{"q":"患者，男，55岁。高血压病史已20余年。手术切除脾脏，切片可见脾小体中央动脉管壁增厚，管腔狭窄，管壁内可见均匀红染、半透明物质。这些半透明物质为","o":["淀粉样物质","血浆蛋白和基膜样物质","胶原纤维","免疫球蛋白","脂蛋白"],"a":1,"e":"高血压时脾中央动脉管壁因血浆蛋白渗入和基底膜样物质沉积而增厚、管腔狭窄，形成红染均质的玻璃样变。淀粉样物质需刚果红染色阳性并呈苹果绿双折光；胶原纤维为瘢痕成分；免疫球蛋白沉积见于多发性骨髓瘤的淀粉样变"},{"q":"一严重肝病患者出现精神错乱，意识不清、睡眠障碍等症状，查血见血氨水平明显升高。下列可用于降低血氨的治疗方式是","o":["吸氧","镇静类药物","口服左旋多巴","静脉输支链氨基酸溶液","口服乳果糖"],"a":4,"e":"乳果糖在结肠被细菌分解为乳酸和醋酸，酸化肠腔、减少氨的吸收并促进氨排出，是降低血氨的常用措施。左旋多巴针对假性神经递质；静脉输支链氨基酸纠正氨基酸失衡；镇静药抑制中枢，吸氧不能降低血氨"},{"q":"一休克患者，已出现血压进行性下降，皮肤出现花斑，伴有少尿、无尿。此时病人的肾障碍属于","o":["肾前性、功能性","肾性、功能性","肾后性、功能性","肾性、器质性","肾后性、器质性"],"a":3,"e":"休克持续发展致肾血流锐减、肾小管缺血性坏死，出现少尿无尿和氮质血症，属肾性、器质性肾功能障碍，滤过率显著下降。肾前性、功能性障碍见于休克早期，补液后尿量即恢复；肾后性、器质性由尿路梗阻引起，与休克无关"},{"q":"盛暑行军时大量饮纯净水可能会发生","o":["水中毒","等渗性脱水","低渗性脱水","高渗性脱水","水肿"],"a":2,"e":"盛暑行军大量出汗丢失水和钠，仅饮纯净水而不补盐，细胞外液渗透压降低，水向细胞内转移，形成低渗性脱水。水中毒多因ADH分泌过多或输入大量低渗液致细胞内水肿、血钠明显降低；高渗性脱水以失水多于失钠、口渴明显为特点"},{"q":"患者，女，55岁，绝经后阴道流血1月余。妇科检查：宫颈光滑，宫体正常大，附件(-)，宫颈细胞学检查未见异常。首先应怀疑的疾病是","o":["子宫肌瘤","子宫腺肌病","子宫颈炎","子宫内膜异位症","子宫内膜癌"],"a":4,"e":"绝经后阴道流血而宫颈光滑、宫颈细胞学正常、子宫正常大小，病变位于子宫内膜，应首先考虑子宫内膜癌，多见于55至65岁。子宫肌瘤表现为经量增多和子宫增大；子宫腺肌病有进行性痛经；子宫内膜异位症以痛经和盆腔结节为主"},{"q":"患者，男，20岁，高热4天，咳铁锈色痰，查体左肺上部叩诊实变，临床诊断为大叶性肺炎，该病变性质为","o":["浆液性炎","增生性炎","变质性炎","假膜性炎","纤维素性炎"],"a":4,"e":"大叶性肺炎的本质是肺泡腔内纤维蛋白原渗出并形成纤维蛋白网，属纤维蛋白性炎，故有实变体征和铁锈色痰。浆液性炎渗出以浆液为主；变质性炎以细胞变性坏死为主，见于病毒性肝炎；假膜性炎发生于黏膜，如菌痢"},{"q":"患者，女性，20岁，阑尾切除术后，残留在体内的缝线周围可能出现的病理改变是","o":["化脓性炎","肉芽肿性炎","炎性假瘤","机化","蜂窝织炎"],"a":1,"e":"缝线属不可吸收异物，长期存留刺激巨噬细胞转化为上皮样细胞并融合成异物巨细胞，周围纤维组织包绕，形成异物性肉芽肿。化脓性炎需细菌感染并形成脓液；蜂窝织炎为疏松结缔组织的弥漫性化脓炎；机化是坏死物被肉芽组织取代的结局"},{"q":"患者，女，18岁。分别在肛周3点、5点、8点和11点处有4个黄豆至红枣大小不等的增生物，色淡红，质软，呈菜花状、乳头状，表面凸凹不平，表面有溃破，覆有脓性分泌物。镜检可见表皮浅层有凹空细胞。考虑诊断为","o":["淋病","梅毒","湿疹","尖锐湿疣","扁平湿疣"],"a":3,"e":"肛周菜花状、乳头状增生物，镜下见表皮浅层凹空细胞，为HPV-6、11型感染所致的尖锐湿疣。扁平湿疣属二期梅毒，暗视野可见螺旋体，无凹空细胞；淋病由淋球菌引起，表现为尿道口脓性分泌物；湿疹无上皮增生和挖空细胞"},{"q":"患者，女，25岁。反复出现皮肤、肾、关节、心、浆膜等组织损害，血清检测抗DNA抗体阳性，临床诊断为系统性红斑狼疮。该病最具病理诊断价值的是","o":["面部蝶形红斑","肾损害","非细菌性疣赘性心内膜炎","关节受累","狼疮小体"],"a":4,"e":"狼疮小体又称苏木素小体，是抗核抗体作用于受损细胞核后形成的均质团块，为SLE的特征性病理改变，具有明确诊断意义。面部蝶形红斑和关节受累缺乏特异性；非细菌性疣赘性心内膜炎虽典型但检出率低，诊断价值不及狼疮小体"},{"q":"一患者氧动脉血氧分压为50mmHg，动脉二氧化碳分压为70mmHg，导致此现象发生的最可能是","o":["呼吸膜厚度增加","肺泡通气血流比例失调","肺泡膜面积减少","肺循环动静脉短路增加","肺泡扩张的弹性阻力增加"],"a":4,"e":"PaO2降低伴PaCO2升高提示肺泡通气不足，肺组织弹性阻力增加使肺扩张受限，形成限制性通气障碍，肺泡通气量下降致二者同时异常。呼吸膜增厚、弥散面积减少和通气血流比例失调主要引起PaO2下降，PaCO2多正常或降低"},{"q":"一患者因急性肾衰竭入院，查尿量为250ml/24h。该患者此时可能出现的最严重并发症是","o":["水中毒","高钾血症","代谢性酸中毒","氮质血症","肾性高血压"],"a":1,"e":"尿量250ml/24h属少尿，钾排出减少、组织分解代谢增强及酸中毒使钾外移，血钾迅速升高，可诱发严重心律失常甚至心搏骤停，是最危险的并发症。水中毒和氮质血症进展较慢；代谢性酸中毒和肾性高血压一般不立即致命"},{"q":"患者，男，15岁。近1年来经常出现鼻塞。检查发现右鼻道内有一赘生物，遂行赘生物切除术。病理检查结果显示：鼻黏膜上皮增生，皮下结缔组织高度水肿，较多淋巴细胞和浆细胞浸润。该赘生物可诊断为","o":["鼻炎性息肉","鼻炎性假瘤","鼻良性肿瘤","鼻恶性肿瘤","鼻肉芽肿性炎症"],"a":0,"e":"鼻黏膜上皮增生伴间质高度水肿、大量淋巴细胞和浆细胞浸润，为慢性炎症形成的炎性息肉。炎性假瘤以成纤维细胞增生和炎细胞混杂为特点，可见核分裂；鼻良性肿瘤有明确的肿瘤性增生；肉芽肿性炎以巨噬细胞结节为特征"},{"q":"男性，60岁，最初有皮肤病损，皮肤组织活检见Pautrier微脓肿 ，肿瘤细胞体积较大，核扭曲，该患者可能患有","o":["滤泡性淋巴瘤","弥漫性大B细胞性淋巴瘤","淋巴母细胞性淋巴瘤","Burkitt淋巴瘤","蕈样肉芽肿"],"a":4,"e":"瘤细胞核高度扭曲、侵入表皮聚集成Pautrier微脓肿，是原发于皮肤的成熟T细胞淋巴瘤，即蕈样肉芽肿。滤泡性淋巴瘤由中心细胞和中心母细胞构成滤泡；弥漫性大B细胞淋巴瘤为大细胞弥漫成片；Burkitt淋巴瘤呈星空样图像"},{"q":"患者，女，30岁。腰椎结核并在背部形成冷脓肿，冷脓肿向表皮溃破。破溃处流脓不断。此现象称为","o":["坏死组织溶解吸收","坏死组织机化","坏死组织包裹钙化","坏死组织分离排出","坏死组织恶变"],"a":3,"e":"结核性冷脓肿向体表溃破，坏死物液化后经破口持续排出，属坏死组织的分离排出，遗留窦道。机化是肉芽组织长入并取代坏死物；包裹是纤维组织将坏死灶包绕；钙化是钙盐沉积，多发生于干酪样坏死灶长期存在时"},{"q":"女性，45岁，高血压病史15年，并有高血压家族史。近半年来经常出现气喘、心悸，劳动后加重。查体：肥胖体型，血压170/100mmHg，X线检查，心脏增大。患者心脏可能出现的病变是","o":["左心室肥大","心肌萎缩","心肌纤维化","心肌梗死","心肌炎"],"a":0,"e":"长期高血压使左心室压力负荷增加，心肌细胞代偿性肥大、室壁增厚，形成向心性肥大，X线示心脏增大。心肌萎缩见于慢性消耗和老年；心肌纤维化是晚期失代偿表现；心肌梗死需有冠状动脉闭塞的急性事件"},{"q":"患者，男，70岁。咳嗽，痰中带血半年来院检查。既往体健，吸烟45年。X线示右肺门处见一个7cm×6cm巨大不规则阴影，边界不清，其最可能诊断是","o":["肺鳞癌","肺脓肿","肺炎性假瘤","肺结核","肺内转移癌"],"a":0,"e":"老年重度吸烟者出现痰中带血，肺门区巨大不规则肿块，符合中央型肺鳞状细胞癌，癌组织起源于主支气管黏膜上皮。肺脓肿有高热、咳大量脓臭痰及液平；炎性假瘤边界清楚；肺内转移癌多为多发周边结节"},{"q":"患者，男，53岁。反复腹泻、便秘交替出现9年，加重伴腹胀3个月。既往史，每周饮白酒50～100ml(1～2两)15年，务农。查体：消瘦，皮肤巩膜无黄染，腹隆，肝在剑突下4cm，脾下缘平脐，移动性浊音（+）。结肠镜检查病变黏膜苍白、萎缩，有许多呈密集分布、数毫米大小、平坦或稍隆起的黄色结节及虫卵性息肉。B超提示肝硬化。该患者考虑诊断为","o":["门脉性肝硬化","胆汁性肝硬化","酒精性肝硬化","血吸虫性肝硬化","心源性肝硬化"],"a":3,"e":"有疫水接触和慢性腹泻史，结肠黏膜见虫卵性息肉，肝脾大伴腹水，符合血吸虫性肝硬化，虫卵在门管区沉积引起纤维化。门脉性肝硬化由肝炎或酒精引起，无虫卵；酒精性肝硬化需长期大量饮酒；胆汁性肝硬化伴黄疸和皮肤瘙痒"},{"q":"一男性患者，有多年慢性肝病史，体检时发现四肢和躯干多处蜘蛛痣，手掌发红，出现上述表现的主要原因是","o":["胰高血糖素灭活减少","醛固酮灭活减少","ADH灭活减少","胰岛素灭活减少","雌激素灭活减少"],"a":4,"e":"肝细胞对雌激素的灭活能力下降，血中雌激素水平升高，使皮肤小动脉末端分支扩张，形成蜘蛛痣和肝掌。醛固酮灭活减少引起水钠潴留和腹水；ADH灭活减少加重低钠血症；胰岛素灭活减少致低血糖，均不出现血管扩张表现"},{"q":"某患者消化道手术后禁食3天，仅静脉输入大量5%葡萄糖液，此患者最容易发生的电解质紊乱是","o":["低钠血症","低钙血症","低镁血症","低磷血症","低钾血症"],"a":4,"e":"禁食期间无钾摄入，输入大量葡萄糖刺激胰岛素分泌，促使钾随糖原合成进入细胞内，加之应激使醛固酮分泌增多、尿钾排出不减，易致低钾血症。5%葡萄糖不含钠、钙、镁、磷，但低钠和低镁需较长时间才显现"},{"q":"患者，男，56岁。患高血压病13年，其血管壁玻璃样变多见于","o":["大动脉","中型动脉","细动脉","大静脉","小静脉"],"a":2,"e":"高血压时细动脉长期痉挛、内皮受损，血浆蛋白渗入管壁并伴基底膜样物质沉积，形成玻璃样变，最常累及肾入球动脉、视网膜动脉和脾中央动脉。大动脉以粥样斑块为特征；中型动脉表现为纤维肌性内膜增生；静脉不发生此种改变"},{"q":"患儿，女，8岁。因呕吐、腹泻1天到当地医院就诊，给予静脉点滴葡萄糖500ml，回家后病情无好转，出现发热、烦躁、少尿，来我院就诊，查血清钠155mmol/L，该患者出现的水、钠代谢紊乱是","o":["高渗性脱水","等渗性脱水","低渗性脱水","水中毒","水肿"],"a":0,"e":"腹泻丢失水多于钠，补液以葡萄糖为主而未补足水分和电解质，血钠升至155mmol/L，血浆渗透压升高，为高渗性脱水。等渗性脱水血钠正常；低渗性脱水血钠低于135mmol/L；水中毒血钠降低并伴细胞内水肿"},{"q":"患者，男，65岁。患慢性阻塞性肺气肿8年。近日因受凉感冒后出现活动时心悸、气短，下肢水肿，腹胀。查体：肝颈静脉反流征阳性，肝肋缘下3cm，双下肢凹陷性水肿。临床诊断：慢性肺源性心脏病。缓解该患者肺心病症状最有效的办法是","o":["降低右心前负荷","降低右心后负荷","降低左心前负荷","降低左心后负荷","增强心肌收缩力"],"a":1,"e":"肺心病的根本环节是缺氧性肺血管收缩和肺血管构型改建使肺动脉压升高，右心室后负荷加重，故降低右心后负荷最为有效，氧疗和改善通气可降低肺血管阻力。降低前负荷仅减轻淤血症状；增强心肌收缩力不能解除肺动脉高压"},{"q":"患儿，男，8岁。近1个月来出现显著的面部和下肢水肿，低蛋白血症，高脂血症，大量蛋白尿和脂尿，未发现血尿。此前没有其他病史。其最可能患有的原发性肾小球疾病是","o":["急性弥漫性增生性肾小球肾炎","新月体性肾小球肾炎","微小病变性肾病","IgA肾病","膜性肾小球病"],"a":2,"e":"儿童出现大量蛋白尿、低蛋白血症、明显水肿和高脂血症而无血尿、高血压，符合微小病变性肾病，光镜下肾小球基本正常，电镜见足细胞足突融合。膜性肾小球病多见于成人；急性弥漫性增生性肾炎有血尿和高血压；IgA肾病以发作性血尿为主"},{"q":"患者，男，45岁。鼻塞、涕中带血半年余，近1个月发现右侧胸锁乳突肌上段前缘出现无痛性肿块。应首先考虑下列哪种疾病","o":["淋巴瘤","淋巴结结核","鼻咽癌颈部淋巴结转移","淋巴结反应性增生","肺癌颈部淋巴结转移"],"a":2,"e":"鼻塞、涕中带血伴同侧胸锁乳突肌上段前缘无痛性肿块，为鼻咽癌颈淋巴结转移的典型表现，癌细胞经咽后淋巴结转移至颈上深淋巴结，常为首发症状。淋巴结结核有干酪样坏死和粘连；反应性增生淋巴结质软、有压痛；淋巴瘤无鼻部症状"},{"q":"患者，男，55岁。有长期酗酒史，每日饮白酒量超过100ml。最近B超显示，肝脏体积缩小，脾脏肿大。患者可能的诊断是","o":["门脉性肝硬化","坏死后肝硬化","血吸虫性肝硬化","淤血性肝硬化","胆汁性肝硬化"],"a":0,"e":"长期酗酒致酒精性肝炎、肝细胞脂肪变及坏死，进而纤维化形成小结节型肝硬化，即门脉性肝硬化，伴肝缩小和门脉高压性脾大。血吸虫性肝硬化有疫水接触和虫卵结节；胆汁性肝硬化伴黄疸、瘙痒；淤血性肝硬化见于慢性右心衰竭"},{"q":"一ARF患者，尿量为750ml/天，伴进行性氮质血症及代谢性酸中毒，无高钾血症。该患者此时可能处于的病程是","o":["少尿型ARF少尿期","少尿型ARF多尿期","少尿型ARF移行期","少尿型ARF恢复期","非少尿型ARF"],"a":4,"e":"24小时尿量750ml已超过少尿标准，但出现进行性氮质血症和代谢性酸中毒，符合非少尿型急性肾衰竭，肾小管浓缩功能受损而水排出尚可。少尿型少尿期尿量少于400ml；多尿期尿量逐日增多且氮质血症开始缓解"},{"q":"患者，男，35岁。住院手术后出现肝功能异常 。据调查，患者术中输血500ml。为明确诊断，患者需要首先做何检查","o":["病原血清学检查","病理活检","B超","CT","MRI"],"a":0,"e":"术中输血是乙型、丙型肝炎的重要传播途径，出现肝功能异常应先做肝炎病毒标志物检测以明确病原，再评估病毒复制水平。病理活检有创且非首选；B超、CT和MRI只能显示形态改变，不能确定病毒类型，故不作为首要检查"},{"q":"某患者临床检查结果：①淋巴细胞DNA琼脂糖凝胶电泳谱：梯状条带。②淋巴细胞电镜检查：细胞皱缩，胞膜及细胞器相对完整，核固缩。③淋巴细胞核酸内切酶活性测定：显著增强。 请问患者淋巴细胞发生什么病理改变","o":["淋巴细胞浸润","淋巴细胞坏死","淋巴细胞凋亡","淋巴细胞分裂","淋巴细胞恶性变"],"a":2,"e":"DNA降解为180至200bp片段、电泳呈梯状带，细胞皱缩、胞膜及细胞器完整、核固缩，核酸内切酶活性增强，均为凋亡的典型表现，属基因调控的程序性死亡。坏死时细胞肿胀、膜破裂、DNA降解无规律，电泳不呈梯状带"},{"q":"患者，男，36岁。四年前被诊断为梅毒，现皮肤、黏膜、骨、关节以及各内脏等多部位均受累及，并有特征性树胶样肿形成。有麻痹性痴呆表现。该患者的病程处于","o":["早期梅毒","后天性一期梅毒","后天性二期梅毒","后天性三期梅毒","先天性梅毒"],"a":3,"e":"感染后4至5年出现树胶样肿，累及皮肤、黏膜、骨、关节及内脏，并伴麻痹性痴呆，属后天性三期梅毒，传染性小但破坏性大。一期梅毒以硬性下疳为特征；二期梅毒表现为梅毒疹和扁平湿疣；先天性梅毒无下疳，有哈钦森三联征"},{"q":"患者，女，73岁。大便性状改变月余，大便潜血阳性。经肠镜检查发现一个0、5cm×1、0cm的息肉。病理报告显示:横结肠黏膜腺癌，淋巴管内见癌栓。本患者之恶性肿瘤与下列哪个抑癌基因密切相关","o":["APC","WT-1","P16","NF-1","BRCA-2"],"a":0,"e":"结直肠癌发生中APC基因突变起始动作用，该抑癌基因失活使WNT通路持续激活、β联蛋白积聚，细胞异常增殖。WT-1与肾母细胞瘤相关；P16与黑色素瘤和胰腺癌相关；BRCA-2与遗传性乳腺癌和卵巢癌相关"},{"q":"患者，女，20岁。右乳外上象限有一直径约2.5cm大小的圆形肿块，边界清楚，表面光滑，可移动，不痛。此肿块最可能的是","o":["乳腺癌","乳腺纤维腺瘤","乳腺增生症","炎性包块","乳腺脓肿"],"a":1,"e":"年轻女性乳腺圆形肿块、边界清楚、表面光滑、活动度好且无痛，符合乳腺纤维腺瘤，由增生的腺体和纤维间质构成。乳腺癌质硬、边界不清、活动差，可伴皮肤橘皮样改变；乳腺增生症为多发结节伴周期性胀痛；乳腺脓肿有红肿热痛"},{"q":"患者，男，48岁。鼻塞、头痛、耳鸣3月余，查体发现左侧颈部扪及无痛性包块，活检为淋巴结内转移性鳞状细胞癌，其原发癌最可能是","o":["肺鳞癌","食管鳞癌","鼻咽部鳞癌","喉鳞癌","口腔鳞癌"],"a":2,"e":"鼻塞、头痛、耳鸣伴同侧颈部淋巴结转移性鳞癌，原发灶最可能位于鼻咽部，鼻咽癌颈淋巴结转移率高且常为首发症状。喉癌以声嘶为主、转移较晚；肺鳞癌、食管鳞癌和口腔鳞癌的颈部转移多伴相应器官症状"},{"q":"某患者血气分析结果如下：pH：7.49，PaCO2：48mmHg，HCO3ˉ：36mmol/L，该酸碱平衡紊乱对机体的影响不包含","o":["心血管系统对儿茶酚胺反应性降低","烦躁不安","神经肌肉应激性增高","血红蛋白氧离曲线左移","低钾血症"],"a":0,"e":"pH升高、HCO3明显升高而PaCO2代偿性增高，为代谢性碱中毒。碱中毒使神经肌肉应激性增高，出现烦躁和手足搐搦，氧离曲线左移致组织缺氧，并引起低钾血症；心血管对儿茶酚胺反应性降低是酸中毒的表现"},{"q":"一男性患者出现发热，外周血白细胞增高，脑部CT和MRI均表现为囊壁光滑的环形强化占位灶，周围伴不同程度水肿。最可能的诊断是","o":["流行性脑脊髓膜炎","流行性乙型脑炎","急性支气管炎","小叶性肺炎","脑脓肿"],"a":4,"e":"发热、白细胞升高，CT和MRI示囊壁光滑的环形强化灶伴周围水肿，符合慢性脑脓肿，脓肿壁由炎性肉芽组织和纤维包膜构成。流行性脑脊髓膜炎为脑膜弥漫性强化；乙脑病变位于脑实质、无环形强化；支气管炎和小叶性肺炎无颅内病灶"},{"q":"患者，男，50岁。橡胶厂工人，无痛性血尿5月余。膀胱镜检查：膀胱三角区可见一乳头状肿物，宽基底无蒂，质地脆。病理活检诊断为浸润性尿路上皮癌。下列哪种物质与本患者所患肿瘤密切相关","o":["3，4-苯并芘","联苯胺","黄曲霉毒素","苯","多环芳烃"],"a":1,"e":"联苯胺、乙萘胺等芳香胺类经肝代谢后由尿排出，长期接触使膀胱黏膜受损，印染和橡胶工人膀胱癌高发。3,4-苯并芘和多环芳烃主要与肺癌相关；黄曲霉毒素B1与肝细胞癌相关；苯主要引起白血病和再生障碍性贫血"},{"q":"患者，男，35岁。突发少尿、血尿和咳血，肾功能检查发现肌酐和尿素氮水平显著升高，尿蛋白++++，血清学检查显示存在抗GBM抗体。经皮肾穿刺检查，其可能出现的肾小球病变是","o":["基底膜显著增厚","新月体形成","系膜增生","基底膜呈“双轨征”","内皮细胞增生"],"a":1,"e":"抗GBM抗体阳性伴肺出血和肾功能急剧恶化，为肺出血肾炎综合征，属Ⅰ型急进性肾小球肾炎，肾小球囊壁层上皮细胞增生形成新月体。基底膜增厚见于膜性肾病；双轨征见于膜增生性肾炎；内皮细胞增生见于急性弥漫性增生性肾炎"},{"q":"患者，女，46岁，颈部淋巴结肿大，手术切除。肿大的淋巴结内可见淡黄色、质软的干酪样坏死，镜下见病灶中心为干酪样坏死，周围为上皮样细胞、朗汉斯巨细胞，再向外为大量淋巴细胞浸润和少量反应性增生的成纤维细胞。该淋巴结的病变是","o":["化脓性炎","纤维素性炎","肉芽肿性炎","浆液性炎","出血性炎"],"a":2,"e":"中心为干酪样坏死，周围为放射状排列的上皮样细胞和朗汉斯巨细胞，外周淋巴细胞及成纤维细胞包绕，为典型结核结节，属感染性肉芽肿性炎。化脓性炎以中性粒细胞和脓液为特征；纤维素性炎见于大叶性肺炎；浆液性炎渗出以浆液为主"},{"q":"患儿，男，3岁。不小心右手被开水烫伤，皮肤上出现多个水疱，此水疱属于","o":["漏出液","纤维素渗出","浆液性渗出","脓性渗出","以上都有"],"a":2,"e":"Ⅱ度烫伤时表皮内积聚的液体为浆液性渗出物，含少量蛋白质和炎症细胞，形成水疱。漏出液由静脉压升高或胶体渗透压降低引起，蛋白含量低、非炎症性；纤维素渗出见于大叶性肺炎和假膜性炎；脓性渗出需大量中性粒细胞和化脓菌"},{"q":"患者静脉注射青霉素后，出现心悸，出汗，面色苍白，脉速而弱，其最有可能发生","o":["过敏性休克","失血性休克失代偿期","感染性休克","神经源性休克","心源性休克"],"a":0,"e":"注射青霉素后迅速出现心悸、出汗、面色苍白、脉速而弱，为IgE介导的Ⅰ型超敏反应所致过敏性休克，外周血管扩张和通透性增高使血压骤降。感染性休克有感染灶和发热；失血性休克有明确失血；神经源性休克多由脊髓损伤引起"},{"q":"患者，男，20岁。部队官兵，在一次抢险救灾中造成全身软组织多处挫伤，请问在他组织损伤修复过程开始于以下哪个阶段","o":["损伤早期","损伤晚期","炎症静止期","炎症活动期","炎症起始期"],"a":0,"e":"组织损伤后即刻出现出血和炎症反应，同时启动修复，成纤维细胞和内皮细胞在损伤早期即受生长因子刺激而增生，故修复始于损伤早期。炎症静止期和晚期以纤维化收缩为主；修复与炎症并存，并非待炎症消退后才开始"},{"q":"某患者，受凉后出现畏寒、“鸡皮疙瘩”，手脚冰冷，皮肤苍白，自测体温37.6℃。请问患者处于发热的哪个时相","o":["体温上升期","高温持续期","体温下降期","体温稳定期","体温变化期"],"a":0,"e":"畏寒、皮肤苍白、起鸡皮疙瘩及四肢冰冷，为皮肤血管收缩、竖毛肌收缩和寒战产热的表现，此时调定点上移而体温尚未升至新水平，属体温上升期。高温持续期皮肤血管扩张、面色潮红并出汗；体温下降期大量出汗、皮肤温暖"},{"q":"患者，女，40岁。10年前因乙型肝炎住市传染病医院。近2年来周身乏力，消瘦，常伴牙龈出血，月经量多。近10天腹胀加重，伴少尿。查体：面色黝暗无光泽，巩膜黄染，腹壁静脉曲张明显，移动性浊音阳性。上述症状不提示的临床诊断是","o":["乙型肝炎","门脉高压症","肝功能不全","肝性脑病","肝肾综合症"],"a":3,"e":"面色黝暗、黄疸、腹壁静脉曲张、脾大及移动性浊音提示肝硬化失代偿、门脉高压和肝功能不全，少尿提示肝肾综合征；全程无意识障碍、扑翼样震颤及血氨升高，故不提示肝性脑病，其余各项表现均已出现"},{"q":"患儿，1岁。因“脑膜炎”发热 3 天，出现哭闹、烦躁不安、肌肉抽搐等症状。请问这些症状出现的主要原因","o":["发热导致患儿丢失大量水分","患儿中枢神经系统感染","小儿神经系统未发育成熟易导致热惊厥","发热使患儿心率加快","患儿因发热出现不适"],"a":2,"e":"婴幼儿大脑皮质发育不成熟、神经髓鞘形成不全，兴奋易泛化，发热时易出现全身性抽搐，即热性惊厥。中枢神经系统感染虽可抽搐，但伴脑膜刺激征和脑脊液改变；单纯心率加快和失水不会引起肌肉抽搐"},{"q":"一患者的甲状腺手术切除标本送病理检查，显微镜下见肿瘤细胞多排列成复杂分支的乳头结构，乳头中心有纤维血管间质，间质内常见呈同心圆状的砂粒体，核染色质少，常呈透明或毛玻璃状，无核仁。该患者最有可能的诊断是","o":["滤泡癌","未分化癌","髓样癌","乳头状癌","甲状腺腺瘤"],"a":3,"e":"肿瘤呈复杂分支乳头，乳头中心有纤维血管间质，间质内见砂粒体，细胞核毛玻璃状、核沟明显，为甲状腺乳头状癌，预后较好但淋巴结转移早。滤泡癌以包膜和血管侵犯为诊断依据；髓样癌有淀粉样间质并分泌降钙素；未分化癌异型显著"},{"q":"患者，李某，女，30岁，患慢性肾小球肾炎8年。近年来尿量增多，夜间尤甚。本次因妊娠反应严重，呕吐频繁，进食困难而入院。该病人除可出现缺钾外，还可能出现下列哪项电解质紊乱","o":["低磷血症","高钙血症","高钠血症","高镁血症","低镁血症"],"a":4,"e":"频繁呕吐和进食困难使镁随消化液丢失并摄入不足，低钾常与低镁并存，故还易出现低镁血症。高镁血症见于肾功能衰竭少尿、镁排出受阻；低磷血症多见于再喂养综合征；高钙血症由甲状旁腺功能亢进或骨破坏引起"},{"q":"患者，男，28岁。腹痛、腹泻三天，每日排便十余次，初为黏液稀便，后转为黏液脓血便，该患者所患疾病可能为","o":["伤寒","大肠癌","阿米巴痢疾","急性细菌性痢疾","肠真菌病"],"a":3,"e":"起病急、每日排便十余次并由黏液稀便转为黏液脓血便，符合急性细菌性痢疾，病变为假膜性炎，累及乙状结肠和直肠。阿米巴痢疾大便呈暗红果酱样、里急后重轻；伤寒以便秘或腹泻、玫瑰疹为特点；大肠癌病程长，以排便习惯改变为主"},{"q":"患者，男，33岁。患肾结核致左肾功能丧失而切除。标本见肾实质切面有大小不等的虫蚀样缺损，该病理改变称为","o":["空洞","溃疡","窦道","瘘管","囊肿"],"a":0,"e":"肾干酪样坏死物液化后经输尿管排出，肾实质内遗留空腔，称空洞，见于肾结核。溃疡为皮肤黏膜表面的组织缺损；窦道为只开口于体表的盲管；瘘管连接两个器官或器官与体表；囊肿为内含液体的闭合腔隙，非坏死排出所致"},{"q":"患者，年轻女性，关节、皮肤、肾反复出现病变，肾活检系弥漫增生型改变，可见苏木素小体。该患者血清检测中具有特征性的阳性抗体是","o":["抗DNA拓扑异构酶-1抗体","抗着丝点抗体","抗双链DNA抗体","抗SS-A抗体","抗HLA抗体"],"a":2,"e":"苏木素小体为抗核抗体攻击受损细胞核后形成的均质团块，其对应的特征性抗体是抗双链DNA抗体，特异性高且与疾病活动度相关。抗SS-A抗体见于干燥综合征；抗着丝点抗体见于CREST综合征；抗DNA拓扑异构酶-1抗体见于系统性硬化症"},{"q":"患者，女，48岁。患风湿性心脏病二尖瓣狭窄6年。近一月来出现呼吸困难，咳嗽、气喘，不能平卧，间断自服平喘药氨茶碱，呼吸困难较前减轻，但出现颈静脉怒张，肝脏肿大，下肢水肿。该患者呼吸困难减轻的最主要原因是","o":["氨茶碱治疗有效","二尖瓣狭窄的程度减轻","在原有左心衰竭的基础上又发生了右心衰竭","合并了二尖瓣关闭不全","合并了主动脉病变"],"a":2,"e":"右心衰竭使右心室排血减少，肺循环血量下降、肺淤血减轻，故呼吸困难缓解，但同时出现体循环淤血，表现为颈静脉怒张、肝大和下肢水肿。氨茶碱仅短暂缓解支气管痉挛；二尖瓣狭窄程度不会自行减轻"},{"q":"患者因肺癌作肺叶切除手术，若切除3/5肺叶，可能会出现呼吸功能障碍，其机制是","o":["肺阻塞性通气功能障碍","肺限制性通气功能障碍","肺弥散功能障碍","残存的肺泡通气不足","残存的肺泡血流不足"],"a":2,"e":"肺叶切除后肺泡-毛细血管膜总面积减少，气体弥散面积不足，导致弥散功能障碍和低氧血症。限制性通气障碍指肺顺应性下降或胸廓活动受限，如肺纤维化和胸膜增厚；阻塞性通气障碍见于气道狭窄；通气血流比例失调需有血流或通气分布异常"},{"q":"患者，男，60岁。40年吸烟史。慢性咳嗽30年，近1月来痰中带血丝。X线检查，显示左肺门处不规则巨大阴影。支气管镜检查，左主支气管黏膜粗糙不平，管腔狭窄。活检病理诊断最可能是","o":["慢性支气管炎","大叶性肺炎","肺炎性假瘤","肺癌","肺结核"],"a":3,"e":"长期吸烟、痰中带血，肺门区不规则巨大阴影伴支气管黏膜粗糙、管腔狭窄，符合中央型肺癌，癌组织起源于主支气管。慢性支气管炎仅见纹理增粗；大叶性肺炎有急性感染表现且不形成肿块；肺炎性假瘤边界清楚；肺结核多位于上叶并见钙化"},{"q":"一位日本老年女性是1945年关岛原子弹爆炸后的幸存者，她可能发生","o":["精神病","神经病","多器官衰竭","应激性溃疡","创伤后应激综合征"],"a":4,"e":"核爆等重大灾难的幸存者可长期出现闪回、噩梦、警觉性增高和回避行为，符合创伤后应激综合征。急性放射病所致多器官衰竭发生在受照后数周内，而非数十年后；精神病和神经病不能概括灾难后的心理反应"},{"q":"患者，女，45岁。自觉平素体健，单位常规体检时发现肝功能轻度异常，B超显示肝内少量纤维组织增生。问诊了解到该患者从未注射过乙型肝炎免疫球蛋白，平时喜欢在饭店吃饭。病人最可能的诊断是","o":["脂肪肝","轻度慢性肝炎","中度慢性肝炎","肝硬化","肝癌"],"a":1,"e":"肝功能轻度异常、B超仅见少量纤维组织增生，无门脉高压表现，符合轻度慢性肝炎，炎症活动度和纤维化程度均较轻。中度慢性肝炎纤维间隔形成更明显；肝硬化有假小叶和门脉高压；脂肪肝B超呈明亮肝；肝癌有占位性病变"},{"q":"某女，6岁。身高150cm, 面部粗糙、手脚增厚增大, 生长较同龄儿童明显快。实验室检查发现GH水平总值较正常值高出10倍，临床诊断为巨人症。请分析GH主要通过下列哪个细胞信号转导途径发挥其生物学效应","o":["JAK-STAT信号转导途径","cAMP-PKA通路","IP3/DAG-PKA通路","受体酪氨酸蛋白激酶（RTK）介导的信号转导途径","NF-κB介导的信号转导途径"],"a":0,"e":"生长激素受体属细胞因子受体超家族，通过激活JAK2、使STAT5磷酸化后转位入核，调控基因转录，故GH经JAK-STAT途径发挥作用。胰岛素和表皮生长因子经受体酪氨酸蛋白激酶途径；cAMP-PKA和IP3/DAG-PKA为G蛋白耦联受体通路"},{"q":"患者，男，40岁。面部及下肢水肿2月余，尿液检查蛋白+++，尿肌酐、尿素氮正常。组织学见肾小球体积增大，肾小球基底膜呈弥漫性增厚，无炎症反应。电镜见基底膜增厚，上皮侧大量小丘状电子致密物沉积。此例肾炎可能是什么类型","o":["系膜增生性肾小球肾炎","膜性肾小球病","急性弥漫性增生性肾小球肾炎","新月体性肾小球肾炎","IgA肾病"],"a":1,"e":"基底膜弥漫增厚、上皮侧大量小丘状电子致密物沉积、无炎症细胞，为膜性肾小球病的特征，沉积物间基膜增生形成钉突。系膜增生性肾炎以系膜区沉积为主；急性弥漫性增生性肾炎有驼峰状沉积；新月体性肾炎以新月体形成为特点"},{"q":"患者，女，62岁。冠心病病史10年，近日上呼吸道感染在某诊所输液治疗过程中，因速度过快突然出现呼吸困难，咳嗽、咳粉红色泡沫痰。出现此现象最有可能的原因是","o":["上呼吸道感染加重，导致肺循环阻力增大","输液速度过快使血容量急剧增加","交感神经兴奋性增高，外周阻力增大","发生了酸中毒，导致心肌收缩性减弱","缺氧导致心肌供氧不足"],"a":1,"e":"输液速度过快使回心血量骤增，左心室前负荷超过其排血能力，肺静脉压急升致急性肺水肿，出现呼吸困难和粉红色泡沫痰。上呼吸道感染仅为基础诱因；交感兴奋使外周阻力升高主要加重后负荷；酸中毒和缺氧为继发改变"},{"q":"一女性患者，近期出现怕冷、嗜睡、月经周期紊乱、声音嘶哑、便秘，皮肤苍白、发凉、粗糙、非凹陷性水肿，有可能患有","o":["甲亢","甲状腺功能低下","甲状腺功能亢进","慢性淋巴细胞性甲状腺炎","慢性纤维性甲状腺炎"],"a":1,"e":"怕冷、嗜睡、动作思维减慢、便秘、声嘶及皮肤苍白发凉、非凹陷性水肿，为甲状腺激素不足致黏多糖在间质沉积的表现，即黏液水肿。甲亢表现为怕热多汗、消瘦、易激动；桥本甲状腺炎为病因，其功能状态需甲状腺功能检查确定"},{"q":"患者，女，53岁。体检发现左乳外上象限无痛性肿物，直径2cm左右，活动度差，同侧腋窝触及1枚肿大淋巴结。病理诊断为乳腺浸润性导管癌。本患者可能有下列哪项指标异常","o":["BHD基因突变","BRCA-1基因突变","KIT点突变","L-myc 基因扩增","hst-1过度表达"],"a":1,"e":"BRCA-1是遗传性乳腺癌的易感基因，其胚系突变使DNA双链修复障碍，乳腺癌及卵巢癌风险显著升高，约20%遗传性乳腺癌可查见该突变。KIT突变见于胃肠间质瘤；L-myc扩增见于小细胞肺癌；BHD基因突变与肾肿瘤相关"},{"q":"患者，女，60岁。高血压病史10年。近半月来，患者疲倦、下肢水肿明显，尿中出现大量泡沫并不易消退。医生建议患者进一步检查，你认为下列哪项检查是不必要的","o":["尿常规","眼底镜","心脏超声","脑CT","肺功能检查"],"a":4,"e":"患者有高血压史并出现蛋白尿、下肢水肿，需评估靶器官损害：尿常规判断肾受累，眼底镜观察视网膜动脉有无硬化，心脏超声了解左心室肥厚，脑CT排查脑血管病变；肺功能与高血压靶器官损害无关，属不必要检查"},{"q":"患者，女，56岁。慢性咳嗽、咳痰3年，每年冬季发作，多持续3～4个月。近一周再次出现咳嗽、咳白黏痰，无发热及呼吸困难。实验室检查：白细胞7.0×109/L，分叶68%，淋巴30%，嗜酸1%，单核1%，尿常规正常，胸片可见双肺纹理增多、紊乱。查肺功能：FEV1/FVC正常。最恰当的诊断是","o":["慢性阻塞性肺疾病","肺结核","支气管哮喘","慢性支气管炎","肺炎"],"a":3,"e":"咳嗽咳痰每年持续3个月、连续2年以上，胸片示纹理增多紊乱，而FEV1/FVC正常、无气流受限，符合慢性支气管炎。慢性阻塞性肺疾病须有FEV1/FVC小于70%的持续气流受限；支气管哮喘为发作性喘息、气流受限可逆；肺炎有实变影"},{"q":"患者，女性，38岁，因减肥连续服用泻药一周，现感虚弱乏力，偶有直立性眩晕而入院。患者皮肤弹性差，黏膜干燥，血Na+140mmol/L，血浆渗透压295mOsm/L。其发生的水、钠代谢紊乱类型是","o":["等渗性脱水","低渗性脱水","水中毒","水肿","高渗性脱水"],"a":0,"e":"连续服用泻药致消化液丢失，其渗透压与细胞外液相近，血钠140mmol/L、血浆渗透压295mOsm/L均在正常范围，属等渗性脱水，表现为皮肤弹性差、黏膜干燥和直立性低血压。低渗性脱水血钠低于135mmol/L；高渗性脱水血钠高于150mmol/L"},{"q":"患者，男，新生儿。出生后发现面部有一不规则形红斑，红斑突起于皮肤。本病例最可能的诊断是","o":["脂肪瘤","平滑肌瘤","淋巴管瘤","基底细胞癌","血管瘤"],"a":4,"e":"新生儿面部不规则形、突出于皮肤的红斑为先天性血管瘤，由血管内皮细胞增生形成，可随身体发育长大，成年后多停止发展或消退。淋巴管瘤呈囊性、内含淋巴液，多见于颈部；基底细胞癌见于老年人曝光部位；脂肪瘤质软、分叶状"},{"q":"死者，女，尸检发现两肾体积缩小，重量减轻，质地硬，皮质变薄，表面呈颗粒状，肾切片观察，均有细动脉玻璃样变性，肾小球纤维化等改变。此患者生前可能患有的疾病是","o":["肾盂肾炎","高血压病","肾小球肾炎","药物中毒","肾癌"],"a":1,"e":"双肾对称性缩小、质地变硬、表面细颗粒状，镜下细动脉玻璃样变、肾小球纤维化，为原发性颗粒性固缩肾，是高血压病的肾脏改变。慢性肾小球肾炎双肾缩小但以肾小球硬化、蛋白管型为特点；慢性肾盂肾炎瘢痕不对称、肾盂变形；肾癌为占位性肿块"},{"q":"患者，男，40岁。因交通意外致外伤出血。急诊接诊检查，神智清，面色苍白，四肢湿冷，心率88次/分，血压105/85mmHg。该患者腹腔内脏微循环变化的特点为","o":["少灌多流、灌多于流","多灌多流、灌少于流","少灌少流、灌少于流","多灌少流、灌多于流","少灌少流、灌多于流"],"a":2,"e":"外伤失血早期交感神经兴奋，微动脉和微静脉收缩、毛细血管前阻力升高，微循环呈少灌少流、灌少于流，血压尚可维持。休克期微循环淤血呈多灌少流、灌多于流；难治期出现DIC和微循环麻痹，血压显著下降"},{"q":"某肝性脑病患者血气测定结果为：pH 7.48，仅根据pH的变化，可作出酸碱平衡紊乱类型的诊断为","o":["代偿性碱中毒","代偿性酸中毒","失代偿性碱中毒","失代偿性酸中毒","失代偿性呼吸性碱中毒"],"a":2,"e":"pH为7.48，高于正常上限，提示碱中毒；仅凭pH不能判断是呼吸性还是代谢性，且机体未完全代偿，故称失代偿性碱中毒。失代偿性酸中毒pH低于7.35；代偿性碱中毒pH应在正常范围；判定呼吸性碱中毒还需PaCO2降低的依据"},{"q":"某肾衰竭患者放置导尿管2天后，出现发热、腰痛，尿中含有大量白细胞和细菌。血气检查结果为：pH：7.39，PaCO2：19mmHg，HCO3-：11mmol/L，可诊断为","o":["代谢性酸中毒","呼吸性碱中毒","代谢性酸中毒合并代谢性碱中毒","代谢性酸中毒合并呼吸性碱中毒","代谢性碱中毒合并呼吸性碱中毒"],"a":3,"e":"HCO3降至11mmol/L提示代谢性酸中毒，PaCO2 19mmHg明显低于预计代偿值（1.5乘11加8约24.5mmHg），提示同时存在呼吸性碱中毒，故为代谢性酸中毒合并呼吸性碱中毒。单纯代谢性酸中毒PaCO2不会降至此程度；代谢性碱中毒HCO3应升高"},{"q":"患者，女，60岁。心绞痛病史3年，1年前出现劳力性呼吸困难等症状。近来呼吸困难加重，夜间常不能平卧。查体：颈静脉怒张，心界向两侧扩大，双肺底可闻及湿性啰音，肝脏肿大，双下肢水肿。该患者最可能的诊断是","o":["左心衰竭","右心衰竭","全心衰竭","左房衰竭","右房衰竭"],"a":2,"e":"心绞痛病史、劳力性呼吸困难及夜间不能平卧提示左心衰竭，颈静脉怒张、肝大和双下肢水肿提示右心衰竭，心界向两侧扩大、双肺底湿啰音，符合全心衰竭。单纯左心衰竭无颈静脉怒张和下肢水肿；单纯右心衰竭无夜间阵发性呼吸困难"},{"q":"患者，男，16岁。左侧下肢内踝肿胀明显1周，约3cm×3cm×2cm范围，高出皮肤，色红、质软，皮温高、有波动感。实验室检查：白细胞计数14、8×109/L，其中中性粒细胞占85%，血培养1周后结果为金黄色葡萄球菌阳性。该病变应诊断为","o":["脓肿","蜂窝织炎","表面化脓","浆液性炎","肉芽肿性炎"],"a":0,"e":"局部红肿热痛、界限较清并有波动感，中性粒细胞占85%、血培养金黄色葡萄球菌阳性，为局限性化脓性炎即脓肿，金葡菌产生凝血酶使病变局限并液化坏死形成脓腔。蜂窝织炎呈弥漫性扩散、边界不清；表面化脓发生于黏膜表面；浆液性炎无脓液"},{"q":"患者，男，65岁。慢性肾小球肾炎10余年。因进展为CRF入院，其临床表现中最不可能出现的是","o":["尿量超过2000ml/24h","尿量少于400ml/24h","尿比重1.003~1.030","尿比重1.008~1.012","蛋白尿、血尿和管型尿"],"a":2,"e":"慢性肾衰竭时肾浓缩稀释功能丧失，尿比重固定在1.008~1.012，即等张尿；早期健存肾单位代偿可出现多尿超过2000ml/24h，晚期肾小球滤过率显著下降则少尿不足400ml/24h，尿蛋白、红细胞及颗粒管型均常见。1.003~1.030为正常随机尿比重范围，反映浓缩与稀释功能完好，与肾衰竭时的固定低比重尿不符"},{"q":"患者，男，60岁。近段时间出现乏力、厌食、肝区疼痛加重。肝活检显示，肝组织碎片状坏死，有炎症细胞浸润和毛玻璃样肝细胞，见纤维间隔增生，但肝小叶结构基本保存。患者10年前诊断为急性乙型肝炎。患者现在最可能被诊断为","o":["轻度慢性乙型肝炎","中度慢性乙型肝炎","重度慢性乙型肝炎","门脉性肝硬化","酒精性肝炎"],"a":1,"e":"碎片状坏死指肝小叶周边界板肝细胞灶性坏死崩解，是判断慢性肝炎活动度的关键指标；伴纤维间隔增生而小叶结构基本保存，符合中度慢性肝炎。轻度慢性肝炎仅有小叶内点状坏死与嗜酸小体，不出现明显碎片状坏死；重度者见桥接坏死及小叶结构紊乱；门脉性肝硬化为假小叶形成；酒精性肝炎以脂肪变和Mallory小体为特点"},{"q":"患儿，男，10岁。2周前患扁桃腺炎，经治疗好转。近2天来出现眼睑水肿，少尿、血尿，尿蛋白（+++），血压升高（150/90mmHg）。患者的临床表现符合","o":["急性肾炎综合征","肾病综合征","慢性肾炎综合征","快速进行性肾炎综合征","无症状性血尿或蛋白尿"],"a":0,"e":"链球菌感染后10天左右起病，出现血尿、蛋白尿、水肿与高血压，是急性弥漫性增生性肾小球肾炎的典型表现，属急性肾炎综合征。肾病综合征以大量蛋白尿、低蛋白血症、高度水肿和高脂血症为特征，不以血尿高血压为主；快速进行性肾炎综合征数周内即进入少尿无尿和肾衰竭；慢性肾炎综合征有长期病史及贫血、肾功能减退；无症状性血尿或蛋白尿无水肿和高血压"},{"q":"一尸检标本，见肝脏体积增大，颜色淡黄，光镜下见肝细胞胞浆中出现大小不等的空泡。其最有可能的病理变化是","o":["气球样变","脂肪变","细胞水肿","黏液样变","细胞坏死"],"a":1,"e":"肝细胞胞质内出现大小不等的球形空泡、肝脏增大色淡黄质软，是甘油三酯蓄积形成的脂滴，即脂肪变，大脂滴可将胞核挤向一侧。气球样变为细胞水肿的极期，胞质疏松淡染而未必有清晰空泡；细胞水肿表现为胞质水分增多呈颗粒状；黏液样变为间质黏多糖积聚；细胞坏死以核固缩、核碎裂、核溶解为标志"},{"q":"患者，男，70岁。反复咳嗽、咳痰3月。痰液脱落细胞学检查镜下见成堆体积大的细胞，细胞核大、深染，染色质粗，可见病理性核分裂象。这些细胞可能是","o":["中性粒细胞","淋巴细胞","癌细胞","鳞状上皮细胞","杯状细胞"],"a":2,"e":"细胞核大深染、染色质粗、核质比增高并出现病理性核分裂象，是恶性肿瘤细胞的细胞学特征，痰脱落细胞学即据此诊断肺癌。中性粒细胞以分叶核和颗粒为特点，见于化脓性炎；淋巴细胞核小而圆、胞质少；正常鳞状上皮细胞核小、染色质均匀；杯状细胞胞质含黏液空泡，均无病理性核分裂象"},{"q":"患者，男，23岁。24小时前因车祸引起左下肢胫骨及腓骨开放性、粉碎性骨折，入院清创固定后12小时，出现左小腿及左足青紫、肿胀，患者出现发热和全身不适。次日肿胀加剧，累及左大腿，伤口流出恶臭脓汁，伴有气泡，肿胀区按之有捻发音。左小腿的病变为","o":["干性坏疽","湿性坏疽","气性坏疽","液化性坏死","干酪样坏死"],"a":2,"e":"深达肌肉的开放性粉碎骨折合并产气荚膜杆菌等厌氧菌感染，坏死组织内产生大量气体，触之有捻发音，伴恶臭脓汁和全身中毒症状，为气性坏疽。干性坏疽见于动脉闭塞的肢体末端，干燥皱缩、界限清楚、无气体；湿性坏疽多发生于内脏或淤血水肿的肢体，有腐败而无捻发音；液化性坏死见于脑和化脓灶；干酪样坏死为结核的特征性坏死"},{"q":"患者，男，68岁。糖尿病史10年。近一年来左下肢行走后疼痛，休息后好转。近两个月左拇趾变黑，皱缩，知觉消失。此种坏死最可能是","o":["固缩坏死","干性坏疽","湿性坏疽","气性坏疽","液化性坏死"],"a":1,"e":"糖尿病下肢动脉硬化致慢性缺血，足趾变黑皱缩、知觉消失、与正常组织界限清楚，为缺血性凝固性坏死即干性坏疽。湿性坏疽发生在伴淤血水肿或腐败菌感染的部位，局部肿胀恶臭、界限不清；气性坏疽见于深部肌肉开放性创伤合并厌氧菌感染，按压有捻发音；固缩坏死不是病理学坏死类型；液化性坏死多见于脑梗死与脓肿"},{"q":"患者，男，73岁。面颊部发现一溃疡2年余。病理检查发现：癌巢由深染的基底细胞样癌细胞构成。该患者的病理诊断是","o":["脂肪瘤","乳头状腺癌","基底细胞癌","血管肉瘤","纤维肉瘤"],"a":2,"e":"老年人面部长期不愈的溃疡，癌巢由深染的基底细胞样癌细胞构成、周边细胞呈栅栏状排列，为基底细胞癌，生长缓慢、极少转移。脂肪瘤由成熟脂肪细胞构成、位于皮下；乳头状腺癌形成乳头状腺样结构，多见于胃肠道和甲状腺；血管肉瘤由异型内皮细胞构成血管样腔隙；纤维肉瘤由异型梭形纤维母细胞呈交织束状排列"},{"q":"患儿，男，4岁。于8月前来就诊。高热8小时，抽搐2小时，呕吐一次，体温40℃，血压46/18mmHg，昏睡状，面色苍白，腮腺不大，颈软，四肢紧张，肢冷，腱反射亢进， 皮肤呈花纹状，心肺腹未见异常，实验室检查：WBC：18×109/L，N：0.86，L：0.14, 粪便镜检：WBC：2～8/HP，应首选考虑诊断为","o":["流行性乙型脑炎","中毒性菌痢","腮腺炎脑炎","脑型疟疾","流行性脑脊髓膜炎"],"a":1,"e":"学龄前儿童突发高热、抽搐、面色苍白、肢冷、血压下降，而肠道症状轻微、粪检仅少量白细胞，符合中毒性菌痢，病变以全身微循环障碍和脑水肿为主。流行性乙型脑炎以高热、意识障碍和中枢性呼吸衰竭为主，休克少见；流行性脑脊髓膜炎有皮肤瘀点瘀斑和颈项强直，脑脊液呈化脓性；腮腺炎脑炎伴腮腺肿大；脑型疟疾有疟疾发作史及脾大"},{"q":"患者，男，48岁。20年吸烟史。8年前每当气候转凉便开始咳嗽，痰呈白色黏液样，至天气转暖后症状好转。近一年来咳嗽发作频繁，但痰量减少，为干咳少痰症状。其可能的原因是","o":["支气管扩张","支气管哮喘","长期慢性支气管炎引起支气管黏膜和腺体萎缩","肺癌广泛转移","肺气肿合并慢性肺心病"],"a":2,"e":"长期慢性支气管炎反复发作可使支气管黏膜和腺体萎缩，分泌物减少，故由咳白色黏液痰转为干咳少痰。支气管扩张以大量脓臭痰和反复咯血为特征；支气管哮喘表现为发作性呼气性呼吸困难和哮鸣音；肺癌广泛转移多有消瘦、咯血及恶病质；肺气肿合并肺心病出现桶状胸、气促和右心衰表现，均不以痰量减少为主要转归"},{"q":"某患者血氧检查结果是：动脉血氧分压50mmHg（正常为100mmHg），血氧容量20ml/dl（正常为20ml/dl），动脉血氧含量15ml/dl(正常为19ml/dl)，动-静脉氧含量差4ml/dl(正常为5ml/dl)。请问其缺氧类型是哪一种","o":["低张性缺氧","血液型缺氧","循环性缺氧","组织性缺氧","混合型缺氧"],"a":0,"e":"动脉血氧分压降至50mmHg，血氧容量正常而动脉血氧含量降低，动静脉氧含量差大致正常，属低张性缺氧，由外呼吸功能障碍致动脉血氧合不足。血液性缺氧是血红蛋白量或质异常，血氧容量下降而PaO2正常；循环性缺氧因灌注不足，动静脉氧含量差增大；组织性缺氧是细胞利用氧障碍，静脉血氧含量升高；混合型需两类以上指标同时异常"},{"q":"脑缺血后，局部增加的物质是","o":["糖原","葡萄糖","ATP","磷酸肌酸","乳酸"],"a":4,"e":"脑缺血时氧供中断，糖酵解增强，丙酮酸还原为乳酸并在局部蓄积，故乳酸升高。糖原和葡萄糖被大量消耗而减少；ATP生成减少，磷酸肌酸将其高能磷酸键转给ADP亦随之下降。后四者均为缺血后降低的物质，乳酸是唯一升高的代谢产物"},{"q":"患者，女，31岁，孕40周。分娩时出现阴道大量流血，注射催产素后仍流血不止。因病情恶化，抢救无效死亡。尸检发现双肺明显水肿、淤血及出血，大部分肺泡壁毛细血管内可见均质、红染的微血栓。其最可能的病理诊断是","o":["败血症","休克","DIC","羊水栓塞","心力衰竭"],"a":2,"e":"产后大出血并羊水入血激活凝血系统，肺毛细血管内广泛形成均质红染的纤维蛋白微血栓，伴肺水肿淤血出血，符合弥散性血管内凝血。羊水栓塞的诊断依据是肺血管内查见角化鳞状上皮、胎脂等羊水成分，单纯微血栓不足以判定；败血症需血培养阳性及化脓性病灶；休克为功能状态而非病理诊断；心力衰竭见心肌病变"},{"q":"一肾功能衰竭患者血气分析可见：pH 7.30，PaCO2 35mmHg，HCO3ˉ 17mmol/L，该酸碱平衡紊乱发生时，机体主要依靠的代偿模式为","o":["蛋白质缓冲系统的作用","肺的调节作用","细胞内外的离子交换","肾的调节作用","碳酸氢盐缓冲系统的作用"],"a":1,"e":"pH 7.30、HCO3⁻ 17mmol/L为代谢性酸中毒，PaCO2 35mmHg系通气增强所致，故主要代偿方式是肺的调节，通过加深加快呼吸排出二氧化碳。碳酸氢盐缓冲系统是血浆最主要的缓冲对，属即刻缓冲而非代偿；肾的调节起效慢，且该患者肾衰竭已丧失排氢保碱能力；细胞内外离子交换和蛋白质缓冲系统作用有限"},{"q":"患者，男，35岁。有亚急性重型肝炎病史。最近B超显示，肝脏体积缩小，脾脏肿大。患者可能的诊断是","o":["门脉性肝硬化","坏死后性肝硬化","血吸虫性肝硬化","淤血性肝硬化","胆汁性肝硬化"],"a":1,"e":"亚急性重型肝炎后肝细胞大片坏死、再生结节大小不等、纤维间隔宽窄不一，形成大结节型肝硬化，即坏死后性肝硬化，肝缩小、脾因门脉高压而肿大。门脉性肝硬化由轻型肝炎或酒精引起，结节小而均匀、间隔纤细；血吸虫性肝硬化有虫卵结节及干线型纤维化；淤血性肝硬化继发右心衰；胆汁性肝硬化伴胆汁淤积和胆管增生"},{"q":"患者，女，40岁。同房有接触性出血病史，阴道镜检查行宫颈活检，镜下见鳞状上皮层下部近2/3的细胞出现异型性，应诊断为","o":["CINI级","CINII级","CINIII级","宫颈浸润癌","宫颈原位癌"],"a":1,"e":"异型细胞占据上皮下近2/3、上1/3仍较成熟，符合CINⅡ级，相当于新分类中的HSIL。CINⅠ级异型细胞局限于下1/3；CINⅢ级异型细胞超过下2/3或达全层，包括原位癌；宫颈浸润癌须突破基底膜侵入间质；宫颈原位癌指全层异型而基底膜完整，属CINⅢ的范畴"},{"q":"患者，男，60岁。在常规体检中查出镜下血尿，CT检查发现右肾上极有一直径7cm的占位病变，该患者最可能患有的疾病是","o":["肾母细胞瘤","血管平滑肌脂肪瘤","肾细胞癌","肾结石","转移性癌"],"a":2,"e":"60岁男性无痛性镜下血尿，CT见肾上极7cm占位，符合肾细胞癌，多见于肾脏上、下极，透明细胞型占70%~80%。肾母细胞瘤见于儿童，体积大、生长快；血管平滑肌脂肪瘤为含脂肪的良性错构瘤，CT示负值密度；肾结石表现为高密度影伴肾绞痛；转移性癌多为双侧多发结节且有原发灶"},{"q":"在一例79岁老年男性的尸体剖验中，发现其双肾体积变小，包膜皱缩，表面细颗粒状，镜下见散在的肾小球纤维化和玻璃样变，肾小管萎缩伴间质纤维化，细小动脉壁增厚及玻璃样变。该患者生前肾功能检查正常，其肾脏改变最符合的诊断是","o":["糖尿病所致肾小球结节性硬化","过敏性间质性肾炎","慢性肾盂肾炎","良性高血压所致颗粒性固缩肾","肾小球肾炎所致颗粒性固缩肾"],"a":3,"e":"入球小动脉玻璃样变致肾小球缺血性硬化、相应肾小管萎缩、间质纤维化，双肾对称缩小、表面细颗粒状，为原发性颗粒性固缩肾；因病变呈灶性分布、残存肾单位代偿，生前肾功能可正常。肾小球肾炎所致固缩肾为弥漫性颗粒，多有肾炎史和肾功能损害；慢性肾盂肾炎瘢痕不对称、肾盂变形；糖尿病结节性硬化有K-W结节；过敏性间质性肾炎以间质炎症为主"},{"q":"患者，女，55岁。对称性手足关节疼痛不适、变形，查体发现皮下结节。取结节活检，镜下见中央为纤维素样坏死，周围呈栅状或放射状排列的上皮样细胞，外围为肉芽组织。该患者的诊断是","o":["类风湿性关节炎","系统性红斑狼疮","风湿性关节炎","炎性疾病","系统性硬化"],"a":0,"e":"类风湿小结中央为纤维蛋白样坏死，周围上皮样细胞呈栅栏状放射状排列，外围为肉芽组织，见于关节隆突及受压部位皮下，结合对称性手足小关节疼痛变形可诊断类风湿性关节炎。系统性红斑狼疮以面部红斑、肾小球及小血管纤维素样坏死为特点；风湿性关节炎侵犯膝踝肩腕等大关节、呈游走性，无类风湿小结；系统性硬化以皮肤及内脏纤维化为特征"},{"q":"患者，男，38岁。反复鼻塞3年。鼻腔镜示中鼻甲有一带蒂的肿物，表面光滑，灰红色，大小为2cm×2cm×1cm。镜下见黏膜上皮及腺体增生，间质水肿，血管扩张充血，有淋巴细胞浸润。该病变最可能是","o":["鼻炎","炎性息肉","炎性假瘤","乳头状瘤","腺瘤"],"a":1,"e":"鼻腔黏膜在慢性炎症长期刺激下，黏膜上皮与腺体增生、间质水肿、血管扩张充血并伴淋巴细胞浸润，形成带蒂的息肉状突起，即炎性息肉（鼻息肉）。炎性假瘤为成纤维细胞、肌纤维母细胞及炎细胞构成的瘤样团块；乳头状瘤为被覆上皮呈指状增生的真性肿瘤；腺瘤为腺上皮的良性肿瘤；鼻炎仅有黏膜炎症而无息肉形成"},{"q":"患者，女，52岁，阴道不规则出血，阴道镜检见子宫颈有菜花样肿物，表面出血坏死。最有可能的诊断是","o":["宫颈糜烂","宫颈息肉","宫颈癌","纳博特囊肿","宫颈肥大"],"a":2,"e":"中老年女性阴道不规则流血，宫颈菜花样肿物伴表面出血坏死，是宫颈浸润癌的典型大体表现，以鳞状细胞癌最多见。宫颈糜烂为柱状上皮异位形成的红色糜烂样区、表面光滑无肿块；宫颈息肉为带蒂的黏膜突起、质软；纳博特囊肿为腺管口阻塞形成的潴留囊肿；宫颈肥大由慢性炎症纤维增生所致，均无坏死菜花状肿块"},{"q":"一中年男子在进行健康检查时，X线检查发现右上肺有一直径3cm的圆形阴影，初步考虑肺结核球和支气管肺癌，二者鉴别最有效的方法是","o":["肿瘤标志物检测","痰检查结核杆菌","结节穿刺活检","病史和体格检查","胸部磁共振检查"],"a":2,"e":"肺结核球与周围型肺癌的鉴别最终依靠病理，穿刺活检获取组织行组织学检查，可明确有无癌细胞及干酪样坏死。肿瘤标志物缺乏特异性，仅作辅助；痰查抗酸杆菌阴性不能排除结核球；病史和体格检查对孤立性结节的鉴别价值有限；磁共振对肺内结节的分辨不如CT，且不能定性"},{"q":"一男性患者，60岁。20年前被诊断为慢性肝炎，治疗情况不详。近日来，患者出现烦躁不安、睡眠紊乱、记忆力减退，提示该患者可能出现了","o":["肝性脑病","肝硬化","慢性肝炎","肝衰竭","肝肾综合征"],"a":0,"e":"慢性肝病基础上出现烦躁、睡眠倒错、记忆力减退等神经精神症状，是肝功能衰竭致毒性代谢产物潴积引起的中枢神经系统功能紊乱，即肝性脑病。肝硬化是形态学诊断，本身不解释精神症状；慢性肝炎无此表现；肝衰竭以黄疸、凝血障碍、腹水为主；肝肾综合征表现为少尿、氮质血症，不以意识障碍为首发"},{"q":"患者，男，50岁。入院时体温39℃，自觉头痛、腰痛、眼眶痛。口腔黏膜、胸背、腋下出现大小不等的出血点或瘀斑。随着病情的发展，病人退烧，但症状反而加重，继而出现低血压、休克、少尿、无尿及严重出血等症状。应考虑诊断为","o":["伤寒","流行性出血热","泌尿道感染","中毒性休克","病毒性肺炎"],"a":1,"e":"发热伴头痛、腰痛、眼眶痛三痛及皮肤黏膜出血点，退热后症状反而加重并出现低血压休克、少尿无尿，是流行性出血热典型的五期经过和热退病重特点。伤寒为持续高热、相对缓脉、玫瑰疹；泌尿道感染有尿频尿急尿痛；中毒性休克为综合征而非独立疾病；病毒性肺炎以呼吸道症状为主，无肾损害和出血倾向"},{"q":"患者，女，40岁。近两年来经常腹泻，有便血史。体检：较消瘦，腹部膨隆，肝未触及，脾脏明显增大，下缘在肋缘下5cm。腹部移动性浊音（+），大便检查出虫卵。考虑诊断为","o":["丝虫病","血吸虫病","门脉性肝硬化","阿米巴病","细菌性痢疾"],"a":1,"e":"有疫水接触史，慢性腹泻便血、消瘦，肝未触及而脾明显肿大伴腹水，粪检见虫卵，符合血吸虫病所致窦前性门脉高压。丝虫病表现为淋巴管炎、象皮肿和乳糜尿；门脉性肝硬化多有肝炎或酗酒史、粪检无虫卵；阿米巴病以果酱样便和烧瓶状溃疡为特点；细菌性痢疾为黏液脓血便伴里急后重，不引起显著脾大"},{"q":"患者，男，78岁。患急性广泛前壁心肌梗死，入院后常出现夜间阵发性呼吸困难，心率120次/分，两肺底闻及湿性啰音，正确的诊断是急性心肌梗死伴有","o":["支气管哮喘发作","右心衰竭","左心衰竭","全心衰竭","急性心包填塞"],"a":2,"e":"急性前壁心肌梗死致左室收缩力下降，肺静脉压升高形成肺淤血，出现夜间阵发性呼吸困难、心率快、两肺底湿啰音，为急性左心衰竭。右心衰竭以体循环淤血为主，表现为颈静脉怒张、肝大和下肢水肿；全心衰竭兼有两侧体征；支气管哮喘有哮鸣音和过敏史；心包填塞见血压下降、心音遥远和奇脉"},{"q":"患者，男，35岁。间歇性腹泻脓血便二年，乙状结肠镜插入13cm处见到多处3～5mm大小边缘不整的溃疡，较深，溃疡面覆盖灰白色苔状物，肠壁因纤维组织增生、瘢痕形成而增厚变硬。该患者患哪种疾病可能性较大","o":["慢性细菌性痢疾","慢性肠阿米巴病","慢性非特异性溃疡性结肠炎","结肠癌","血吸虫病"],"a":1,"e":"溶组织内阿米巴在结肠形成口小底大、边缘潜行的烧瓶状溃疡，溃疡较深且间杂正常黏膜，反复发作后肠壁因纤维增生而增厚变硬，符合慢性肠阿米巴病。慢性菌痢溃疡浅表、黏膜弥漫充血并有假膜；溃疡性结肠炎病变连续、自直肠向上蔓延；结肠癌为隆起肿块或环形狭窄；血吸虫病以虫卵肉芽肿和息肉形成为主"},{"q":"患者，男，49岁。超声诊断肝脂肪变，其发生的原因中最不可能包括的是","o":["缺氧","慢性乙醇中毒","糖尿病","高血压","高脂饮食"],"a":3,"e":"肝脂肪变由脂质摄入过多、脂肪酸氧化障碍及脂蛋白合成不足引起，常见于高脂饮食、慢性乙醇中毒、糖尿病、肥胖和缺氧。乙醇使NADH/NAD比值升高促脂肪合成；糖尿病时脂肪动员增强；缺氧损伤肝细胞代谢。高血压主要引起细动脉玻璃样变和左心室肥大，不直接造成肝细胞脂质蓄积"},{"q":"死者，老年男性，尸检见肺组织内散在多个小实变区。病理诊断为小叶性肺炎，细支气管壁浸润的炎细胞应为","o":["中性粒细胞","嗜酸性粒细胞","淋巴细胞和浆细胞","巨噬细胞","多核巨细胞"],"a":0,"e":"小叶性肺炎由化脓性细菌引起，以细支气管为中心的肺泡腔内充满以中性粒细胞为主的炎性渗出物，故管壁浸润的炎细胞是中性粒细胞。嗜酸性粒细胞见于寄生虫和变态反应性疾病；淋巴细胞和浆细胞为主是慢性炎症和病毒性肺炎的特点；巨噬细胞见于肉芽肿和脂性肺炎；多核巨细胞见于结核等肉芽肿性炎"},{"q":"患者，男，28岁。右上腹胀痛3个月，黄疸2周，有大量饮酒史。转氨酶轻度升高，B超显示肝脏轻度肿大。肝活检显示，肝细胞脂肪变性，门管区有炎症细胞浸润。患者可能的诊断是","o":["甲型病毒性肝炎","乙型病毒性肝炎","丙型病毒性肝炎","丁型病毒性肝炎","酒精性肝炎"],"a":4,"e":"长期大量饮酒后出现肝大、黄疸及转氨酶升高，肝细胞脂肪变性伴门管区炎症，符合酒精性肝炎，重者可见Mallory小体和中性粒细胞浸润。甲型肝炎为粪口传播的急性肝炎，无长期饮酒史；乙型、丙型、丁型须有相应病毒标志物阳性，炎细胞以淋巴细胞为主；酒精性肝病还可进展为脂肪肝和酒精性肝硬化"},{"q":"患者，女，13岁。近1周来高热、咳嗽。心率110次/分，偶发期前收缩。全血细胞分析示WBC：10×109/L，中性粒细胞0.56，淋巴细胞0.38。初步诊断为心肌炎。患者心肌间质最可能发生浸润的炎细胞是","o":["淋巴细胞和单核细胞","嗜酸性粒细胞和中性粒细胞","单核细胞和中性粒细胞","中性粒细胞和淋巴细胞","单核细胞和浆细胞"],"a":0,"e":"病毒性心肌炎以心肌间质水肿及淋巴细胞、单核细胞浸润为特点，心肌细胞呈灶性坏死，与感染后发病、白细胞轻度升高而中性粒细胞不高的表现一致。嗜酸性粒细胞浸润见于寄生虫病和过敏反应；中性粒细胞为主见于细菌性心肌炎和化脓性炎；浆细胞增多见于慢性炎症和骨髓瘤"},{"q":"16岁男性患者，被诊断为胰岛素依赖性糖尿病，其主要病变的细胞是","o":["胰岛D细胞","胰岛A细胞","胰岛B细胞","心肌细胞","肝细胞"],"a":2,"e":"胰岛素依赖型（1型）糖尿病为自身免疫性胰岛炎，选择性破坏胰岛B细胞，致其数目减少、胰岛素分泌绝对不足，需终身注射胰岛素。胰岛A细胞分泌胰高血糖素，D细胞分泌生长抑素，均非主要受损细胞；心肌细胞和肝细胞是并发症的靶器官损伤部位，不是原发病变所在"}];
